-- v3.1 — hardened after review.
--
-- ENGINE (verified against DF internals):
--   * Embark subset = entries in df.global.world.populations.all whose region back-ref
--     matches THIS embark's world regions (via getTileBiomeRgn). Editing their `quantity`
--     is LIVE (no reload). In-season -> a weight-scaled quantity, out-of-season -> 0.
--   * The region MASTER list (world_data.regions[i].population) is untouched by quantity
--     edits, so it is the "worldgen Default" baseline for the Default view / reset.
--   * Add-new (species not native to the embark) writes to the region master and REQUIRES a
--     reload (live insertion of a local_population is unsupported in DFHack — verified).
--
-- weight = relative ABUNDANCE (50 = default qty, 100 = 2x, 0 = muted).
-- season assignment is per-creature (config.assign[token] = array of season ints 0-3),
-- set by the preference matrix on "Set roster", hand-overridable by shift-click cycling.
--
-- After editing this file, just re-run `gui/seasonal-wildlife` — there is NO `reload`
-- command for scripts; reqscript auto-reloads on mtime (restart DFHack if it seems stale).
-- Install seasonal-wildlife.lua and gui/seasonal-wildlife.lua into dfhack-config/scripts/.
-- TEST ON A BACKUP SAVE.
-- =====================================================================================

local repeatUtil = require('repeat-util')

local MODULE     = 'seasonal-wildlife'
local CONFIG_KEY = 'seasonal-wildlife/config'
local SEASON     = { [0]='Spring', [1]='Summer', [2]='Autumn', [3]='Winter' }
local SEASON_SH  = { [0]='Sp', [1]='Su', [2]='Au', [3]='Wi' }
local SEASON_PEN = { [0]=COLOR_GREEN, [1]=COLOR_YELLOW, [2]=COLOR_BROWN, [3]=COLOR_LIGHTBLUE }
-- v6.4.0 (W2): a species' category is its ROLE -- predator or prey -- or vermin; where it lives is its habitat
-- (MODEL.HABITATS) and how big it is its size band, each read from the raws on its own. 'bird', 'apex' and
-- 'other' are gone: a raptor is a predator that flies, a megabeast is DF's (D8), and a creature with no diet
-- token is prey.
local CATEGORIES = { 'predator', 'prey', 'vermin' }
-- (LARGE_SIZE = 5000, the one-cut size split, retired in v6.4.0 for MODEL's three bands, D4.)
local LAYERS = { 'land', 'water', 'cavern', 'deep' }   -- ecosystem layers; see 'layers' below (v6.5.0: deep, D7)
local INNUMERABLE = 10000001   -- DF sentinel for uncountable populations; never touch these

-- Which season a creature belongs to is read from its CLIMATE RANGE: the whole set of
-- biomes its raws admit, not the handful it shares with this embark.
--
-- ⚠️ Two defects lived here until 2026-09-16, and S1 found them both. 'CONIFER' was a
-- cold hint, so FOREST_TEMPERATE_CONIFER -- the commonest temperate forest, and half of
-- region1 -- scored as arctic; and the scoring only ever looked at the embark's own
-- biomes, which on a single-climate map are identical for every creature and so carry no
-- seasonal signal at all. Together they put 2 of 38 tokens in Summer and made black bears
-- winter-only. Measured on region1: every in-embark creature shared exactly the same two
-- temperate biomes, while their full ranges differ sharply -- wolf reaches tundra and
-- taiga, kangaroo reaches three deserts, sparrow spans 23 biomes.
--
-- So each creature gets a climate lean in [-1, +1]:
--     lean = (hot biomes - cold biomes) / (hot + cold + mild)
-- and the roster is cut by RANK within this embark's own pool, not by an absolute
-- threshold. Vanilla's biome lists skew hot (26 of region1's 38 lean positive), so fixed
-- cut-offs would crowd summer and starve winter on almost every map; terciles balance
-- whatever mix the embark actually has. The coldest third are the winter visitors, the
-- warmest third the summer visitors, and the middle third are residents all year.
local COLD_BIOMES = { MOUNTAIN=true, GLACIER=true, TUNDRA=true, FOREST_TAIGA=true, OCEAN_ARCTIC=true }
local HOT_HINTS   = { 'TROPICAL', 'DESERT', 'MANGROVE' }
local MILD_HINTS  = { 'TEMPERATE' }
local SEASON_SETS = {   -- Sp=0 Su=1 Au=2 Wi=3
    cold = { 2, 3 },            -- arrives as it cools, gone by spring
    mild = { 0, 1, 2, 3 },      -- resident: the backbone the visitors rotate around
    hot  = { 0, 1 },            -- arrives as it warms
}
-- (SEASON_FLOOR, the thin-season top-up, retired in v6.3.0 with the quartered matrix.)

--========================================================================================
-- utils
--========================================================================================

local function contains_any(s, list)
    for _, x in ipairs(list) do if s:find(x, 1, true) then return true end end
    return false
end
local function set_from_list(t) local s = {}; for _, v in ipairs(t or {}) do s[v] = true end; return s end
local function keys_sorted(t) local o = {}; for k in pairs(t) do o[#o+1] = k end; table.sort(o); return o end
local function copy_list(t) local o = {}; for _, v in ipairs(t) do o[#o+1] = v end; return o end
local TICKS_PER_DAY, TICKS_PER_YEAR = 1200, 403200
local function absTick() return df.global.cur_year * TICKS_PER_YEAR + df.global.cur_year_tick end
local function abbrevBiome(id)
    local nm, parts = df.biome_type[id] or ('#'..id), {}
    for p in nm:gmatch('[^_]+') do parts[#parts+1] = p:sub(1, 3) end
    return table.concat(parts, '.')
end
local rng = dfhack.random.new()
-- Fisher-Yates in-place shuffle; no builtin shuffle exists in DFHack Lua.
-- rng:random(i) returns an integer in [0, i), so j lands in [1, i].
local function shuffle(t)
    for i = #t, 2, -1 do
        local j = rng:random(i) + 1
        t[i], t[j] = t[j], t[i]
    end
    return t
end

--========================================================================================
-- config (per-fort). loadConfig SANITIZES: it rebuilds a clean config and discards any
-- stale/foreign keys, so no legacy table with mixed number/string keys can ever reach the
-- JSON persister (that was the "key 0 exists both as string and number" crash).
--========================================================================================

local function deepcopy(v)
    if type(v) ~= 'table' then return v end
    local out = {}
    for k, x in pairs(v) do out[k] = deepcopy(x) end
    return out
end
-- v6.3.0 (W7, alpha 1): the configuration is held in memory. Decoding it from site data cost ~65 ms a
-- call on the trial fort, and every job, tab and verb called it. CACHE.cfg is the sanitized copy as last
-- read or saved; loadConfig hands out a deep copy (callers edit what they get before saving), saveConfig
-- replaces it, and a map load or unload clears it. CACHE.ver counts saves so derived caches know when
-- the roster changed.
-- ⚠️ ONE CACHE FOR EVERY COPY OF THIS SCRIPT. DFHack runs a console verb in a copy of the script of its own,
-- and the window and the scheduled jobs can hold others; a cache kept per copy let the jobs go on reading a
-- configuration the window or the console had since changed. X1 found it (26 Sep): the jobs' timing table
-- was empty in the copy the probe read. So the cache lives in one table in DFHack's global environment,
-- keyed by release so a deploy starts clean.
local CACHE = rawget(_G, '__seasonal_wildlife_cache')
if not CACHE or CACHE.release ~= '7.1.0' then
    CACHE = { release = '7.1.0', cfg = nil, ver = 0, regionNum = setmetatable({}, { __mode = 'k' }),
              class = {}, climate = {}, rawBiomes = {},   -- per creature raw, once per loaded world (raws reload with it)
              ecoDone = {}, ecoRuns = 0, predset = nil, fuseStats = {}, trickle = { raws = nil, season = nil } }
    rawset(_G, '__seasonal_wildlife_cache', CACHE)
end
-- v7.1 (Alpha Four 3.8): cave entries' wider region set; a cache made by an earlier 7.1.0 deploy lacks it, so it also
-- drops the cached region set once to rebuild it with the cave tiles
if not CACHE.caveNum then CACHE.caveNum = setmetatable({}, { __mode = 'k' }); CACHE.region = nil end
-- v7.0.0 (user, 30 Sep 2026): one table for the v7 work, because the main chunk is at Lua's 200-local limit.
-- Its functions are defined further down, each beside the code it changes; callers reach them through V7.
local V7 = {}
-- v7.1 (perf stream, R48/R55; docs/v7.1/perf.md): performance switches. Each legacy_* flag puts one change back on the
-- v7.0 path (correctness first: a new path that misbehaves is one verb away from the old one). Defined here so
-- defaultConfig can read the defaults; the functions are in the PERF block beside CACHE.drop.
V7.PERF = { DEF = { stagger = true, kb = true, overlay_ms = 250, undo_persist = 50, persist_transient = false,
                    events = true, events_freq = 100, rescan_ticks = 6000, slice = true, slice_ms = 20, forEachTile = true,
                    legacy_class = false, legacy_groups = false, legacy_undo = false, legacy_cfg = false, legacy_overlay = false,
                    legacy_census = false, legacy_live = false, legacy_pool = false, legacy_survey = false, legacy_scav = false,
                    legacy_json = false },   -- a4fix perf: legacy_json = DFHack's encoder (legacy_draw went with the prey seed, v7.1-place)
            NUM = { overlay_ms = { 0, 60000 }, undo_persist = { 1, 50 }, events_freq = { 1, 1200 }, rescan_ticks = { 300, 100000 },
                    slice_ms = { 2, 200 } } }
function V7.perfDefaults() local d = {}; for k, v in pairs(V7.PERF.DEF) do d[k] = v end; return d end
function V7.perfSanitize(c, raw)
    local r = type(raw.perf) == 'table' and raw.perf or {}
    for k, d in pairs(V7.PERF.DEF) do
        local v, lim = r[k], V7.PERF.NUM[k]
        if type(d) == 'boolean' and type(v) == 'boolean' then c.perf[k] = v
        elseif type(d) == 'number' and type(v) == 'number' and lim and v >= lim[1] and v <= lim[2] then c.perf[k] = math.floor(v) end
    end
end
function V7.PERF.on(k)   -- a perf switch from the cached config, else its default (jobs, hot loops: no copy)
    local p = CACHE.cfg and CACHE.cfg.perf
    local v = p and p[k]
    if v == nil then v = V7.PERF.DEF[k] end
    return v
end
function V7.on(cfg, k)   -- a v7 switch from this config, or from the cached one when a caller holds none
    local v = (cfg or CACHE.cfg or {}).v7
    return v ~= nil and v[k] or nil
end
-- v7.1 (aquarium stream; docs/v7.1/aquarium.md): the Aquarium's switches. The overlays and the graphics-mod installer live
-- in scripts/seasonal-wildlife-aquarium.lua and -aquarium-gfx.lua; the engine keeps only the keys, their sanitiser and
-- the verb (V7.AQ.verb, beside V7.CLI), so the console, the Panel and the browser set them through the one config.
V7.AQ = { DEF = { enabled = true, lens = false, depth = 4, fade = 0.7, schools = true, color = 'level', legend = false,
                  legend_rows = 8, waves = 'auto', surf = true, foam = true, veil = false, scan_hz = 4, budget_ms = 2,
                  trip_frames = 30, marks = 400, preset = 'aquarium',
                  bed = 'auto', bed_depth = 8, bed_tint = 0.6, bed_river = 'pebbles', bed_lift = true, bed_absorb = 1,   -- v7.1-bed
                  bed_material = 'sand-mud', bed_below = true,   -- v7.1-bed v1: sand / mud beds, creatures below the view
                  bed_river_mud = true,   -- v7.1-bed round 6: rivers drawn as mud under water over the baked sand
                  streaks = true, streaks_layer = 'top', shimmer = true, shimmer_depth = 2 },   -- v7.1-waves: moving water
          NUM = { depth = { 1, 8, true }, fade = { 0.3, 1 }, legend_rows = { 3, 16, true }, scan_hz = { 1, 10, true },
                  budget_ms = { 1, 20 }, trip_frames = { 5, 600, true }, marks = { 50, 3000, true },
                  bed_depth = { 1, 16, true }, bed_tint = { 0, 1 }, bed_absorb = { 0, 2 }, shimmer_depth = { 1, 3, true } },
          ENUM = { color = { 'level', 'kind', 'group' }, waves = { 'auto', 'on', 'off' },
                   preset = { 'vanilla', 'subtle', 'aquarium', 'clear', 'shallows', 'custom' },
                   bed = { 'auto', 'on', 'off' }, bed_river = { 'pebbles', 'floor', 'df' }, bed_material = { 'sand-mud', 'auto' }, streaks_layer = { 'top', 'under' } },
          ALPHA = { 150, 140, 130, 120, 110, 100, 90 } }
function V7.aqDefaults()
    local d = {}
    for k, v in pairs(V7.AQ.DEF) do d[k] = v end
    d.alpha = {}
    for i, v in ipairs(V7.AQ.ALPHA) do d.alpha[i] = v end
    return d
end
function V7.aqSanitize(c, raw)
    local r = type(raw.aquarium) == 'table' and raw.aquarium or {}
    local a = c.aquarium
    for k, d in pairs(V7.AQ.DEF) do
        local v, lim, opts = r[k], V7.AQ.NUM[k], V7.AQ.ENUM[k]
        if type(d) == 'boolean' and type(v) == 'boolean' then a[k] = v
        elseif lim and type(v) == 'number' and v >= lim[1] and v <= lim[2] then a[k] = lim[3] and math.floor(v) or v
        elseif opts and type(v) == 'string' then for _, o in ipairs(opts) do if o == v then a[k] = v end end end
    end
    if type(r.alpha) == 'table' then
        for i = 1, 7 do local v = r.alpha[i]; if type(v) == 'number' and v >= 0 and v <= 255 then a.alpha[i] = math.floor(v) end end
    end
end
-- v7.1 (groups stream): the groups scheduler's v7.1 work lives in V7.GRP (the main chunk has no local to spare).
-- The table is made here so the loader can sanitise its keys; its functions are defined beside the scheduler.
V7.GRP = { PRIOR = { land = 34500, water = 27000, cavern = 30000 }, BODIES = { 'ocean', 'lake', 'river', 'pool' },
           DEPTHS = { 0, 1, 2 }, TRIM_COUNTDOWN = 10, ADOPT_EVERY = 1200,
           POD = { ORCA = true, NARWHAL = true, SPERM_WHALE = true },
           PANICS = { herd = true, pack = true, school = true, pod = true } }
-- Sanitise the v7.1 group keys of a saved config and migrate a pre-v7.1 one once (raw.limits.mode absent):
--   R7  layer_groups is always on (per-layer counting cannot be turned off); a player's old explicit land number
--       (`limits land groups N`, auto=false) becomes the single fixed cap on every layer, else the map-size formula
--   R29 seasons_own is the tool's deal: forced on once at migration
--   R45 the water ceiling's old default (12 animals) is a hard cap: migrated to 0 (none)
--   R44 the cavern cap is universal: cavern_cap (default 5); the old cavern_max (2) is not carried over
function V7.grpSanitize(c, raw)
    local rg, rl = type(raw.groups) == 'table' and raw.groups or {}, type(raw.limits) == 'table' and raw.limits or {}
    local g, L = c.groups, c.limits
    for _, k in ipairs({ 'adaptive', 'cavern_hold_shared', 'cavern_hold_mix', 'cavern_trim', 'cavern_trim_gated', 'natives_cavern', 'natives_land', 'seeded_water',
                         'panic', 'panic_flocks', 'reelect_after_panic', 'sync_countdown' }) do
        if type(rg[k]) == 'boolean' then g[k] = rg[k] end
    end
    for _, k in ipairs({ 'w_prior_land', 'w_prior_water', 'w_prior_cavern', 'cavern_cap', 'cavern_trim_days', 'panic_days',
                         'panic_tiles', 'follow_pod' }) do
        if type(rg[k]) == 'number' and rg[k] >= 1 then g[k] = math.floor(rg[k]) end
    end
    if type(rg.apcap) == 'number' and rg.apcap >= 0 then g.apcap = math.floor(rg.apcap) end   -- 0 = off
    for k, r in pairs({ target_band = { 0, 10 }, catchup = { 0, 10 }, gap_jitter = { 0, 0.9 }, gap_floor_days = { 0.1, 30 }, w_alpha = { 0.01, 1 } }) do
        if type(rg[k]) == 'number' and rg[k] >= r[1] and rg[k] <= r[2] then g[k] = rg[k] end
    end
    if rg.cavern_hold == 'any' or rg.cavern_hold == 'all' or rg.cavern_hold == 'off' then g.cavern_hold = rg.cavern_hold end
    if rg.panic_mode == 'scatter' or rg.panic_mode == 'edge' then g.panic_mode = rg.panic_mode end
    if rl.mode == 'formula' or rl.mode == 'fixed' then L.mode = rl.mode end
    if type(rl.fixed) == 'number' and rl.fixed >= 1 then L.fixed = math.floor(rl.fixed) end
    if rl.mode == nil then   -- a fresh config, or a saved one from before v7.1: migrate once
        local land = type(rl.land) == 'table' and rl.land or nil
        if land and land.auto == false and type(land.groups) == 'number' and land.groups >= 1 then L.mode, L.fixed = 'fixed', math.floor(land.groups) end
        if L.water.ceiling == 12 then L.water.ceiling = 0 end   -- the old default (also what a pre-v6.5 water target migrates to)
        c.v7.seasons_own = true
        if next(raw) ~= nil then c.migrated_v71 = true end
    end
    for _, l in ipairs({ 'land', 'water', 'cavern' }) do L[l].auto = true end   -- R7: no per-layer on/off; the mode decides
    c.v7.layer_groups = true
    g.cavern_max = g.cavern_cap   -- the field older readers (the window's Overview) still print
end
