             perf=V7.perfDefaults(),         -- v7.1 (perf stream, R48/R55): caches, stagger, census, legacy_* fallbacks
             aquarium=V7.aqDefaults(),       -- v7.1 (aquarium stream): the lens, legend, waves, veil and the mod's preset
             allow={}, weight={}, assign={}, expanded={}, default_snapshot={}, why={},
             realm='' }   -- v7.0.0 (item 21): '' = unset, 'auto' = pick from the embark's own species, or a realm code
end

local function sanitizeStrMap(raw, valtype)
    local out = {}
    if type(raw) == 'table' then
        for k, v in pairs(raw) do if type(k) == 'string' and type(v) == valtype then out[k] = v end end
    end
    return out
end
local function sanitizeAssign(raw)
    local out = {}
    if type(raw) == 'table' then
        for token, arr in pairs(raw) do
            if type(token) == 'string' and type(arr) == 'table' then
                local seasons, seen = {}, {}
                for _, v in ipairs(arr) do
                    v = tonumber(v)
                    if v and v >= 0 and v <= 3 and not seen[v] then seen[v] = true; seasons[#seasons+1] = v end
                end
                table.sort(seasons)
                if #seasons > 0 then out[token] = seasons end
            end
        end
    end
    return out
end
local function loadConfigRaw()
    local raw = dfhack.persistent.getSiteData(CONFIG_KEY, nil) or {}
    local c = defaultConfig()
    if type(raw.enabled) == 'boolean' then c.enabled = raw.enabled end
    if type(raw.initialized) == 'boolean' then c.initialized = raw.initialized end
    if type(raw.in_season_qty) == 'number' then c.in_season_qty = raw.in_season_qty end
    c.allow            = sanitizeStrMap(raw.allow, 'boolean')
    c.weight           = sanitizeStrMap(raw.weight, 'number')
    c.why              = sanitizeStrMap(raw.why, 'string')   -- v5.10.5: the reason behind each allow/season state
    c.expanded         = sanitizeStrMap(raw.expanded, 'boolean')
    c.default_snapshot = sanitizeStrMap(raw.default_snapshot, 'number')
    c.assign           = sanitizeAssign(raw.assign)
    -- v6.3.0 (D8, 26 Sep): only natural wildlife is managed. Demons and the rest of the underworld, megabeasts,
    -- titans, forgotten beasts, night creatures and mythic creatures are DF's own; a saved class switch that
    -- turned one of them on is ignored, and they are not shown as controls.
    if type(raw.targets) == 'table' then
        for _, l in ipairs(LAYERS) do
            if type(raw.targets[l]) == 'table' then
                for k, v in pairs(raw.targets[l]) do if type(k) == 'string' and type(v) == 'number' and v >= 0 then c.targets[l][k] = math.floor(v) end end
            end
        end
    end
    V7.irrSanitize(c, raw)   -- v7.1 (irruption stream): IRRUPT v2 keys; a v6.1-v7.0 irruption config migrates once
    if type(raw.patterns) == 'table' then   -- v5.10.0
        for _, l in ipairs{ 'land', 'cavern', 'water' } do
            local v = raw.patterns[l]
            if v == 'steady' or v == 'burst' or v == 'trickle' or v == 'dawn' or v == 'follow' then c.patterns[l] = v end
        end
    end
    c.class_override = sanitizeStrMap(raw.class_override, 'string')
    c.habitat_override = sanitizeStrMap(raw.habitat_override, 'string')   -- v6.4.0 (W2)
    c.role_override = sanitizeStrMap(raw.role_override, 'string')
    if type(raw.groups) == 'table' then
        local g = raw.groups
        if type(g.enabled) == 'boolean' then c.groups.enabled = g.enabled end
        if type(g.coupling) == 'boolean' then c.groups.coupling = g.coupling end
        if type(g.piggyback) == 'boolean' and g.coupling == nil then c.groups.coupling = g.piggyback end  -- v5.4/5.5 configs
        if type(g.pack) == 'number' and g.pack >= 0 then c.groups.pack = math.floor(g.pack) end
        if type(g.cohesion) == 'boolean' then c.groups.cohesion = g.cohesion end
        if type(g.cavern) == 'boolean' then c.groups.cavern = g.cavern end                                  -- v5.9.1
        if type(g.cavern_max) == 'number' and g.cavern_max >= 1 then c.groups.cavern_max = math.floor(g.cavern_max) end
        for _, k in ipairs{ 'follow_herd', 'follow_pack', 'follow_flock', 'follow_school', 'stuck_ticks' } do
            if type(g[k]) == 'number' and g[k] >= 1 then c.groups[k] = math.floor(g[k]) end
        end
        for _, k in ipairs{ 'max_concurrent', 'gap_min_days', 'gap_max_days' } do
            if type(g[k]) == 'number' and g[k] >= 1 then c.groups[k] = math.floor(g[k]) end
        end
    end
    if type(raw.layers) == 'table' then
        for _, l in ipairs(LAYERS) do if type(raw.layers[l]) == 'boolean' then c.layers[l] = raw.layers[l] end end
    end
    if type(raw.water) == 'table' then
        local w = raw.water
        if type(w.enabled) == 'boolean' then c.water.enabled = w.enabled end
        for _, k in ipairs{ 'target', 'cadence', 'countdown' } do
            if type(w[k]) == 'number' and w[k] >= 1 then c.water[k] = math.floor(w[k]) end
        end
    end
    if type(raw.cavern) == 'table' then
        if type(raw.cavern.enabled) == 'boolean' then c.cavern.enabled = raw.cavern.enabled end
        for _, k in ipairs{ 'cadence', 'countdown' } do
            if type(raw.cavern[k]) == 'number' and raw.cavern[k] >= 1 then c.cavern[k] = math.floor(raw.cavern[k]) end
        end
    end
    if type(raw.quota) == 'table' then
        for _, l in ipairs(LAYERS) do
            if type(raw.quota[l]) == 'number' and raw.quota[l] >= 0 then c.quota[l] = math.floor(raw.quota[l]) end
        end
    end
    -- v6.5.0 (W4, Q6): limits; an older config's quota, max_concurrent, cavern_max and water target migrate once
    local L = type(raw.limits) == 'table' and raw.limits or nil
    for _, l in ipairs({ 'land', 'water', 'cavern' }) do
        local src = L and type(L[l]) == 'table' and L[l] or {}
        for _, k in ipairs({ 'groups', 'ceiling' }) do
            if type(src[k]) == 'number' and src[k] >= 0 then c.limits[l][k] = math.floor(src[k]) end
        end
        if type(src.auto) == 'boolean' then c.limits[l].auto = src.auto end   -- v6.9.0: groups at once = sqrt(embark) + 1
    end
    if not L then
        c.limits.land.groups = (c.quota.land > 0) and c.quota.land or c.groups.max_concurrent
        c.limits.cavern.groups = c.groups.cavern_max
        c.limits.water.ceiling = (c.quota.water > 0) and c.quota.water or c.water.target
        c.limits.cavern.ceiling = c.quota.cavern
    end
    c.limits.land.groups = math.max(1, c.limits.land.groups); c.limits.cavern.groups = math.max(1, c.limits.cavern.groups)
    c.limits.water.groups = math.max(1, c.limits.water.groups)
    -- the older fields the code still reads mirror the limits
    c.groups.max_concurrent, c.groups.cavern_max, c.water.target = c.limits.land.groups, c.limits.cavern.groups, math.max(1, c.limits.water.ceiling)
    c.quota = { land = 0, water = 0, cavern = c.limits.cavern.ceiling }
    if type(raw.hunting) == 'table' and type(raw.hunting.enabled) == 'boolean' then c.hunting.enabled = raw.hunting.enabled end
    if type(raw.alerts) == 'table' and type(raw.alerts.quiet_wildlife) == 'boolean' then c.alerts.quiet_wildlife = raw.alerts.quiet_wildlife end
    if type(raw.curious) == 'table' then
        c.curious.resident = sanitizeStrMap(raw.curious.resident, 'boolean')
        for k, d in pairs(c.curious) do   -- v7.1 (scav, R30): the reform keys, by the default's type
            local r = raw.curious[k]
            if k ~= 'resident' and type(d) == type(r) and (type(r) ~= 'number' or (r >= 0 and r <= 1e6))
               and (k ~= 'loot' or r == 'drop' or r == 'keep') then c.curious[k] = r end
        end
    end
    if type(raw.scavenge) == 'table' then
        if type(raw.scavenge.enabled) == 'boolean' then c.scavenge.enabled = raw.scavenge.enabled end
        if type(raw.scavenge.radius) == 'number' and raw.scavenge.radius >= 3 then c.scavenge.radius = math.floor(raw.scavenge.radius) end
        for k, d in pairs(c.scavenge) do   -- v7.1 (scav): natural-cadence keys by the default's type; SCAV.num clamps each
            local r = raw.scavenge[k]
            if k ~= 'enabled' and k ~= 'radius' and type(d) == type(r) and (type(r) ~= 'number' or (r >= 0 and r <= 1e6)) then c.scavenge[k] = r end
        end
    end
    if type(raw.exhaust) == 'table' then
        local x, rx = c.exhaust, raw.exhaust
        if type(rx.enabled) == 'boolean' then x.enabled = rx.enabled end
        if type(rx.stamp) == 'number' then x.stamp = math.floor(rx.stamp) end
        x.done = sanitizeStrMap(rx.done, 'boolean')
        if type(rx.promoted) == 'table' then
            for k, v in pairs(rx.promoted) do
                if type(k) == 'string' and type(v) == 'table' and type(v.season) == 'number' then
                    x.promoted[k] = { season = math.floor(v.season) % 4, for_key = type(v.for_key) == 'string' and v.for_key or '' }
                end
            end
        end
    end
    for _, f in ipairs({ 'group_size', 'stock', 'odds' }) do
        c[f] = {}
        if type(raw[f]) == 'table' then for k, v in pairs(raw[f]) do if type(k) == 'string' and type(v) == 'number' and v >= 0 then c[f][k] = math.floor(v) end end end
    end
    if type(raw.v7) == 'table' then   -- v7.0.0
        local r, v = raw.v7, c.v7
        for k, d in pairs(v) do
            if type(d) == 'boolean' and type(r[k]) == 'boolean' then v[k] = r[k]
            elseif type(d) == 'number' and type(r[k]) == 'number' and r[k] >= 0 and r[k] <= 10 then v[k] = r[k] end
        end
        if type(r.fisher_list) == 'table' then v.fisher_list = sanitizeStrMap(r.fisher_list, 'boolean') end
    end
    if type(raw.vermin_eat) == 'table' then   -- v7.1 (R21, R27): vermin eating; ranges match the verb's
        local r, v = raw.vermin_eat, c.vermin_eat
        for _, k in ipairs{ 'forage', 'log' } do if type(r[k]) == 'boolean' then v[k] = r[k] end end
        if r.source == 'rules' or r.source == 'edges' or r.source == 'both' then v.source = r.source end
        local NUM = { cadence = { 200, 50000 }, radius = { 3, 60 }, budget = { 1, 64 }, cooldown = { 0, 100000 } }
        for k, lim in pairs(NUM) do
            if type(r[k]) == 'number' and r[k] >= lim[1] and r[k] <= lim[2] then v[k] = math.floor(r[k]) end
        end
        for _, k in ipairs{ 'chance', 'colony', 'diversity' } do
            if type(r[k]) == 'number' and r[k] >= 0 and r[k] <= (k == 'diversity' and 10 or 1) then v[k] = r[k] end
        end
        if type(r.classes) == 'table' then
            for k in pairs(v.classes) do if type(r.classes[k]) == 'boolean' then v.classes[k] = r.classes[k] end end
        end
    end
    if type(raw.realm) == 'string' then c.realm = raw.realm end   -- v7.0.0 (item 21): '', 'auto', 'off' or a realm code
    V7.rosterLoad(raw, c)   -- v7.1 (roster stream): the roster block, sanitised over its defaults
    V7.extinctLoad(raw, c)  -- v7.1 (extinct stream): cfg.extinct, sanitised over its defaults
    if type(raw.ecology) == 'table' then
        local e = raw.ecology
        for _, k in ipairs{ 'enabled', 'livestock', 'nudge' } do if type(e[k]) == 'boolean' then c.ecology[k] = e[k] end end
        for _, k in ipairs{ 'radius', 'far_tiles', 'far_ticks', 'cadence' } do
            if type(e[k]) == 'number' and e[k] >= 1 then c.ecology[k] = math.floor(e[k]) end
        end
    end
    V7.sanitizeHunters(c, raw)   -- v7.1 (ecology stream)
    V7.grpSanitize(c, raw)   -- v7.1 (groups stream)
    V7.watSanitize(c, raw)   -- v7.1 (water stream)
    V7.perfSanitize(c, raw)  -- v7.1 (perf stream)
    V7.aqSanitize(c, raw)    -- v7.1 (aquarium stream)
    return c
end
-- v7.1 (ecology stream): cfg.hunters, read field by field into the defaults. A config saved before v7.1 has no `hunters`
-- table: its ecology cadence and nudge, and its fishers switch and list, are the v7.0 defaults it was saved with, so the
-- user's v7.1 rulings (R37 cadence 3,000, R38 nudge off, R43 bears fish) replace them once, when the value still reads
-- the old default. A player's own non-default choice is kept.
function V7.sanitizeHunters(c, raw)
    local h, r = c.hunters, raw.hunters
    if type(r) ~= 'table' then
        if c.ecology.cadence == 1500 then c.ecology.cadence = 3000 end
        if c.ecology.nudge == true then c.ecology.nudge = false end
        if c.v7.fishers == false then c.v7.fishers = true end
        local d = defaultConfig().v7.fisher_list
        for tok, on in pairs(c.v7.fisher_list) do if d[tok] == nil then d[tok] = on end end
        d.TIGER, d.JAGUAR, d.RACCOON = false, false, false
        c.v7.fisher_list = d
        return c
    end
    local function num(dst, src, k, lo, hi)
        local v = src[k]
        if type(v) == 'number' and v >= lo and v <= hi then dst[k] = v end
    end
    for _, k in ipairs{ 'pack_on', 'raptors', 'swim_scav' } do if type(r[k]) == 'boolean' then h[k] = r[k] end end
    num(h, r, 'pack_radius', 1, 60)
    if type(r.skills) == 'table' then
        for _, k in ipairs{ 'solo_apex', 'solo_meso', 'pack', 'pack_sneak', 'pack_bonus' } do num(h.skills, r.skills, k, 0, 20) end
        h.skills.species = {}
        if type(r.skills.species) == 'table' then
            for tok, v in pairs(r.skills.species) do
                if type(tok) == 'string' and type(v) == 'number' and v >= 0 and v <= 20 then h.skills.species[tok] = math.floor(v) end
            end
        end
    end
    if type(r.stoop) == 'table' then
        if type(r.stoop.enabled) == 'boolean' then h.stoop.enabled = r.stoop.enabled end
        num(h.stoop, r.stoop, 'cooldown', 100, 100000); num(h.stoop, r.stoop, 'range', 2, 200); num(h.stoop, r.stoop, 'max', 0, 50)
        num(h.stoop, r.stoop, 'chance', 0, 100); num(h.stoop, r.stoop, 'prey_ratio', 0.1, 50)
        if type(r.stoop.skip) == 'table' then h.stoop.skip = sanitizeStrMap(r.stoop.skip, 'boolean') end
    end
    if type(r.fish) == 'table' then
        if type(r.fish.run) == 'string' then h.fish.run = r.fish.run end
        if type(r.fish.polar) == 'boolean' then h.fish.polar = r.fish.polar end
        num(h.fish, r.fish, 'cooldown', 100, 100000); num(h.fish, r.fish, 'range', 2, 200); num(h.fish, r.fish, 'spot', 1, 20)
        num(h.fish, r.fish, 'lure', 0, 10); num(h.fish, r.fish, 'wait', 0, 100000)
    end
    if type(r.swim_scav_list) == 'table' then h.swim_scav_list = sanitizeStrMap(r.swim_scav_list, 'boolean') end
    h.cohesion = {}
    if type(r.cohesion) == 'table' then
        for tok, v in pairs(r.cohesion) do if type(tok) == 'string' and V7.COHESION_LABELS[v] then h.cohesion[tok] = v end end
    end
    return c
end
V7.COHESION_LABELS = { solitary = true, pack = true, herd = true, flock = true, school = true }
local function loadConfig()
    if not CACHE.cfg then
        CACHE.cfg = loadConfigRaw()
        if V7.sanitizeLocked then pcall(V7.sanitizeLocked, CACHE.cfg) end   -- v7.0.0 (defined with the classes)
        if V7.rosterSync then pcall(V7.rosterSync, CACHE.cfg) end           -- v7.1 (R53): PRED follows the config, once per load
    end
    return deepcopy(CACHE.cfg)
end
local function saveConfig(c)
    dfhack.persistent.saveSiteData(CONFIG_KEY, c)
    CACHE.cfg = deepcopy(c); CACHE.ver = CACHE.ver + 1
end

local function inSeason(cfg, token, s)
    for _, v in ipairs(cfg.assign[token] or {}) do if v == s then return true end end
    return false
end
local function setAssign(cfg, token, arr) table.sort(arr); cfg.assign[token] = arr end

--========================================================================================
-- LEDGER (v5.9.9): every write the tool makes, and why -- one readable line each
--========================================================================================
-- The design's "every automatic decision logs one line the user can read" and the v6.0 Ledger
-- tab both read this. A ring of LEDGER.CAP entries in the fort's persistent site data, oldest
-- first; each entry is {t=absolute tick, k=kind, l=layer or '', s=text}. Kinds: season, arrive,
-- wave, coupling, sweep, hold, dismiss, ecology, place, cavern, fuse, edit, build, undo, irruption (v7.1: LEDGER.KINDS). Adding never raises
-- (pcall) and costs one site-data write; nothing in a job path waits on it.
local LEDGER = { KEY = MODULE .. '/ledger', CAP = 300 }
-- v7.1 (fixes2): every kind the tool writes, in the order the Ledger tab's K filter cycles them (the v7.1 streams added
-- panic, lead, extinct, adopt, call, size and eco), and the old kinds a filter also matches: v7.1's roster
-- builder wrote 'roster' while the filter offered 'build', and it now writes 'build'. v7.1-place: 'strand' (the stranding
-- guard, removed) is gone; 'bodies' is the water body registry's line per rescan.
LEDGER.KINDS = { 'edit', 'undo', 'build', 'season', 'wave', 'arrive', 'adopt', 'place', 'call', 'hold', 'dismiss', 'sweep',
                 'coupling', 'ecology', 'eco', 'lead', 'panic', 'bodies', 'cavern', 'size', 'irruption', 'extinct', 'fuse' }
LEDGER.ALIAS = { build = { roster = true } }
-- v6.3.0 (W7): held in memory (CACHE.ledger) and written through; while a scheduled job runs (CACHE.ledgerBatch)
-- the write is made once at the end of the pass instead of once per line.
function LEDGER.load()
    if CACHE.ledger then return CACHE.ledger end
    local l = dfhack.persistent.getSiteData(LEDGER.KEY, nil) or {}
    l.entries = l.entries or {}
    l.count = l.count or 0
    CACHE.ledger = l
    return l
end
function LEDGER.flush()
    if CACHE.ledgerDirty and CACHE.ledger then dfhack.persistent.saveSiteData(LEDGER.KEY, CACHE.ledger) end
    CACHE.ledgerDirty = false
end
function LEDGER.add(kind, layer, fmt, ...)
    if not dfhack.isMapLoaded() then return end
    local n = select('#', ...)
    local args = { ... }
    local ok, err = pcall(function()
        local l = LEDGER.load()
        local text = n > 0 and fmt:format(table.unpack(args, 1, n)) or fmt
        l.entries[#l.entries + 1] = { t = absTick(), k = kind, l = layer or '', s = text }
        while #l.entries > LEDGER.CAP do table.remove(l.entries, 1) end
        l.count = l.count + 1
        CACHE.ledgerDirty = true
        if not CACHE.ledgerBatch then LEDGER.flush() end
    end)
    if not ok then dfhack.printerr('seasonal-wildlife ledger: ' .. tostring(err)) end
end
function LEDGER.stamp(t)   -- 'y5 Spring 14'
    local year, yt = math.floor(t / TICKS_PER_YEAR), t % TICKS_PER_YEAR
    local sl = TICKS_PER_YEAR / 4
    return ('y%d %s %d'):format(year, SEASON[math.floor(yt / sl)], math.floor((yt % sl) / TICKS_PER_DAY) + 1)
end
-- The newest `n` lines matching kind and/or layer, oldest first, and the total ever recorded.
function LEDGER.lines(n, kind, layer)
    local l, out = LEDGER.load(), {}
    for i = #l.entries, 1, -1 do
        local e = l.entries[i]
        if (not kind or e.k == kind or (LEDGER.ALIAS[kind] or {})[e.k]) and (not layer or e.l == layer) then
            table.insert(out, 1, ('%-14s %-9s %-7s %s'):format(LEDGER.stamp(e.t), e.k, e.l ~= '' and e.l or '-', e.s))
            if #out >= (n or 20) then break end
        end
    end
    return out, l.count
end
function LEDGER.clear() CACHE.ledger = { entries = {}, count = 0 }; dfhack.persistent.saveSiteData(LEDGER.KEY, CACHE.ledger) end

-- WHY (v5.10.5): the reason behind each species' state -- one string per key, written wherever the
-- allow or season state is written ('fill prey to 4', 'matrix: seasons', 'you: blocked', 'vermin flies
-- off', 'co-align', 'natural predators') with the date. The Roster's why column reads it; a reset
-- clears it, and a state with no record is explained from what the tool knows (whyFor, below).
-- UNDO (v5.11.4): a snapshot ring (ten deep until v6.5, fifty since), of everything the player can edit, taken by the window
-- before each write and by the `undo` verb's callers; `undo` restores the newest. Persisted beside
-- the ledger so it survives closing the window. The worldgen snapshot is never part of it.
local UNDO = { KEY = MODULE .. '/undo', CAP = 50,   -- v6.5.0 (W10, alpha 1 step 9.2): fifty deep, was ten
               FIELDS = { 'enabled', 'in_season_qty', 'layers', 'water', 'cavern', 'patterns', 'quota', 'groups', 'ecology',
                          'classes', 'class_override', 'allow', 'weight', 'assign', 'expanded', 'why', 'targets', 'habitat_override', 'role_override',
                          'limits', 'group_size', 'stock', 'odds', 'alerts', 'curious',
                          -- v7.1 (Alpha Four 1.13, 6.8, 6.13): the v7.1 settings. Without them `undo` of a roster, hunters,
                          -- extinct, irruption, vermin or scavenging edit said 'undid: ...' and restored nothing of it
                          'hunting', 'scavenge', 'vermin_eat', 'roster', 'extinct', 'irruption', 'hunters', 'v7', 'realm', 'perf' } }
-- v7.1 (perf, P2): the ring is held in the shared CACHE (CACHE.undo, dropped with the map) and written through compact,
-- newest perf.undo_persist snapshots (default 50 = all). Until v7.1 every window edit decoded the whole ring, appended
-- and re-encoded it pretty (about 50 ms on the host at depth 50), and the window's Undo label decoded it every frame.
-- perf legacy_undo on = read and write site data on every call, as before.
function UNDO.load()
    if not V7.PERF.on('legacy_undo') and CACHE.undo then return CACHE.undo end
    local u = dfhack.persistent.getSiteData(UNDO.KEY, nil) or {}
    u.ring = u.ring or {}
    if not V7.PERF.on('legacy_undo') then CACHE.undo = u end
    return u
end
function UNDO.save(u)
    if V7.PERF.on('legacy_undo') then CACHE.undo = nil; dfhack.persistent.saveSiteData(UNDO.KEY, u) return end
    CACHE.undo = u
    local keep = V7.PERF.on('undo_persist') or UNDO.CAP
    local rec = u
    if #u.ring > keep then
        rec = { ring = {} }
        for i = #u.ring - keep + 1, #u.ring do rec.ring[#rec.ring+1] = u.ring[i] end
    end
    V7.PERF.persist(UNDO.KEY, rec)
end
function UNDO.push(cfg, label)
    if not dfhack.isMapLoaded() then return end
    pcall(function()
        local u = UNDO.load()
        local snap = { t = absTick(), label = label or 'edit', cfg = {} }
        for _, f in ipairs(UNDO.FIELDS) do snap.cfg[f] = deepcopy(cfg[f]) end
        u.ring[#u.ring + 1] = snap
        while #u.ring > UNDO.CAP do table.remove(u.ring, 1) end
        UNDO.save(u)
    end)
end
-- Restore the newest snapshot into cfg (the caller saves). Returns the label undone, or nil.
function UNDO.pop(cfg)
    local u = UNDO.load()
    local snap = u.ring[#u.ring]
    if not snap then return nil end
    table.remove(u.ring)
    UNDO.save(u)
    for _, f in ipairs(UNDO.FIELDS) do if snap.cfg[f] ~= nil then cfg[f] = deepcopy(snap.cfg[f]) end end
    LEDGER.add('undo', '', 'undid: %s (from %s)', snap.label, LEDGER.stamp(snap.t))
    return snap.label, #u.ring
end
function UNDO.depth() return #UNDO.load().ring end
local function whySet(cfg, key, text)
    cfg.why = cfg.why or {}
    cfg.why[key] = dfhack.isMapLoaded() and (text .. ' @ ' .. LEDGER.stamp(absTick())) or text
end

--========================================================================================
-- biome detection
--========================================================================================

-- The region tiles DF draws wildlife from: the SITE RECORD's tiles (the site's
-- global mid-level-tile bounds divided by 16) PLUS the tile(s) the map blocks
-- name for their biome (dfhack.maps.getTileBiomeRgn). Both are sources.
--
-- ⚠️ v5.3 (2026-09-16, E9a and E4-E9bc on CTRL, DwarfCron harness). CTRL is a 4x4
-- wholly inside 29,20 by the site record. Of fifteen surface waves, twelve carried
-- 29,20 in the unit's own population reference and three carried 28,19 -- the
-- block-biome tile -- whose entries flipped `discovered` and were debited/refunded.
-- The entry edge did not choose the tile. Which rule picks between them is open
-- (E2 on SPLIT); until then the tool manages BOTH sets, which on region1 means the
-- 8,5 entries that v5.2 dropped are managed again. The v5.2 note below stays as
-- the record of why the site record is still the only reading of where the fort IS.
--
-- ⚠️ Bug 13 (2026-09-16). This used to walk every map block through
-- dfhack.maps.getTileBiomeRgn. On 53.16 that call returns the fort's tile
-- shifted by exactly (-1,-1) for every block sampled, on all three forts
-- checked (region1 at 9,6 -> 8,5; CTRL at 29,20 -> 28,19; SPLIT at 23..24,14
-- -> 22..23,13). Whether that is DF's block-level biome borrowing or an
-- offset in DFHack's region_offset decoding is unresolved; either way it
-- is not the answer to "which tiles is this fort on". The tool managed a
-- phantom neighbour tile's populations for months because of it, and the
-- wombat result in G4 was that phantom: its "other region" was never part of
-- the embark. biomeSet still collects what getTileBiomeRgn reports, because
-- creature ELIGIBILITY may depend on borrowed biomes and that is harmless.
-- v5.8.3: cached for the life of the loaded map (keyed on the site and the map's size). Eleven
-- callers, one of them daily.
-- v5.8.4: the block pass is decoded from memory, every block, no DFHack call. A block's biome tile
-- is its region_pos plus the 3x3 neighbour its region_offset[designation.biome] names -- exactly
-- what dfhack.maps.getTileBiomeRgn computes -- and it DOES change with depth: on CTRL 2,160 of
-- 16,704 blocks name 28:19 and the rest 29:20, mixed within a column. v5.8.3 sampled one block per
-- column and lost 28:19 for the hours it was deployed; this pass reads all of them in ~100 ms.
local function getEmbarkRegions()
    local key = ('%d:%d:%d:%d'):format(df.global.plotinfo.site_id, df.global.world.map.x_count,
                                        df.global.world.map.y_count, df.global.world.map.z_count)
    if CACHE.region and CACHE.region.key == key then return CACHE.region.regions, CACHE.region.biomes end   -- v6.3.0: shared
    local regionSet, biomeSet = {}, {}
    local site = df.world_site.find(df.global.plotinfo.site_id)
    if site then
        local x0, x1 = math.floor(site.global_min_x / 16), math.floor(site.global_max_x / 16)
        local y0, y1 = math.floor(site.global_min_y / 16), math.floor(site.global_max_y / 16)
        for rx = x0, x1 do
            for ry = y0, y1 do
                local ok, id = pcall(dfhack.maps.getBiomeType, rx, ry)
                if ok and id and id >= 0 then regionSet[rx .. ':' .. ry] = id; biomeSet[id] = true end
            end
        end
    end
    -- the block-biome tiles are draw sources too (v5.3); add them to the managed set
    local wd = df.global.world.world_data
    local WW, WH = wd.world_width, wd.world_height
    -- ⚠️ v6.3.0 (X1, 26 Sep): EVERY neighbour a block can name, not the one its first tile names. A block's
    -- tiles each carry a biome index 0-8 into region_offset, and different tiles of one block name different
    -- neighbours; reading only designation[0][0] missed tile 50:62 on the trial fort, and DF drew twenty cavies
    -- from its entry in X1 while every entry the tool managed was held at 0. Reading all nine offsets per
    -- block costs nine byte reads, not a walk of the block's 256 tiles (which took minutes, p10).
    local tiles = {}
    for _, block in ipairs(df.global.world.map.map_blocks) do
        local ro, bx, by = block.region_offset, block.region_pos.x, block.region_pos.y
        for o = 0, 8 do
            local off = ro[o]
            local rx = math.max(0, math.min(WW - 1, bx + (off % 3) - 1))
            local ry = math.max(0, math.min(WH - 1, by + (off // 3) - 1))
            tiles[rx * 65536 + ry] = true
        end
    end
    for k in pairs(tiles) do
        local rx, ry = k // 65536, k % 65536
        local ok, id = pcall(dfhack.maps.getBiomeType, rx, ry)
        if ok and id and id >= 0 then regionSet[rx .. ':' .. ry] = id; biomeSet[id] = true end
    end
    -- v6.3.0 (W7): the same tiles keyed by number, so the per-entry membership test in managedPop builds no
    -- string ('rx:ry' made a fresh string for each of 7,606 entries, every pass)
    local num = {}
    for k in pairs(regionSet) do local rx, ry = k:match('(%d+):(%d+)'); num[tonumber(rx) * 65536 + tonumber(ry)] = true end
    CACHE.regionNum[regionSet] = num
    -- v7.1 (Alpha Four 3.8, 2 Oct, RinghatchetsReady): DF draws CAVERN waves from the full 3x3 neighbourhood of every
    -- site region tile, not only the tiles a block's region_offset names. The block set held 6 of the 9 tiles around
    -- 169:172; troglodytes, a reacher, a troll and a green devourer came from entries on 168:173 and 170:173, and Spring
    -- brought rutherers and giant cave toads (Summer species) from the unmanaged copies while every managed copy was
    -- held at 0. Cave entries are judged against this wider set; surface entries keep the block set (X1: no leak).
    local cave = {}
    for k in pairs(num) do cave[k] = true end
    if site then
        for rx = math.floor(site.global_min_x / 16) - 1, math.floor(site.global_max_x / 16) + 1 do
            for ry = math.floor(site.global_min_y / 16) - 1, math.floor(site.global_max_y / 16) + 1 do
                if rx >= 0 and ry >= 0 and rx < WW and ry < WH then cave[rx * 65536 + ry] = true end
            end
        end
    end
    CACHE.caveNum[regionSet] = cave
    CACHE.region = { key = key, regions = regionSet, biomes = biomeSet }
    return regionSet, biomeSet
end

--========================================================================================
-- layers
--========================================================================================
-- A population entry's back-reference says which ecosystem layer it belongs to.
-- Surface land life has feature_idx=-1, cave_id=-1. River and lake life carries the
-- index of the outdoor water feature (feature_idx >= 0). Cavern life carries a
-- cave_id. The deep layers are INNUMERABLE and never managed. Verified on region1
-- 2026-09-16: BEAVER 650 / SNAPPING TURTLE 672 / FISH_STURGEON 416 at feat=0 --
-- countable river entries that the old surface-only test made invisible.
--
-- ⚠️ W1 (48,000 unpaused ticks, river present, water species isolated at 200), and then
-- E20/E26 over a full year: DF produces NO water-sourced arrivals at all, while land waves
-- come within 1,500 ticks whenever the gate is clear. A feature entry is read once, at
-- embark, and never again. So the data here -- quantities, seasons, the web, the Vermin
-- entries DF's fishing reads -- is real but inert on its own, and since v5.8 the WATER job
-- puts the animals in the water itself, by placement (addenda 46-48).
-- v6.5.0 (D7, 26 Sep): a cave entry below the three caverns -- the magma sea (layer_depth 3) and the underworld
-- (4) -- is the DEEP layer. Its natural species (magma crabs, fire imps if the raws call them natural) join the
-- roster there and are steered by frequency like the caverns; demons and the rest of the underworld are a
-- special class and stay DF's (D8). Depth per cave never changes while a world is loaded, so it is cached.
CACHE.depth = {}
function CACHE.caveDepth(cave_id)
    local d = CACHE.depth[cave_id]
    if d ~= nil then return d end
    local ok, r = pcall(function() return df.global.world.world_data.underground_regions[cave_id] end)
    d = (ok and r) and r.layer_depth or -1
    CACHE.depth[cave_id] = d
    return d
end
local function layerOf(pop)
    local r = pop.population
    if r.cave_id ~= -1 then return (CACHE.caveDepth(r.cave_id) <= 2) and 'cavern' or 'deep' end
    if r.feature_idx ~= -1 then return 'water' end
    return 'land'
end
-- Config keys stay plain tokens for land so every existing config still loads;
-- other layers prefix the token: 'water:BEAVER'.
local function keyFor(layer, token)
    if layer == 'land' then return token end
    return layer .. ':' .. token
end
local function enabledLayers(cfg)
    local out = {}
    for _, l in ipairs(LAYERS) do if cfg.layers[l] then out[l] = true end end
    return out
end

-- is this population entry an embark, countable animal/vermin in an enabled layer?
-- v6.3.0 (W7, alpha 1 R4): nothing here allocates. Six callers used to pass a table literal ({ water = true })
-- built afresh for every one of 7,606 entries, and the region test built a string per entry; on the trial
-- fort's 54 MB heap that garbage cost ~1.5 s a pass against 0-33 ms without it. Callers pass LAYER_SET.
local POP_TYPES = { Animal = true, Vermin = true, VerminInnumerable = true, ColonyInsect = true }
local LAYER_SET = { land = { land = true }, water = { water = true }, cavern = { cavern = true }, deep = { deep = true },
                    all = { land = true, water = true, cavern = true, deep = true } }
local function managedPop(pop, regionSet, layers)
    if not POP_TYPES[df.world_population_type[pop.type]] then return false end
    local r = pop.population
    local num = (r.cave_id >= 0 and CACHE.caveNum[regionSet]) or CACHE.regionNum[regionSet]
    if num then
        if not num[r.region_x * 65536 + r.region_y] then return false end
    elseif regionSet[r.region_x .. ':' .. r.region_y] == nil then return false end
    if pop.quantity_max >= INNUMERABLE then return false end   -- never touch uncountable clouds
    return (layers or LAYER_SET.land)[layerOf(pop)] == true
end

--========================================================================================
-- classification + size
--========================================================================================

-- Adult body volume. ⚠️ caste.body_size holds the SIZES and body_size_day the
-- AGES at which each size is reached; RESEARCH-NOTES had them the other way
-- round, and this read body_size_day -- so a wolf, an elk, a bobcat and a
-- grizzly all came back as 672 (days), and the large/small split that the whole
-- food web keys on was decided on ages. Verified live 2026-09-16: WOLF
-- body_size={400,2000,4000} body_size_day={0,336,672}. craw.adultsize carries
-- the same final value and is the fallback.
-- v6.4.1: DF stores these in units of 10 cm3 -- the wolf's raw reads BODY_SIZE 4000 / 20000 / 40000,
-- the lion's 200000, the hippo's 1500000 -- so the value is scaled back to the raw's cm3 here. The
-- food web's rules are ratios and did not move; the size bands (D4, set in cm3) put every creature
-- a band too low until this (validation 211308: lion and bull shark small, elephant and hippo medium).
local function adultSize(craw)
    local best = 0
    for _, caste in ipairs(craw.caste) do
        local v = caste.body_size
        if #v > 0 then best = math.max(best, v[#v - 1]) end
    end
    if best == 0 then best = craw.adultsize or 0 end
    return best * 10
end
-- No native marsupial/monotreme flag exists in DF; use a curated creature_id set
-- (extensible: we also honor a modded [CREATURE_CLASS:MARSUPIAL] / MONOTREME).
local MARSUPIAL_TOKENS = {
    KANGAROO=true, WALLABY=true, WALLAROO=true, KOALA=true, OPOSSUM=true, POSSUM=true,
    WOMBAT=true, BANDICOOT=true, QUOKKA=true, NUMBAT=true, BILBY=true, THYLACINE=true,
    PLATYPUS=true, ECHIDNA=true, SUGAR_GLIDER=true, CUSCUS=true, PADEMELON=true, QUOLL=true,
    TASMANIAN_DEVIL=true,
}
-- ⚠️ Indexing a df-flagarray with a name the enum does not define RAISES
-- ("Cannot read field BitArray<>.X: not found"), it does not return false. One
-- stale flag name therefore kills the whole tool rather than degrading one
-- test -- which is exactly what AQUATIC did on DF v0.53.15. Probe the name once
-- and cache the answer, so an unknown flag is simply absent.
local flagKnown = {}
local function casteFlagExists(craw, flag)
    local known = flagKnown[flag]
    if known ~= nil then return known end
    local caste = craw.caste[0]
    if not caste then return false end
    local ok = pcall(function() return caste.flags[flag] end)
    flagKnown[flag] = ok
    return ok
end
local function hasCasteFlag(craw, flag)
    if not casteFlagExists(craw, flag) then return false end
    for _, caste in ipairs(craw.caste) do if caste.flags[flag] then return true end end
    return false
end
-- v6.9.0: every caste carries the flag (BENIGN is read this way: a species hunts on a relation unless all of it is BENIGN)
local function allCasteFlag(craw, flag)
    if not casteFlagExists(craw, flag) then return false end
    for _, caste in ipairs(craw.caste) do if not caste.flags[flag] then return false end end
    return #craw.caste > 0
end
local function hasCreatureClass(craw, cls)
    for _, caste in ipairs(craw.caste) do
        for _, s in ipairs(caste.creature_class) do
            local v = (type(s) == 'string') and s or (s and s.value)
            if v == cls then return true end
        end
    end
    return false
end
local WATER_BIOME_PREFIXES = { 'OCEAN', 'POOL', 'LAKE', 'RIVER', 'SUBTERRANEAN_WATER' }
local function isWaterBiomeName(nm)
    for _, p in ipairs(WATER_BIOME_PREFIXES) do if nm:sub(1, #p) == p then return true end end
    return false
end
-- enum-index fallback so an unknown BIOME_<name> flag reads false instead of erroring
local function biomeFlag(craw, nm)
    local fi = df.creature_raw_flags['BIOME_' .. nm]
    if fi == nil then return false end
    return craw.flags[fi] or false
end
-- Water-only fallback: a creature whose eligible biomes are ALL water is aquatic even
-- without the caste flags (some water-only raws lack them).
local function allBiomesWater(craw)
    local any, allWater = false, true
    for i = df.biome_type._first_item, df.biome_type._last_item do
        local nm = df.biome_type[i]
        if nm and biomeFlag(craw, nm) then
            any = true
            if not isWaterBiomeName(nm) then allWater = false end
        end
    end
    return any and allWater
end
-- ⚠️ Flag names verified against df-structures on DF v0.53.15 / DFHack 53.15-r2.
-- RESEARCH-NOTES targeted 50.x/51.x and listed AQUATIC and UNDERSWIM as two
-- separate flags; the Great Reorganization of creature.h merged them into the
-- single AQUATIC_UNDERSWIM, and neither old name resolves any more. The other
-- three are unchanged. Both legacy names are kept in the list deliberately --
-- hasCasteFlag now ignores names the running DF does not define, so leaving
-- them costs nothing and keeps the tool working on older DFHack.
local AQUATIC_FLAGS = {
    'AQUATIC_UNDERSWIM',   -- 53.x
    'AQUATIC', 'UNDERSWIM', -- 50.x/51.x spellings, ignored where absent
    'CAN_BREATHE_WATER', 'CANNOT_BREATHE_AIR', 'IMMOBILE_LAND',
}
local function isAquatic(craw)
    for _, f in ipairs(AQUATIC_FLAGS) do
        if hasCasteFlag(craw, f) then return true end
    end
    return allBiomesWater(craw)
end
local function cladeOf(craw)
    if MARSUPIAL_TOKENS[craw.creature_id] then return 'marsupial' end
    if hasCreatureClass(craw, 'MARSUPIAL') or hasCreatureClass(craw, 'MONOTREME') then return 'marsupial' end
    if hasCreatureClass(craw, 'PLACENTAL_MAMMAL') or hasCreatureClass(craw, 'MAMMAL') then return 'placental' end
    return 'other'
end

--========================================================================================
-- ecology classes
--========================================================================================
-- Not one flag, a class. Derived from flags DF itself needs to run the creature, so a
-- modded creature classifies to the extent DF can use it; what cannot be classified is
-- listed for the user with the reasons, and their answer persists in class_override.
-- The tool manages NATURAL by default; every other class is an explicit opt-in, and the
-- food web never pairs across classes. Non-natural behaviour is preserved by
-- construction: nothing here addresses a unit, an INNUMERABLE entry, or a class the
-- user has not enabled.
local ECOLOGY_CLASSES = { 'natural', 'mythic', 'mega', 'night', 'unliving', 'generated', 'unclassified' }
-- `#df.biome_type` is 0 under DFHack's enum wrapper (found 2026-09-16: every animal
-- came back 'no BIOME flags' and locked); walk _first_item.._last_item instead.
local function hasAnyBiome(craw)
    for i = df.biome_type._first_item, df.biome_type._last_item do
        local nm = df.biome_type[i]
        if nm and biomeFlag(craw, nm) then return true end
    end
    return false
end
-- returns class, reasons (a short list of the flags that decided it)
-- v7.1 (perf, P1): a pure function of the raw, so it is memoized per world in CACHE.ecoClass (dropped on world unload
-- by CACHE.drop). Up to ten caste walks per call ran for every unit, two or three times per ecology pass (V7.natural,
-- V7.managedWild). The reasons list is shared and read-only. perf legacy_class on = no memo.
local function ecologyClass(craw)
    if V7.PERF.on('legacy_class') then return V7.ecologyClassRaw(craw) end
    local m = CACHE.ecoClass
    if not m then m = {}; CACHE.ecoClass = m end
    local id = craw.creature_id
    local h = m[id]
    if not h then local c, w = V7.ecologyClassRaw(craw); h = { c, w }; m[id] = h end
    return h[1], h[2]
end
function V7.ecologyClassRaw(craw)
    local f = craw.flags
    local why = {}
    if f.GENERATED then return 'generated', { 'GENERATED' } end
    if hasCasteFlag(craw, 'MEGABEAST') then why[#why+1] = 'MEGABEAST' end
    if hasCasteFlag(craw, 'SEMIMEGABEAST') then why[#why+1] = 'SEMIMEGABEAST' end
    if hasCasteFlag(craw, 'TITAN') then why[#why+1] = 'TITAN' end
    if #why > 0 then return 'mega', why end
    for _, n in ipairs{ 'NIGHT_CREATURE_HUNTER', 'NIGHT_CREATURE_BOGEYMAN', 'NIGHT_CREATURE_ANY', 'NIGHT_CREATURE_EXPERIMENTER' } do
        if hasCasteFlag(craw, n) then why[#why+1] = n end
    end
    if #why > 0 then return 'night', why end
    if hasCasteFlag(craw, 'NOT_LIVING') then why[#why+1] = 'NOT_LIVING' end
    if hasCasteFlag(craw, 'NO_EAT') and hasCasteFlag(craw, 'NO_DRINK') and not hasCasteFlag(craw, 'GRAZER') and not hasCasteFlag(craw, 'CARNIVORE') then
        why[#why+1] = 'NO_EAT+NO_DRINK'
    end
    if #why > 0 then return 'unliving', why end
    if f.FANCIFUL then why[#why+1] = 'FANCIFUL' end
    if f.GOOD then why[#why+1] = 'GOOD' end
    if f.EVIL then why[#why+1] = 'EVIL' end
    if #why > 0 then return 'mythic', why end
    if adultSize(craw) <= 0 then why[#why+1] = 'no body size' end
    if not hasAnyBiome(craw) then why[#why+1] = 'no BIOME flags' end
    if #why > 0 then return 'unclassified', why end
    return 'natural', { 'biome flags + body size, none of the special flags' }
end
-- v7.0.0 (user, 30 Sep 2026: "The tool should handle all biome-region combinations, including everything across the
-- Savage-Calm axis and Good-Evil axis"). DF places GOOD and EVIL wildlife by the region's alignment, outside the
-- normal pick (wiki, Creature_token: they "ignore the epicenter distribution system"). The embark's alignment is read
-- from every region tile the fort draws from (getEmbarkRegions): the region_map entry's evilness through
-- dfhack.maps.getRegionBiome (never region_map[x][y], the addendum-31 trap) and, where the build carries them, the
-- world_region's own good/evil flags. good: evilness < 33 or region.good; evil: evilness >= 66 or region.evil.
function V7.alignment()
    local rs = getEmbarkRegions()
    if CACHE.align and CACHE.align.rs == rs then return CACHE.align end
    local a = { rs = rs, good = false, evil = false, tiles = 0 }
    for key in pairs(rs) do
        local rx, ry = key:match('(%d+):(%d+)')
        local ok, ent = pcall(dfhack.maps.getRegionBiome, tonumber(rx), tonumber(ry))
        if ok and ent then
            a.tiles = a.tiles + 1
            local okE, ev = pcall(function() return ent.evilness end)
            if okE and type(ev) == 'number' then
                if ev < 33 then a.good = true elseif ev >= 66 then a.evil = true end
            end
            local okR, reg = pcall(df.world_region.find, ent.region_id)
            if okR and reg then
                local okG, g = pcall(function() return reg.good end); if okG and g == true then a.good = true end
                local okV, v = pcall(function() return reg.evil end); if okV and v == true then a.evil = true end
            end
        end
    end
    CACHE.align = a
    return a
end
-- every biome the raw names is subterranean: a cavern species, whatever its alignment tag
function V7.caveOnly(craw)
    local any = false
    for i = df.biome_type._first_item, df.biome_type._last_item do
        local nm = df.biome_type[i]
        if nm and biomeFlag(craw, nm) then
            if nm:sub(1, 12) ~= 'SUBTERRANEAN' then return false end
            any = true
        end
    end
    return any
end
-- a 'mythic' creature the v7 rules make natural: FANCIFUL alone (yeti, sasquatch), a cavern GOOD/EVIL species,
-- or surface GOOD/EVIL wildlife on a region of its alignment. Returns the reason, or nil.
function V7.alignedNatural(cfg, craw, why)
    local only = {}
    for _, w in ipairs(why or {}) do only[w] = true end
    local f = craw.flags
    local good, evil = f.GOOD and true or false, f.EVIL and true or false
    if not good and not evil then
        if only.FANCIFUL and V7.on(cfg, 'fanciful') then return 'FANCIFUL is art, not placement (v7)' end
        return nil
    end
    if not hasAnyBiome(craw) then return nil end   -- a civ race (goblins) or a legend: no wild entry to manage
    if V7.caveOnly(craw) then
        return V7.on(cfg, 'cave_aligned') and 'a cavern species: alignment only limits taming (v7)' or nil
    end
    if not V7.on(cfg, 'aligned') or not dfhack.isMapLoaded() then return nil end
    local ok, a = pcall(V7.alignment)
    if not ok or not a then return nil end
    if (good and a.good) or (evil and a.evil) then
        return ('%s wildlife on a %s region (v7)'):format(good and 'GOOD' or 'EVIL', good and 'good' or 'evil')
    end
    return nil
end
local function ecoOf(cfg, craw)
    local ov = cfg and cfg.class_override[craw.creature_id]
    if ov == 'natural' then return ov, { 'user override' } end   -- v6.3.0 (D8): an override can only bring a creature in as natural
    local cls, why = ecologyClass(craw)
    if cls == 'mythic' then
        local r = V7.alignedNatural(cfg, craw, why)
        if r then return 'natural', { r } end
    end
    return cls, why
end

--========================================================================================
-- MODEL (v6.4.0, W2; alpha 1 R2; decisions D4, Q1): habitat, role and size band, each from the raws
--========================================================================================
-- Until v6.4 one raw flag decided a species' whole identity: a BENIGN orca was prey, a bird could not be a
-- predator, DF's LARGE_PREDATOR behaviour flag made a dingo 'large', and any water-breathing flag or an
-- all-water biome list made a species 'aquatic' -- albatrosses, night creatures and otters alike. Now three
-- readings, independent of one another:
--   HABITAT, from four caste flags and the biome list (Q1, measured on the trial fort):
--     aquatic      cannot move on land or cannot breathe air: fish, sharks, mollusks, sea monster, sea serpent
--     semiaquatic  breathes water and air ([AMPHIBIOUS]), or cannot fly and every biome it has is water:
--                  hippo, otters, crabs, crocodiles, walrus, penguin
--     waterbird    flies and has at least one water biome: albatross, osprey, puffin, duck
--     flier        flies, no water biome: eagle, kestrel, owls, bats
--     land         everything else. CAN_SWIM_INNATE says nothing (wolves and eagles carry it).
--   ROLE: predator when any caste carries CARNIVORE, BONECARN, LARGE_PREDATOR or AMBUSHPREDATOR, else prey;
--     a short curated table covers the vanilla raws that carry no diet token for an animal that hunts.
--   SIZE BAND by adult body volume in cm3 (D4): small < 150,000; medium < 1,000,000; large from 1,000,000.
-- Water body and salinity come from the biome names (OCEAN_*, LAKE_/RIVER_/POOL_*_FRESH|BRACKISH|SALTWATER,
-- SUBTERRANEAN_WATER) for placement by body and salinity (v6.5). Per-species overrides of habitat and role
-- live in cfg.habitat_override / cfg.role_override and are set from the species detail page.
local MODEL = { SMALL = 150000, LARGE = 1000000,
    HABITATS = { 'land', 'flier', 'waterbird', 'semiaquatic', 'aquatic' },
    SHORT = { land = 'land', flier = 'fly', waterbird = 'wbird', semiaquatic = 'semi', aquatic = 'aqua' },
    -- the vanilla gaps, each naming the raw that lacks the token (checked against the 53.16 raws, 26 Sep 2026)
    ROLE = {
        ORCA = 'predator',             -- creature_large_ocean.txt: [BENIGN], no diet token; an orca hunts
        GIANT_ORCA = 'predator',       -- the giant variation of ORCA, same gap
        GIANT_CUTTLEFISH = 'predator', -- no diet token; cuttlefish hunt (the vermin CUTTLEFISH stays vermin)
        SHARK_WHALE = 'prey',          -- [BENIGN], a filter feeder: prey is right, listed so the choice is on record
    },
    DIET = { 'CARNIVORE', 'BONECARN', 'LARGE_PREDATOR', 'AMBUSHPREDATOR' },
}
function MODEL.band(mass)
    if mass >= MODEL.LARGE then return 'large' end
    if mass >= MODEL.SMALL then return 'medium' end
    return 'small'
end

-- v6.7.0 (alpha 2, step 10.1; user 28 Sep): an animal person's predator/prey standing mirrors its root animal.
-- DF's compiled raws have already expanded [COPY_TAGS_FROM:ROOT] + [APPLY_CREATURE_VARIATION:ANIMAL_PERSON(_LEGLESS)],
-- and a name cannot recover the root (OTTER_MAN is 'otter man', its root RIVER OTTER is 'river otter'), so the
-- two lines are read from the raw files once per world: vanilla, installed mods, mods. A person the files do not
-- name falls back to its token less _MAN (or BIRD_ + that). ~40 files, read once, at the first classification.
function MODEL.rawOf(token)   -- the creature raw by token, indexed once per world (CAVERN.rawFor is declared later)
    if not CACHE.rawByToken then
        CACHE.rawByToken = {}
        for _, c in ipairs(df.global.world.raws.creatures.all) do CACHE.rawByToken[c.creature_id] = c end
    end
    return CACHE.rawByToken[token]
end
-- v7.0.0: a saved allow or season on a species of a locked class is dropped at load. Every quantity writer
-- gates on cfg.allow[key] ~= nil, so a stale value (the Vermin tab's D wrote them for fairies and demon rats
-- until v7) would otherwise keep that entry seasoned or zeroed.
function V7.sanitizeLocked(c)
    if not dfhack.isMapLoaded() then return 0 end
    local n = 0
    for _, map in ipairs({ c.allow, c.assign }) do
        for key in pairs(map) do
            local cr = MODEL.rawOf(key:match('[^:]+$'))
            if cr and c.classes[(ecoOf(c, cr))] ~= true then map[key] = nil; n = n + 1 end
        end
    end
    return n
end
-- v7.1 (roster stream): the same pass records every creature block it saw (CACHE.rawSeen) and every one that applies
-- the GIANT variation (CACHE.giantVar). The token-stem fallback below now runs only for a creature the files never
-- named (a mod outside them): ANT_MAN is its own creature in creature_subterranean.txt, with no COPY_TAGS_FROM, so
-- the stem rule made it an animal person of the vermin ANT (open item antman-civ-class; R61 puts it in the civ set).
function MODEL.rootOf(token)
    if not CACHE.animalRoot then
        local map, base = {}, dfhack.getDFPath()
        local seen, giant = {}, {}
        for _, dir in ipairs({ base .. '/data/vanilla', base .. '/data/installed_mods', base .. '/mods' }) do
            local ok, files = pcall(dfhack.filesystem.listdir_recursive, dir, 6, true)
            for _, fe in ipairs(ok and files or {}) do
                if not fe.isdir and fe.path:match('creature[^/\\]*%.txt$') then
                    local fh = io.open(fe.path, 'rb')
                    if fh then
                        local cur, from, person = nil, nil, false
                        local function close() if cur and from and person then map[cur] = from end end
                        for line in fh:lines() do
                            local c = line:match('%[CREATURE:([^%]]+)%]')
                            if c then close(); cur, from, person = c, nil, false; seen[c] = true
                            else
                                from = line:match('%[COPY_TAGS_FROM:([^%]]+)%]') or from
                                if line:find('APPLY_CREATURE_VARIATION:ANIMAL_PERSON', 1, true) then person = true end
                                if cur and line:find('APPLY_CREATURE_VARIATION:GIANT]', 1, true) then giant[cur] = true end
                            end
                        end
                        close(); fh:close()
                    end
                end
            end
        end
        CACHE.animalRoot = map
        CACHE.rawSeen, CACHE.giantVar = seen, giant
    end
    local r = CACHE.animalRoot[token]
    if r then return r end
    if (CACHE.rawSeen or {})[token] then return nil end   -- v7.1: named in the files and not a person variation
    local stem = token:match('^(.+)_MAN$')
    if stem then
        for _, t in ipairs({ stem, 'BIRD_' .. stem }) do if MODEL.rawOf(t) then return t end end
    end
    return nil
end
local function classify(craw)
    local hit = CACHE.class[craw.creature_id]   -- v6.3.0 (W7): raws are classified once per world
    if hit then return hit end
    local f = craw.flags
    local mega  = f.HAS_ANY_MEGABEAST or false
    local night = f.HAS_ANY_NIGHT_CREATURE or false
    local isVermin = f.VERMIN_GROUNDER or f.VERMIN_ROTTER or f.VERMIN_SOIL
                  or f.VERMIN_FISH or f.VERMIN_EATER or f.SMALL_RACE or false
    local flier = f.HAS_ANY_FLIER or false
    -- v6.4.0: small birds are no longer lifted out of vermin by an egg-and-flight test; a vermin bird is vermin
    -- with the flier habitat, and a large bird is a predator or prey with the flier or waterbird habitat
    local role, roleWhy = MODEL.role(craw)
    local habitat = MODEL.habitat(craw)
    local cat = isVermin and 'vermin' or role
    -- group size: midpoint of cluster_number {MAX, MIN}; a solitary animal is 1
    local cmax, cmin = craw.cluster_number[0], craw.cluster_number[1]
    local group = math.max(1, math.floor((cmax + cmin) / 2))
    local out = { category=cat, size=MODEL.band(adultSize(craw)), mega=mega, night=night,
             role=role, roleWhy=roleWhy, habitat=habitat, waters=MODEL.waters(craw),
             evil=f.EVIL or false, savage=f.SAVAGE or false, flier=flier,
             gameVermin=isVermin, aquatic=(habitat == 'aquatic' or habitat == 'semiaquatic'), clade=cladeOf(craw),
             eco=ecologyClass(craw), mass=adultSize(craw), group=group,
             largePred=hasCasteFlag(craw, 'LARGE_PREDATOR'), ambush=hasCasteFlag(craw, 'AMBUSHPREDATOR'),
             carnivore=hasCasteFlag(craw, 'CARNIVORE'), swims=hasCasteFlag(craw, 'CAN_SWIM_INNATE'),
             -- v6.9.0: a curated predator (the orca) is BENIGN in its raws; the tool clears that flag while ecology runs
             -- (CURIOUS.apply), so the model counts it armed (ECO HO: orca 0 attacks on written seals; BENIGN off 4 of 8)
             benign=allCasteFlag(craw, 'BENIGN') and MODEL.ROLE[craw.creature_id] ~= 'predator',
             noSeason={ [0]=allCasteFlag(craw, 'NO_SPRING'), [1]=allCasteFlag(craw, 'NO_SUMMER'),
                        [2]=allCasteFlag(craw, 'NO_AUTUMN'), [3]=allCasteFlag(craw, 'NO_WINTER') } }
    -- v6.7.0: an animal person stands where its root animal stands in the food web: role, habitat, water, size,
    -- group and the diet flags come from the root; its own class, name and seasons stay its own
    local rootTok = not isVermin and MODEL.rootOf(craw.creature_id)
    local rootRaw = rootTok and rootTok ~= craw.creature_id and MODEL.rawOf(rootTok)
    -- v7.1 (roster stream): the raw cluster range in order (R41, R59), the giant variant, the raw cavern depth and
    -- the lava-only habitat (R28), the native GOBBLE classes and, for vermin, the creature classes (R51)
    local c0, c1 = craw.cluster_number[0], craw.cluster_number[1]
    out.cmin, out.cmax = math.max(0, math.min(c0, c1)), math.max(c0, c1)
    out.giant = ((CACHE.giantVar or {})[craw.creature_id] or craw.creature_id:sub(1, 6) == 'GIANT_') and true or false
    out.sentient = hasCasteFlag(craw, 'CAN_SPEAK') or hasCasteFlag(craw, 'CAN_LEARN')
    out.good, out.monster = f.GOOD or false, (f.GOOD or f.EVIL) and true or false
    local okD, dlo, dhi = pcall(function() return craw.underground_layer_min, craw.underground_layer_max end)
    if okD and type(dlo) == 'number' and type(dhi) == 'number' and dhi > 0 then out.depthLo, out.depthHi = dlo, dhi end
    local onlyLava, anyBiome = true, false   -- (rawBiomes is declared below classify; read the flags directly)
    for i = df.biome_type._first_item, df.biome_type._last_item do
        local nm = df.biome_type[i]
        if nm and biomeFlag(craw, nm) then anyBiome = true; if nm ~= 'SUBTERRANEAN_LAVA' then onlyLava = false end end
    end
    out.fireOnly = anyBiome and onlyLava
    pcall(function()
        local gset = {}
        for _, c in ipairs(craw.caste) do for _, v in ipairs(c.gobble_vermin_class) do gset[(type(v) == 'string') and v or v.value] = true end end
        local gl = {}
        for k in pairs(gset) do if k:sub(1, 4) ~= 'SWV_' then gl[#gl+1] = k end end
        if #gl > 0 then table.sort(gl); out.gobble = gl end
        if isVermin then
            local cs = {}
            for _, c in ipairs(craw.caste) do for _, v in ipairs(c.creature_class) do cs[(type(v) == 'string') and v or v.value] = true end end
            out.cclass = cs
        end
    end)
    if rootRaw then
        local r = classify(rootRaw)
        -- v7.1 (R25/R57, open item animal-person-mass): mass, size band and group are the person's OWN. The
        -- ANIMAL_PERSON variation sets GRAVITATE_BODY_SIZE:70000 (adult size -> the mean of the root's and 70,000
        -- cm3) and its own CLUSTER_NUMBER, both compiled into this raw; v6.7 copied the root's, so a damselfly man
        -- weighed 10 cm3. If the compiled size still equals the root's, the gravitation is applied here.
        for _, k in ipairs({ 'category', 'role', 'habitat', 'waters', 'aquatic', 'flier', 'largePred', 'ambush', 'carnivore', 'swims' }) do out[k] = r[k] end
        if out.mass == r.mass then out.mass = math.floor((r.mass + 70000) / 2) end
        out.root, out.roleWhy, out.ap, out.sentient = rootTok, 'as its root animal ' .. rootTok, true, true
        -- R25: a vermin-root person is a small predator of small critters (ML on foot, RP flying, MW swimming)
        if r.gameVermin then
            out.apVermin, out.role, out.category, out.roleWhy = true, 'predator', 'predator', 'a small predator (vermin root ' .. rootTok .. ', R25)'
            local vm = ((CACHE.cfg or {}).roster or {}).ap_vermin_mass
            if type(vm) == 'number' and vm > 0 then out.mass = vm end
        end
        out.size = MODEL.band(out.mass)
    end
    -- v6.9.0: the guild is read after the root mirror, from the creature's own vermin state: a bat man is a unit even
    -- though a bat is vermin (validation 124603: 79 animal people had taken their vermin root's guild)
    out.guild = MODEL.guild(craw, out)
    V7.EXTINCT.model(craw, out)   -- v7.1 (extinct stream, R24): the corrected extinct tags, raws written or not
    out.civ = V7.isCivRaw(craw)   -- v7.0.0: a cavern civilisation race (V7.isCivRaw)
    CACHE.class[craw.creature_id] = out
    return out
end
-- v6.3.0 (W7): the biome ids a raw admits, read once per world rather than a 'BIOME_' .. name string per
-- raw per embark biome on every pool build
local function rawBiomes(craw)
    local hit = CACHE.rawBiomes[craw.creature_id]
    if hit then return hit end
    local set = {}
    for i = df.biome_type._first_item, df.biome_type._last_item do
        local nm = df.biome_type[i]
        if nm and biomeFlag(craw, nm) then set[i] = true end
    end
    CACHE.rawBiomes[craw.creature_id] = set
    return set
end
function MODEL.habitat(craw)
    if hasCasteFlag(craw, 'IMMOBILE_LAND') or hasCasteFlag(craw, 'CANNOT_BREATHE_AIR') then return 'aquatic' end
    local flier = hasCasteFlag(craw, 'FLIER')
    local water, land = false, false
    for id in pairs(rawBiomes(craw)) do
        if isWaterBiomeName(df.biome_type[id] or '') then water = true else land = true end
    end
    if flier then return water and 'waterbird' or 'flier' end
    if hasCasteFlag(craw, 'CAN_BREATHE_WATER') then return 'semiaquatic' end
    if water and not land then return 'semiaquatic' end
    return 'land'
end
function MODEL.role(craw)
    local cur = MODEL.ROLE[craw.creature_id]
    if cur then return cur, 'curated' end
    for _, flag in ipairs(MODEL.DIET) do if hasCasteFlag(craw, flag) then return 'predator', flag end end
    return 'prey', hasCasteFlag(craw, 'GRAZER') and 'GRAZER' or 'no diet token'
end
MODEL.SALINITY = { FRESHWATER = 'fresh', BRACKISHWATER = 'brackish', SALTWATER = 'salt' }
function MODEL.waters(craw)
    local bodies, salt = {}, {}
    for id in pairs(rawBiomes(craw)) do
        local nm = df.biome_type[id] or ''
        if nm:sub(1, 5) == 'OCEAN' then bodies.ocean = true; salt.salt = true
        elseif nm == 'SUBTERRANEAN_WATER' then bodies.cavern = true; salt.fresh = true
        else
            local b, sl = nm:match('^(%u+)_%u+_(%u+)$')
            if (b == 'LAKE' or b == 'RIVER' or b == 'POOL') and MODEL.SALINITY[sl] then bodies[b:lower()] = true; salt[MODEL.SALINITY[sl]] = true end
        end
    end
    return { bodies = bodies, salt = salt }
end
-- v6.9.0: GUILDS (ECO desk v2, guild-first roster design, 30 Sep 2026). One primary guild per species from documented
-- tokens alone, tested in this order (precedence):
--   V  vermin (the tool's families split them further)
--   AW water apex: LARGE_PREDATOR, not a flier, aquatic or amphibious    RP raptor: flier and a predator's diet or LP
--   AL land apex: LARGE_PREDATOR                                          MW water mesopredator: aquatic, a predator's diet
--   ML ground mesocarnivore: CARNIVORE / BONECARN / curated predator     GZ grazer herd: GRAZER
--   WB waterbird / LB land bird: flier, by a water biome                 PE pelagic (ocean, adult >= 1,000,000 cm3) /
--   FC coastal fish (ocean, smaller) / FF freshwater and cave-water fish  SH shore: amphibious, or water biomes only
--   PL other land prey
-- (The desk also counts BEACH_FREQUENCY toward PE; the tool keys on size alone.)
MODEL.GUILD_NAME = { V = 'vermin', AW = 'water apex', RP = 'raptor', AL = 'land apex', MW = 'water mesopredator',
    ML = 'ground mesocarnivore', GZ = 'grazer herd', WB = 'waterbird', LB = 'land bird', PE = 'pelagic', FC = 'coastal fish',
    FF = 'freshwater fish', SH = 'shore', PL = 'land prey' }
function MODEL.guild(craw, c)
    if c.gameVermin then return 'V' end
    if c.apVermin then return (c.flier and 'RP') or (c.habitat == 'aquatic' and 'MW') or 'ML' end   -- v7.1 (R25)
    local aquatic = c.habitat == 'aquatic'
    local amphib = not aquatic and hasCasteFlag(craw, 'CAN_BREATHE_WATER')
    local lp, flier = c.largePred, c.flier
    local diet = hasCasteFlag(craw, 'CARNIVORE') or hasCasteFlag(craw, 'BONECARN') or MODEL.ROLE[craw.creature_id] == 'predator'
    if lp and not flier and (aquatic or amphib) then return 'AW' end
    if flier and (diet or lp) then return 'RP' end
    if lp then return 'AL' end
    if diet then return aquatic and 'MW' or 'ML' end
    if hasCasteFlag(craw, 'GRAZER') then return 'GZ' end
    local water, land = false, false
    for id in pairs(rawBiomes(craw)) do
        local nm = df.biome_type[id] or ''
        if isWaterBiomeName(nm) or nm == 'SUBTERRANEAN_WATER' then water = true else land = true end
    end
    if flier then return water and 'WB' or 'LB' end
    if aquatic then
        if c.waters and c.waters.bodies.ocean then return (c.mass or 0) >= 1000000 and 'PE' or 'FC' end
        return 'FF'
    end
    if amphib or (water and not land) then return 'SH' end
    return 'PL'
end
-- v7.0.0 (user, 30 Sep 2026: "both, let them hunt and also be prey of cavern apexes"): a cavern civilisation race is a
-- creature that can speak or learn, is not an animal person (no root animal) and not GOOD/EVIL wildlife, and lives in a
-- SUBTERRANEAN biome -- in vanilla the troglodyte, rodent, amphibian, reptile, serpent and ant men, the gremlin and the
-- plump helmet man. With civ_hunt they are armed by their guild; with civ_prey only a cavern apex (AL/AW, itself not a
-- civ race) is related to them, the builder's AL/AW humanoid rule.
V7.PREDG = { AL = true, AW = true, ML = true, MW = true, RP = true }
-- v7.0.0 (item 21): a realm table as optional tool data. The DF raws carry no geography -- no continent or
-- native-range token exists; DF places a species on any landmass whose biome it admits, around a random
-- per-species epicenter. This table is external, real-world knowledge (native ranges), not DF data: curated
-- at the desk (DwarfCron data/eco-desk/Q9-realms.md, "Non-vermin members", the realm membership table), then
-- checked token-by-token on 30 Sep 2026 against this engine's own installed DF 53.16 vanilla raws. The first
-- pass used `grep`, which silently skips a file it judges binary; creature_large_temperate.txt trips that
-- (a flavor-text line carries a Latin-1 0xF8 "o" in a Monty Python nod -- "A moose once bit my sister"), so
-- macOS/BSD grep reports zero matches for the whole file with no warning. Re-checked by reading every raw
-- file's bytes in Python (`f.read_bytes().decode('latin-1')`) instead of grep: WOLF, FOX, BADGER, RACCOON,
-- PANDA, MOOSE, GROUNDHOG, DEER, COUGAR, BEAR_GRIZZLY, BEAR_BLACK, ALLIGATOR, MACAQUE_RHESUS, CAPYBARA and
-- BIRD_BUZZARD are all real CREATURE tokens in that one file; BIRD_PENGUIN (plain, not _EMPEROR/_LITTLE) was
-- a separate plain oversight, found in creature_birds.txt (not a grep casualty). The same byte-safe sweep,
-- run again over every entry already in this table (not just the Q9 names), caught the opposite mistake in
-- the other direction: ALLIGATOR SNAPPING TURTLE, AYE-AYE, DESERT TORTOISE, GIANT TORTOISE, HONEY BADGER,
-- RIVER OTTER, SEA OTTER and SNAPPING TURTLE have NO plain [CREATURE:...] block anywhere in vanilla -- this
-- DF 53.16 build only has GIANT_DESERT_TORTOISE / GIANT_SNAPPING_TURTLE / GIANT_OTTER / POND_TURTLE and the
-- *_MAN beastman forms for that family, no un-prefixed base creature, and no aye-aye or honey badger at all
-- -- so those 8 were removed (this leaves Madagascar, MAD, with zero members: both of its Q9 names were
-- among them). RED PANDA has no vanilla match either (checked the same way) and was never added. A token
-- with no entry here is simply never realm-filtered (V7.realmOk), same as before this feature.
