function V7.extinctDefaults()
    return { fix = true, freq = true, grazer = true, roles = true, cluster = true, realms = true, units = true,
             stand_down = true, grazer_g = 100, skip = {} }
end
function V7.extinctLoad(raw, c)
    local d = V7.extinctDefaults()
    c.extinct = d
    local r = type(raw) == 'table' and type(raw.extinct) == 'table' and raw.extinct or nil
    if not r then return end
    for k, v in pairs(d) do if type(v) == 'boolean' and type(r[k]) == 'boolean' then d[k] = r[k] end end
    if type(r.grazer_g) == 'number' and r.grazer_g >= 1 and r.grazer_g <= 1000 then d.grazer_g = math.floor(r.grazer_g) end
    if type(r.skip) == 'table' then
        for tok, v in pairs(r.skip) do if type(tok) == 'string' and V7.EXTINCT.TAGS[tok] and v == true then d.skip[tok] = true end end
    end
end
function V7.EXTINCT.cfg(cfg)
    local e = (cfg or CACHE.cfg or {}).extinct
    if e then return e end
    V7.EXTINCT.def = V7.EXTINCT.def or V7.extinctDefaults()
    return V7.EXTINCT.def
end
-- the row in force for a token (nil: no row, the fix is off, or the token is skipped)
function V7.EXTINCT.entry(tok, cfg)
    local t = V7.EXTINCT.TAGS[tok]
    if not t then return nil end
    local E = V7.EXTINCT.cfg(cfg)
    if not E.fix or E.skip[tok] then return nil end
    return t, E
end
function V7.EXTINCT.isExtinct(cr) return hasCreatureClass(cr, V7.EXTINCT.CLASS) end
-- classify's hook, after MODEL.guild: the corrected values as the model sees them. An animal person of a corrected root
-- already mirrors the root's corrected role and habitat (classify's root block); it takes the root's guild here.
function V7.EXTINCT.model(craw, out)
    local t, E = V7.EXTINCT.entry(craw.creature_id)
    local own = t ~= nil
    if not t and out.ap and out.root then t, E = V7.EXTINCT.entry(out.root) end
    if not t then return end
    if E.roles and own then
        for k, field in pairs({ lp = 'largePred', carn = 'carnivore', ambush = 'ambush', benign = 'benign' }) do
            if t[k] ~= nil then out[field] = t[k] end
        end
        if t.habitat then out.habitat = t.habitat; out.aquatic = (t.habitat == 'aquatic' or t.habitat == 'semiaquatic') end
        if (out.largePred or out.carnivore or out.ambush) and out.role ~= 'predator' then
            out.role, out.roleWhy = 'predator', 'extinct fix (R24)'
            if not out.gameVermin then out.category = 'predator' end
        end
    end
    if E.roles and t.guild then out.guild = t.guild end
    if E.grazer and t.grazer and out.guild == 'PL' then out.guild = 'GZ' end
    if E.cluster and own and t.cluster then
        out.cmin, out.cmax = t.cluster[1], t.cluster[2]
        out.group = math.max(1, math.floor((t.cluster[1] + t.cluster[2]) / 2))
    end
    out.extinctFix = true
end
-- realm codes into V7.REALMS where it has none (the user's realms json still wins: it loads over the table); taken out
-- again when the fix or realms is off. Per script copy (V7.REALMS is the copy's own), re-run when the config changes.
function V7.EXTINCT.realmSync()
    local E = V7.EXTINCT.cfg()
    local want = (E.fix and E.realms) and true or false
    local sig = tostring(want) .. ':' .. tostring(CACHE.ver)
    if V7.EXTINCT.realmSig == sig then return end
    V7.EXTINCT.realmSig = sig
    for tok, t in pairs(V7.EXTINCT.TAGS) do
        if t.realm then
            local on = want and not E.skip[tok]
            if on and V7.REALMS[tok] == nil then V7.REALMS[tok] = t.realm
            elseif not on and V7.REALMS[tok] == t.realm then V7.REALMS[tok] = nil end
        end
    end
end
function V7.EXTINCT.grazeValue(c, G)
    local size = 0
    pcall(function() size = c.misc.adult_size end)
    if not size or size <= 0 then local v = c.body_size; if #v > 0 then size = v[#v - 1] end end
    if not size or size <= 0 then return 150 end
    return math.max(150, math.min(3000000, math.floor(20000 * (G or 100) * size ^ -0.75)))
end
-- where a pattern writer keeps the raw's own cluster range while it holds the raw ({max, min}, as cluster_number)
function V7.EXTINCT.clusterSlot(tok)
    local tr = PATTERN and PATTERN.trickle and PATTERN.trickle.raws
    if tr and tr[tok] then return tr[tok] end
    local gs = CACHE.gsize and CACHE.gsize.raws
    if gs and gs[tok] then return gs[tok] end
    return nil
end
function V7.EXTINCT.writeFreq(tok, cr, from, to, E)
    local snap = CAVERN.saved()
    local held = snap[tok] ~= nil
    local base = held and snap[tok] or cr.frequency
    if base == to then return 'same', base end
    if E.stand_down and base ~= from then return 'stood', base end
    if held then snap[tok] = to; CAVERN.save(snap) else cr.frequency = to end
    V7.rec(function()
        local ok, s = pcall(CAVERN.saved)
        if ok and s and s[tok] == to then s[tok] = base; pcall(CAVERN.save, s) end
        if cr.frequency == to then cr.frequency = base end
    end)
    return 'wrote', base
end
function V7.EXTINCT.writeCluster(tok, cr, want, E)
    local slot = V7.EXTINCT.clusterSlot(tok)
    local mx, mn = cr.cluster_number[0], cr.cluster_number[1]
    if slot then mx, mn = slot[1], slot[2] end
    local wmn, wmx = want[1], want[2]
    if mx == wmx and mn == wmn then return 'same' end
    if E.stand_down and math.max(mx, mn) > 1 then return 'stood', ('%d:%d'):format(math.min(mx, mn), math.max(mx, mn)) end
    if slot then slot[1], slot[2] = wmx, wmn else cr.cluster_number[0], cr.cluster_number[1] = wmx, wmn end
    V7.rec(function()
        local s = V7.EXTINCT.clusterSlot(tok)
        if s and s[1] == wmx and s[2] == wmn then s[1], s[2] = mx, mn end
        if cr.cluster_number[0] == wmx and cr.cluster_number[1] == wmn then cr.cluster_number[0], cr.cluster_number[1] = mx, mn end
    end)
    return 'wrote'
end
-- the creature-level HAS_ANY_* flag that goes with a caste flag set on
function V7.EXTINCT.anyFlag(cr, name)
    local ok, old = pcall(function() return cr.flags[name] end)
    if ok and old == false and pcall(function() cr.flags[name] = true end) then
        V7.rec(function() pcall(function() cr.flags[name] = false end) end)
    end
end
-- the extinct-related mods in DF's load order: { {id=, name=, why=}, ... }
function V7.EXTINCT.mods()
    local out = {}
    pcall(function()
        local ol = df.global.world.object_loader
        local base = (dfhack.filesystem.getBaseDir and dfhack.filesystem.getBaseDir()) or (dfhack.getDFPath() .. '/')
        for i = 0, #ol.object_load_order_id - 1 do
            local id, name, dir = '', '', ''
            pcall(function() id = ol.object_load_order_id[i].value end)
            pcall(function() name = ol.object_load_order_name[i].value end)
            pcall(function() dir = tostring(ol.object_load_order_src_dir[i]) end)
            local hay, hit = (id .. ' ' .. name .. ' ' .. dir):lower(), nil
            for wid in pairs(V7.EXTINCT.MODS) do if hay:find(wid, 1, true) then hit = wid end end
            for _, pat in ipairs(V7.EXTINCT.MOD_NAMES) do if not hit and hay:find(pat, 1, true) then hit = pat end end
            if not hit and dir ~= '' and not dir:find('vanilla', 1, true) then
                local fh = io.open(base .. dir .. '/info.txt', 'rb')
                if fh then
                    local txt = fh:read('*a') or ''; fh:close()
                    local sid = txt:match('%[STEAM_FILE_ID:(%d+)%]')
                    if sid and V7.EXTINCT.MODS[sid] then hit = sid end
                end
            end
            if hit then out[#out+1] = { id = id, name = name, why = hit } end
        end
    end)
    return out
end
-- The raw writes (from V7.apply, after its restore): every row in force, for every creature raw in this world that DF
-- marks extinct. Returns the summary line. CACHE.extinct keeps the per-row states for `extinct list` and the status.
function V7.EXTINCT.apply(cfg, pool)
    local X, E = V7.EXTINCT, V7.EXTINCT.cfg(cfg)
    if not E.fix then CACHE.extinct = nil; return 'extinct fix off' end
    local st = { rows = {}, n = { freq = 0, grazer = 0, roles = 0, cluster = 0, units = 0, stood = 0 }, world = 0, embark = 0,
                 mods = X.mods(), at = dfhack.isMapLoaded() and absTick() or 0 }
    CACHE.extinct = st
    V7.rec(function() CACHE.extinct = nil end)   -- first recorded, so the last put back
    local inEmbark = {}
    for _, e in ipairs(pool or {}) do if e.inEmbark then inEmbark[e.token] = true end end
    local cap = math.floor(ROSTER.cfg(cfg).apex_raw_cap or 0)
    local changed = {}   -- race index -> { caste flag = value } for the unit pass
    for tok, t in pairs(X.TAGS) do
        local cr = CAVERN.rawFor(tok)
        local row = { notes = {} }
        st.rows[tok] = row
        if not cr then row.state = 'not in this world'
        elseif not X.isExtinct(cr) then row.state = 'no REAL_WORLD_EXTINCT class: left alone'
        elseif E.skip[tok] then row.state = 'skipped'
        else
            st.world = st.world + 1
            if inEmbark[tok] then st.embark = st.embark + 1; row.embark = true end
            local wrote, stood = 0, 0
            local function note(what, res, extra)
                if res == 'wrote' then wrote = wrote + 1; row.notes[#row.notes+1] = what
                elseif res == 'stood' then stood = stood + 1; row.notes[#row.notes+1] = what .. ' stood down (raw ' .. tostring(extra) .. ')' end
            end
            if E.freq and t.freq then
                local to = t.freq[2]
                if cap > 0 then to = math.min(to, cap) end
                local res, base = X.writeFreq(tok, cr, t.freq[1], to, E)
                if res == 'wrote' then st.n.freq = st.n.freq + 1 end
                note(('FREQUENCY %d->%d'):format(base or t.freq[1], to), res, base)
            end
            local race = raceIndex(tok)
            if E.grazer and t.grazer then
                local already = hasCasteFlag(cr, 'GRAZER')
                if already and E.stand_down then note('GRAZER', 'stood', 'already GRAZER')
                elseif casteFlagExists(cr, 'GRAZER') then
                    local any = false
                    for _, c in ipairs(cr.caste) do
                        if V7.flag(cr, c, 'GRAZER', true) then any = true end
                        local val = X.grazeValue(c, E.grazer_g)
                        local ok, old = pcall(function() return c.misc.grazer end)
                        if ok and old ~= val and pcall(function() c.misc.grazer = val end) then
                            any = true
                            V7.rec(function() if c.misc.grazer == val then c.misc.grazer = old end end)
                        end
                    end
                    X.anyFlag(cr, 'HAS_ANY_GRAZER')
                    if any then
                        st.n.grazer = st.n.grazer + 1
                        changed[race] = changed[race] or {}; changed[race].GRAZER = true
                        note(('GRAZER (%d)'):format(X.grazeValue(cr.caste[0], E.grazer_g)), 'wrote')
                    end
                end
            end
            if E.roles then
                local any = false
                for k, flag in pairs(X.FLAGS) do
                    if t[k] ~= nil and casteFlagExists(cr, flag) then
                        local did = false
                        for _, c in ipairs(cr.caste) do if V7.flag(cr, c, flag, t[k]) then did = true end end
                        if did then
                            any = true
                            changed[race] = changed[race] or {}; changed[race][flag] = t[k]
                            note(flag .. (t[k] and ' on' or ' off'), 'wrote')
                            if t[k] and flag == 'CARNIVORE' then X.anyFlag(cr, 'HAS_ANY_CARNIVORE') end
                        end
                    end
                end
                if any then st.n.roles = st.n.roles + 1 end
                if t.habitat or t.guild then row.notes[#row.notes+1] = 'model: ' .. (t.habitat and ('habitat ' .. t.habitat .. ' ') or '') .. (t.guild and ('guild ' .. t.guild) or '') end
            end
            if E.cluster and t.cluster then
                local res, extra = X.writeCluster(tok, cr, t.cluster, E)
                if res == 'wrote' then st.n.cluster = st.n.cluster + 1 end
                note(('cluster %d:%d'):format(t.cluster[1], t.cluster[2]), res, extra)
            end
            st.n.stood = st.n.stood + stood
            row.state = (wrote > 0 and 'written' or (stood > 0 and 'stood down' or 'nothing to write'))
        end
    end
    -- wild extinct units already on the map: the changed caste flags into their per-unit cache (never tame or fort units)
    if E.units and next(changed) and dfhack.isMapLoaded() then
        for _, u in ipairs(df.global.world.units.active) do
            local fl = changed[u.race]
            if fl and not dfhack.units.isDead(u) and dfhack.units.isWildlife(u) then
                local uid = u.id
                for f, v in pairs(fl) do
                    local ok, old = pcall(function() return u.enemy.caste_flags[f] end)
                    if ok and old ~= v and pcall(function() u.enemy.caste_flags[f] = v end) then
                        st.n.units = st.n.units + 1
                        V7.rec(function() local w = df.unit.find(uid); if w then pcall(function() w.enemy.caste_flags[f] = old end) end end)
                    end
                end
            end
        end
    end
    local n = st.n
    local msg = ('extinct (R24): %d of %d table species in this world (%d in the embark); FREQUENCY %d, GRAZER %d, roles %d, cluster %d species written; %d unit flag(s); %d stood down; attack mods %s'):format(
        st.world, X.count(), st.embark, n.freq, n.grazer, n.roles, n.cluster, n.units, n.stood, #st.mods > 0 and ('active: ' .. X.modNames(st.mods)) or 'none')
    LEDGER.add('extinct', '', msg)
    return msg
end
function V7.EXTINCT.count() local n = 0; for _ in pairs(V7.EXTINCT.TAGS) do n = n + 1 end; return n end
function V7.EXTINCT.modNames(mods)
    local t = {}
    for _, m in ipairs(mods) do t[#t+1] = (m.name ~= '' and m.name or m.id) end
    return table.concat(t, ', ')
end
function V7.EXTINCT.switches(E)
    local on = {}
    for _, k in ipairs({ 'freq', 'grazer', 'roles', 'cluster', 'realms', 'units', 'stand_down' }) do if E[k] then on[#on+1] = k end end
    return table.concat(on, ' ')
end
function V7.EXTINCT.statusLine(cfg)
    local E, st = V7.EXTINCT.cfg(cfg), CACHE.extinct
    if not E.fix then return 'extinct: fix off (DF\'s extinct raws as shipped; the model reads them as they are)' end
    local head = ('extinct: fix on [%s]'):format(V7.EXTINCT.switches(E))
    if not (cfg or {}).enabled then return head .. '; raws not written: rotation is off (the model already reads the corrections)' end
    if not st then return head .. '; raws not written yet (they are written when the tool applies: enable, load, `extinct on`)' end
    local n = st.n
    return ('%s; %d of %d table species in this world, %d in the embark; written: FREQUENCY %d, GRAZER %d, roles %d, cluster %d, unit flags %d; stood down %d; attack mods %s'):format(
        head, st.world, V7.EXTINCT.count(), st.embark, n.freq, n.grazer, n.roles, n.cluster, n.units, n.stood,
        #st.mods > 0 and ('active: ' .. V7.EXTINCT.modNames(st.mods)) or 'none (animal-people attacks are mod-only)')
end
-- one row's readback: the raw now (and CAVERN's snapshot), the model's reading, the state of the last apply
function V7.EXTINCT.rowLine(cfg, tok)
    local t = V7.EXTINCT.TAGS[tok]
    local cr = dfhack.isMapLoaded() and CAVERN.rawFor(tok) or nil
    local parts = { 'extinct-entry', tok }
    local want = {}
    if t.freq then want[#want+1] = ('freq=%d->%d'):format(t.freq[1], t.freq[2]) end
    if t.grazer then want[#want+1] = 'grazer=+' end
    for k, flag in pairs(V7.EXTINCT.FLAGS) do if t[k] ~= nil then want[#want+1] = flag .. '=' .. (t[k] and 'on' or 'off') end end
    if t.cluster then want[#want+1] = ('cluster=%d:%d'):format(t.cluster[1], t.cluster[2]) end
    if t.habitat then want[#want+1] = 'habitat=' .. t.habitat end
    if t.guild then want[#want+1] = 'guild=' .. t.guild end
    if t.realm then want[#want+1] = 'realm=' .. table.concat(t.realm, ',') end
    table.sort(want)
    parts[#parts+1] = table.concat(want, ' ')
    if cr then
        local snap = CAVERN.saved()[tok]
        local c = classify(cr)
        parts[#parts+1] = ('| raw freq=%d%s grazer=%s cluster=%d:%d | model guild=%s role=%s habitat=%s benign=%s lp=%s'):format(
            cr.frequency, snap and ('(snap ' .. snap .. ')') or '', tostring(hasCasteFlag(cr, 'GRAZER')),
            math.min(cr.cluster_number[0], cr.cluster_number[1]), math.max(cr.cluster_number[0], cr.cluster_number[1]),
            tostring(c.guild), tostring(c.role), tostring(c.habitat), tostring(c.benign), tostring(c.largePred))
    else parts[#parts+1] = '| not in this world' end
    local row = CACHE.extinct and CACHE.extinct.rows[tok]
    if V7.EXTINCT.cfg(cfg).skip[tok] then parts[#parts+1] = '| skipped'
    elseif row then parts[#parts+1] = ('| %s%s%s'):format(row.state, row.embark and ' (in the embark)' or '', #row.notes > 0 and (': ' .. table.concat(row.notes, ', ')) or '') end
    return table.concat(parts, ' ')
end
function V7.EXTINCT.verb(args)
    local X, c, a2, a3, a4 = V7.EXTINCT, loadConfig(), args[2], args[3], args[4]
    local E = c.extinct
    local function reapply(what)
        saveConfig(c); LEDGER.add('extinct', '', 'extinct %s', what)
        CACHE.class = {}; CACHE.predset = nil   -- the model re-reads every creature with the new setting
        if dfhack.isMapLoaded() then print(c.enabled and V7.apply(loadConfig()) or 'extinct: rotation is off, so no raw is written (the model uses the setting)') end
    end
    if a2 == 'on' or a2 == 'off' then
        E.fix = (a2 == 'on'); reapply(a2)
    elseif a2 == 'set' then
        if a3 == 'grazer_g' and tonumber(a4) and tonumber(a4) >= 1 and tonumber(a4) <= 1000 then E.grazer_g = math.floor(tonumber(a4))
        elseif a3 and type(E[a3]) == 'boolean' and a3 ~= 'fix' and (a4 == 'on' or a4 == 'off') then E[a3] = (a4 == 'on')
        else print('usage: seasonal-wildlife extinct set freq|grazer|roles|cluster|realms|units|stand_down on|off | grazer_g <1-1000>') return end
        reapply(('set %s %s'):format(a3, a4))
    elseif a2 == 'list' then
        local toks = {}
        for tok in pairs(X.TAGS) do toks[#toks+1] = tok end
        table.sort(toks)
        for _, tok in ipairs(toks) do print(X.rowLine(c, tok)) end
        local lost = {}
        for tok in pairs(X.AP_LOST) do lost[#lost+1] = tok end
        table.sort(lost)
        for _, tok in ipairs(lost) do print(('extinct-mod-only %s %s'):format(tok, X.AP_LOST[tok])) end
        return
    elseif a2 == 'mods' then
        local mods = dfhack.isWorldLoaded() and X.mods() or {}
        for _, m in ipairs(mods) do print(('extinct-mod id=%s name=%s matched=%s'):format(m.id, m.name, m.why)) end
        local lost = {}
        for tok, what in pairs(X.AP_LOST) do lost[#lost+1] = tok .. ' (' .. what .. ')' end
        table.sort(lost)
        print(('attack mods active: %d. They restore natural attacks to the extinct animal people only (desk R24.1); the tool writes no attack, so nothing overlaps.%s'):format(
            #mods, #mods > 0 and '' or (' Without one these stay as shipped: ' .. table.concat(lost, '; '))))
        return
    elseif a2 and a2 ~= 'status' then
        local tok = a2:upper()
        if not X.TAGS[tok] then print('usage: seasonal-wildlife extinct [status | list | on|off | TOKEN [on|off] | set KEY on|off | mods]') return end
        if a3 == 'on' or a3 == 'off' then E.skip[tok] = (a3 == 'off') or nil; reapply(('%s %s'):format(tok, a3)) end
        print(X.rowLine(c, tok))
        return
    end
    print(X.statusLine(loadConfig()))
end
function HUNT.status(cfg)
    if not (cfg.hunting and cfg.hunting.enabled) then return 'vermin hunting: off' end
    local dive, hunt = {}, {}
    for tok, list in pairs(CACHE.hunt or {}) do
        local f = list[1] and list[1].flag
        if f == HUNT.DIVE then dive[#dive+1] = tok elseif f == HUNT.HUNT then hunt[#hunt+1] = tok end
    end
    table.sort(dive); table.sort(hunt)
    return ('vermin hunting: on  dive-hunts %d (%s)  hunts %d (%s)'):format(#dive, table.concat(dive, ' '):sub(1, 90), #hunt, table.concat(hunt, ' '):sub(1, 90))
end
--========================================================================================
-- VERMIN gobble (v7.0.0, Q31; user, 30 Sep 2026): GOBBLE_VERMIN_CLASS / _CREATURE wiring
--========================================================================================
-- ECO VRM2 (30 Sep 2026, CTRL) measured the mechanism: writing GOBBLE_VERMIN_CLASS:EDIBLE_GROUND_BUG onto a
-- badger's castes made it remove roaches and no grasshoppers, exactly like the native gobblers (duck,
-- hedgehog); GOBBLE_VERMIN_CREATURE:ROACH_LARGE did the same. This section (a) tags every in-embark vermin
-- species with the tool's own SWV_* CREATURE_CLASS, read by VERMIN.swvClass above, and (b) writes
-- GOBBLE_VERMIN_CLASS (and, for a short class, GOBBLE_VERMIN_CREATURE per member) onto every managed consumer
-- that VERMIN.GOBBLE_RULES or the builder's edge table (VERMIN.GOBBLE_EDGES, swapped for ROSTER.GOBBLE_EDGES when
-- the roster stream exposes it; v7.1, R51) matches. Every write goes through V7.rec, so V7.restore (off, disable,
-- all off, unload) puts the raws back exactly -- strings removed, original lists intact -- the same pattern as
-- CURIOUS and the rest of V7. DF itself wires only one gobble class (EDIBLE_GROUND_BUG: fowl, kiwi, hedgehog,
-- pangolin on ant, beetle, thrips, roach); these rules are the tool's fix for every other vermin family (R27).
-- ANSWERED (ECO VRM4, findings.md:310, 30 Sep night; STATE addendum 98): DF honours a CREATURE_CLASS written at
-- run time onto a vermin caste -- grasshoppers tagged SWV_TEST, badgers given GOBBLE_VERMIN_CLASS:SWV_TEST, 4 and 6
-- removed against 0 and 0 -- so the SWV_* tags alone carry the wiring. The extra native
-- GOBBLE_VERMIN_CLASS:EDIBLE_GROUND_BUG on each SWV_GROUND_BUG consumer is now redundant (DF's four edible bugs
-- are SWV_GROUND_BUG members) and is kept only as a cheap second path; it is restored with the rest.
VERMIN.vecHasValue = function(vec, val)
    for _, s in ipairs(vec) do if ((type(s) == 'string') and s or s.value) == val then return true end end
    return false
end
-- insert `val` into a vector of stl-string (pointers), recorded with V7.rec so restore erases the same value
VERMIN.vecInsert = function(vec, val)
    vec:insert('#', { new = true, value = val })
    V7.rec(function()
        for i = #vec - 1, 0, -1 do
            local v = vec[i]; v = (type(v) == 'string') and v or v.value
            if v == val then vec:erase(i); return end
        end
    end)
end
-- an embark-scoped mirror of VERMIN.allClasses, keyed to this fort's pool (the writer only ever touches
-- species that can actually turn up here). v7.1 (R21): plus every natural vermin species DF has on the map right
-- now (VERMIN.vector -- a cavern or water vermin whose layer the player left off is still prey), each species once.
function VERMIN.gobbleMembers(pool)
    local out, seen = {}, {}
    for _, swv in ipairs(VERMIN.SWV) do out[swv] = {} end
    local function add(craw)
        if craw and not seen[craw.creature_id] then
            seen[craw.creature_id] = true
            table.insert(out[VERMIN.swvClass(craw)], craw.creature_id)
        end
    end
    for _, e in ipairs(pool) do
        if e.cat == 'vermin' and e.inEmbark then add(df.creature_raw.find(e.idx)) end
    end
    local vec = VERMIN.vector and VERMIN.vector()
    if vec then
        local races = {}
        for _, v in ipairs(vec) do races[v.race] = true end
        for race in pairs(races) do
            local craw = df.creature_raw.find(race)
            if craw and not seen[craw.creature_id] then
                local c = classify(craw)
                if c.gameVermin and c.eco == 'natural' then add(craw) end
            end
        end
    end
    return out
end
-- SWV_<class> onto every caste of every member that lacks it; returns how many castes took the write
function VERMIN.gobbleClassVec(members, swv)
    local n = 0
    for _, tok in ipairs(members) do
        local cr = CAVERN.rawFor(tok)
        if cr then
            for _, c in ipairs(cr.caste) do
                if not VERMIN.vecHasValue(c.creature_class, swv) then VERMIN.vecInsert(c.creature_class, swv); n = n + 1 end
            end
        end
    end
    return n
end
-- GOBBLE_VERMIN_CLASS:cls + VERMIN_GOBBLER onto every caste of consumer raw `cr`; true if anything was written
function VERMIN.gobbleWriteClass(cr, cls)
    local wrote = false
    for _, c in ipairs(cr.caste) do
        if not VERMIN.vecHasValue(c.gobble_vermin_class, cls) then VERMIN.vecInsert(c.gobble_vermin_class, cls); wrote = true end
        if V7.flag(cr, c, 'VERMIN_GOBBLER', true) then wrote = true end
    end
    return wrote
end
-- GOBBLE_VERMIN_CREATURE:tok (caste ALL) + VERMIN_GOBBLER onto every caste of consumer raw `cr` -- the
-- single-species fallback for a short class (cfg.v7.gobble_creature_fallback)
function VERMIN.gobbleWriteCreature(cr, tok)
    local wrote = false
    for _, c in ipairs(cr.caste) do
        if not VERMIN.vecHasValue(c.gobble_vermin_creature, tok) then
            VERMIN.vecInsert(c.gobble_vermin_creature, tok); VERMIN.vecInsert(c.gobble_vermin_caste, 'ALL'); wrote = true
        end
        if V7.flag(cr, c, 'VERMIN_GOBBLER', true) then wrote = true end
    end
    return wrote
end
-- who eats which vermin class -- one row per guild rule, easy to edit: add a row, the write loop below never
-- changes. `mass` is adultSize's cm3 reading (the same units PE's 1,000,000 cm3 pelagic cut uses); `legless`
-- is a best-effort read of the caste's gait names (no WALK/RUN gait => legless) -- DF exposes no leg count to
-- Lua directly, so this is flagged for the rig in vermin.md rather than assumed.
VERMIN.GOBBLE_MASS_SMALL = 10000   -- ~10 kg
VERMIN.GOBBLE_SMALL_GUILD = { ML = true, PL = true, SH = true }
VERMIN.GOBBLE_FISH_GUILD = { WB = true, FF = true, FC = true }
function VERMIN.legless(craw)
    local caste = craw.caste[0]
    if not caste then return false end
    local ok, result = pcall(function()
        local gi = caste.body_info.gait_info
        if #gi == 0 then return false end
        for i = 0, #gi - 1 do
            local name = (gi[i].name or ''):upper()
            if name:find('WALK') or name:find('RUN') then return false end
        end
        return true
    end)
    return ok and result or false
end
VERMIN.GOBBLE_RULES = {
    { name = 'small land insectivore/omnivore', classes = { 'SWV_GROUND_BUG', 'SWV_SOIL', 'SWV_COLONY' },
      match = function(cr, e) return VERMIN.GOBBLE_SMALL_GUILD[e.guild] and (e.mass or 0) < VERMIN.GOBBLE_MASS_SMALL
                                      and (e.carnivore or not hasCasteFlag(cr, 'GRAZER')) end },
    { name = 'waterbird / fish-eater', classes = { 'SWV_SMALL_FISH' },
      match = function(cr, e) return VERMIN.GOBBLE_FISH_GUILD[e.guild] end }, -- luacheck: ignore 212
    { name = 'raptor', classes = { 'SWV_SMALL_BIRD', 'SWV_BAT', 'SWV_SMALL_MAMMAL' },
      match = function(cr, e) return e.guild == 'RP' end }, -- luacheck: ignore 212
    { name = 'bat / land bird', classes = { 'SWV_FLYING_INSECT' },
      match = function(cr, e) return e.guild == 'LB' end }, -- luacheck: ignore 212
    { name = 'snake', classes = { 'SWV_SMALL_MAMMAL', 'SWV_HERP' },
      match = function(cr, e) return e.guild == 'ML' and VERMIN.legless(cr) end },
}
-- v7.1 (R51): the builder's GOBBLE_VERMIN edge table, ported. Source: DwarfCron data/eco-desk/v2/guilds/roster2.py
-- (DIET, CAVE_LB_DIET, the GOBBLE native rule in diet_of) and design.md section 4 (the diet matrix) and R14 (vermin
-- links): an eater guild -> the builder's vermin guilds. VB -> VI (vermin on vermin) is the builder's bookkeeping
-- link, not a unit's, and is left out. VERMIN.VCLASS maps each builder vermin guild onto the tool's SWV classes
-- (species2.py _vclass: VC colony, VB flying bird or bat, VI flying insect, VF fish/aquatic, VG everything else).
-- The roster builder writes GOBBLE_VERMIN_CREATURE per species pair; the engine writes the same edges as whole
-- runtime classes (VRM4), which reaches every member present, with gobble_creature_fallback for short classes.
-- Row shape (also accepted from ROSTER.GOBBLE_EDGES): { guild = <MODEL guild code>, vermin = { <VG|VC|VF|VB|VI>... },
-- where = nil|'cave'|'water', native = nil|true (DF's own GOBBLE_VERMIN_CLASS eaters, any guild) }. A plain map
-- { ML = { 'VG', 'VC', 'VF' }, ... } is accepted too (VERMIN.edges normalises both).
VERMIN.VCLASS = { VG = { 'SWV_GROUND_BUG', 'SWV_SOIL', 'SWV_SMALL_MAMMAL', 'SWV_HERP', 'SWV_OTHER' },
                  VC = { 'SWV_COLONY' }, VF = { 'SWV_SMALL_FISH' }, VB = { 'SWV_SMALL_BIRD', 'SWV_BAT' },
                  VI = { 'SWV_FLYING_INSECT' } }
VERMIN.GOBBLE_EDGES = {
    { guild = 'ML', vermin = { 'VG', 'VC', 'VF' } },          -- ground mesocarnivores: ground, colony, fish vermin
    { guild = 'AW', vermin = { 'VF' } },                      -- water apex: vermin fish (cave water has no unit fish)
    { guild = 'MW', vermin = { 'VF' } },                      -- water mesopredators
    { guild = 'RP', vermin = { 'VB', 'VI' } },                -- raptors: small birds, bats, flying insects
    { guild = 'LB', vermin = { 'VB', 'VI', 'VG' }, where = 'cave' },   -- v2.2: cavern bats and floaters
    -- v2.2: DF's own gobblers (fowl, kiwi, hedgehog, pangolin) get links to their own class only (roster2.py edge():
    -- 'gobblers: their class only'), which DF already wires -- so the row writes nothing; it is kept so the table
    -- reads whole and so a swapped-in ROSTER.GOBBLE_EDGES row with vermin listed here is honoured
    { native = true, vermin = {} },
}
-- the edge rows in force: ROSTER.GOBBLE_EDGES when the roster stream provides it, else the port above; normalised
-- to a list of rows. Returns rows, source label.
-- v7.1 (fixes): the roster stream's table as merged is keyed by roster LAYER ({ land = { built, vermin, edges }, ... },
-- one edge per consumer species and vermin), not by guild -- read as a guild map, its rows were named 'land', 'water'...,
-- matched no guild, and once a build ran the edge source fed nothing. It is turned into per-species rows here (token =
-- the consumer, vermin = the vermin guilds of its 'write' edges; 'native' edges need no write, 'tool' edges are vermin
-- on vermin), plus the native-gobbler row. CACHE.gobbleEdges is the copy every script copy shares.
function VERMIN.rosterRows(src)
    local layered = false
    for _, t in pairs(src) do if type(t) == 'table' and type(t.edges) == 'table' then layered = true end end
    if not layered then return nil end
    local rows, by = {}, {}
    for _, t in pairs(src) do
        for _, ed in ipairs(type(t) == 'table' and type(t.edges) == 'table' and t.edges or {}) do
            if ed.kind == 'write' and ed.consumer and VERMIN.VCLASS[ed.vclass or ''] then
                local r = by[ed.consumer]
                if not r then r = { token = ed.consumer, vermin = {}, seen = {} }; by[ed.consumer] = r; rows[#rows+1] = r end
                if not r.seen[ed.vclass] then r.seen[ed.vclass] = true; r.vermin[#r.vermin+1] = ed.vclass end
            end
        end
    end
    table.sort(rows, function(a, b) return a.token < b.token end)
    rows[#rows+1] = { native = true, vermin = {} }
    return rows
end
function VERMIN.edges()
    local src, label = rawget(ROSTER, 'GOBBLE_EDGES'), 'ROSTER.GOBBLE_EDGES'
    if (type(src) ~= 'table' or next(src) == nil) and type(CACHE.gobbleEdges) == 'table' then src = CACHE.gobbleEdges end
    if type(src) ~= 'table' or next(src) == nil then src, label = VERMIN.GOBBLE_EDGES, 'VERMIN.GOBBLE_EDGES (port of roster2.py)' end
    if src[1] == nil then
        local rows = VERMIN.rosterRows(src)
        if rows then return rows, label .. ' (per species, from the roster build)' end
    end
    if src[1] == nil then   -- a guild -> vermin-guild map
        local rows = {}
        for g, list in pairs(src) do if type(list) == 'table' then rows[#rows+1] = { guild = g, vermin = list } end end
        table.sort(rows, function(a, b) return a.guild < b.guild end)
        return rows, label
    end
    return src, label
end
-- does consumer raw `cr` (pool entry `e`) carry DF's own GOBBLE_VERMIN_CLASS in its unmodified raws? Read before
-- the tool writes (gobbleApply runs after V7.restore), memoised per world in CACHE.gobbleNative.
function VERMIN.nativeGobbler(cr)
    CACHE.gobbleNative = CACHE.gobbleNative or {}
    local hit = CACHE.gobbleNative[cr.creature_id]
    if hit ~= nil then return hit end
    local yes = false
    for _, c in ipairs(cr.caste) do if #c.gobble_vermin_class > 0 or #c.gobble_vermin_creature > 0 then yes = true; break end end
    CACHE.gobbleNative[cr.creature_id] = yes
    return yes
end
function VERMIN.edgeMatch(row, cr, e)
    if row.native then return VERMIN.nativeGobbler(cr) end
    if row.token then return row.token == cr.creature_id end   -- v7.1 (fixes): a per-species row from the roster build
    if row.guild ~= e.guild then return false end
    if row.where == 'cave' then return e.layer == 'cavern' end
    if row.where == 'water' then return e.layer == 'water' or e.aquatic end
    return true
end
-- the SWV classes consumer `cr` should eat: the union of the rules and/or the edge table (cfg.vermin_eat.source),
-- less any class switched off (cfg.vermin_eat.classes). nil when nothing matches.
function VERMIN.gobbleWants(cr, e, cfg)
    local ve = (cfg or CACHE.cfg or {}).vermin_eat or {}
    local src, on = ve.source or 'both', ve.classes or {}
    local set, any = {}, false
    local function add(cls) if on[cls] ~= false then set[cls] = true; any = true end end
    if src ~= 'edges' then
        for _, rule in ipairs(VERMIN.GOBBLE_RULES) do
            if rule.match(cr, e) then for _, cls in ipairs(rule.classes) do add(cls) end end
        end
    end
    if src ~= 'rules' then
        for _, row in ipairs((VERMIN.edges())) do
            if VERMIN.edgeMatch(row, cr, e) then
                for _, vg in ipairs(row.vermin or {}) do for _, cls in ipairs(VERMIN.VCLASS[vg] or {}) do add(cls) end end
            end
        end
    end
    return any and set or nil
end
function VERMIN.gobbleApply(cfg, pool)
    if not V7.on(cfg, 'gobble') then return 0, 0, 0 end
    pool = pool or buildPool(cfg)
    local members = VERMIN.gobbleMembers(pool)
    local nTagged, nCons, nFall, byClass = 0, 0, 0, {}
    local on = (cfg.vermin_eat or {}).classes or {}   -- v7.1: a class switched off is neither tagged nor eaten
    for _, swv in ipairs(VERMIN.SWV) do
        if on[swv] ~= false and #members[swv] > 0 and VERMIN.gobbleClassVec(members[swv], swv) > 0 then nTagged = nTagged + 1 end
    end
    local seen = {}
    local shortN = cfg.v7.gobble_creature_fallback or 0
    for _, e in ipairs(pool) do
        local cr = not seen[e.token] and not e.locked and e.inEmbark and e.cat ~= 'vermin' and CAVERN.rawFor(e.token)
        if cr then
            seen[e.token] = true
            local want = VERMIN.gobbleWants(cr, e, cfg)
            if want then
                local classes = {}
                for cls in pairs(want) do classes[#classes+1] = cls end
                table.sort(classes)
                local wroteThis = false
                for _, cls in ipairs(classes) do
                    if VERMIN.gobbleWriteClass(cr, cls) then wroteThis = true end
                    if cls == 'SWV_GROUND_BUG' and VERMIN.gobbleWriteClass(cr, 'EDIBLE_GROUND_BUG') then wroteThis = true end
                    if shortN > 0 and #members[cls] > 0 and #members[cls] <= shortN then
                        for _, tok in ipairs(members[cls]) do
                            if VERMIN.gobbleWriteCreature(cr, tok) then wroteThis = true; nFall = nFall + 1 end
                        end
                    end
                    byClass[cls] = (byClass[cls] or 0) + 1
                end
                if wroteThis then nCons = nCons + 1 end
            end
        end
    end
    CACHE.gobble = { members = members, byClass = byClass, cons = nCons, tagged = nTagged, fallback = nFall }
    return nTagged, nCons, nFall
end
function VERMIN.gobbleStatus(cfg)
    if not V7.on(cfg, 'gobble') then return 'vermin gobble: off (v7 gobble off)' end
    local g = CACHE.gobble
    if not g then return 'vermin gobble: on, not yet applied this session (`v7 apply` or enable the rotation)' end
    local parts = {}
    for _, swv in ipairs(VERMIN.SWV) do
        local n = #(g.members[swv] or {})
        if n > 0 then parts[#parts+1] = ('%s=%d/%d'):format(swv, g.byClass[swv] or 0, n) end
    end
    return ('vermin gobble: on  %d species class-tagged  consumers by class (written/members): %s'):format(g.tagged, table.concat(parts, ' '))
end
--========================================================================================
-- ALERTS (v6.9.0): quiet wildlife fights
--========================================================================================
-- DF's announcement settings switch per report type (43 COMBAT_* types), never per who is fighting, so a fort full
-- of wildlife raises a COMBAT alert for every scuffle between two animals. A COMBAT alert lists its units
-- (report_unid), so the tool drops the ones that hold no humanoid: a creature some entity (civilisation) is made of,
-- an animal person (class ANIMAL_PERSON or an id ending MAN), a citizen, one of the fort's civilisation or anything the
-- fort controls. Custom entities (gnomes...) therefore always alert. The fight's reports stay in each animal's own
-- log; only the alert button goes. Measured (ECO A1/A2, 30 Sep 2026): wolves x deer 3 alerts dropped, 0 left; wolf
-- men x deer and goblins x deer kept; a save and reload with the filter running was fine.
local ALERTS = { JOB = MODULE .. '/alerts', CADENCE = 10 }
function ALERTS.humanoids()
    if CACHE.humanoid then return CACHE.humanoid end
    local h = {}
    for _, e in ipairs(df.global.world.raws.entities) do
        for _, cid in ipairs(e.creature_ids) do h[cid] = true end
    end
    for i, c in ipairs(df.global.world.raws.creatures.all) do
        if not h[i] then
            local ap = c.creature_id:match('MAN$') ~= nil
            if not ap and c.caste[0] then
                for _, cl in ipairs(c.caste[0].creature_class) do if cl.value == 'ANIMAL_PERSON' then ap = true; break end end
            end
            if ap then h[i] = true end
        end
    end
    CACHE.humanoid = h
    return h
end
function ALERTS.run()
    local c = CACHE.cfg or loadConfig()   -- the Panel switch turns it off between passes: stop at once
    if not (c.enabled and c.alerts and c.alerts.quiet_wildlife) then repeatUtil.cancel(ALERTS.JOB); return 0 end
    local al = df.global.world.status.announcement_alert
    if #al == 0 then return 0 end
    local h, dropped = ALERTS.humanoids(), 0
    for i = #al - 1, 0, -1 do
        local a = al[i]
        if a.type == df.announcement_alert_type.COMBAT then
            local keep = #a.report_unid == 0
            for j = 0, #a.report_unid - 1 do
                local u = df.unit.find(a.report_unid[j])
                if not u or h[u.race] or dfhack.units.isCitizen(u) or dfhack.units.isOwnCiv(u) or dfhack.units.isFortControlled(u) then keep = true; break end
            end
            if not keep then al:erase(i); dropped = dropped + 1 end
        end
    end
    return dropped
end
function ALERTS.schedule(cfg)
    if cfg.enabled and cfg.alerts and cfg.alerts.quiet_wildlife then
        V7.PERF.every(ALERTS.JOB, ALERTS.CADENCE, 'ticks', FUSE.job(ALERTS.JOB, ALERTS.run), V7.PERF.PHASE.alerts)
    else repeatUtil.cancel(ALERTS.JOB) end
end

--========================================================================================
-- SCAV (v6.9.0): scavenging, done by the tool
--========================================================================================
-- Nothing in DF eats or moves remains (ECO S: six corpses beside vultures, hyenas, bears, raccoons and wolves for
-- 4,000 ticks, none touched; BONECARN is documented as broken). What works (ECO S2): give the scavenger a full
-- tile-by-tile path (a destination alone moved nobody), and delete the remains once it stands beside them -- 3 of 6
-- hyenas walked 20 tiles in 300 ticks, 6 of 6 corpses went, and the deletion survived a save and reload. Underground a
-- straight line hit rock (HC1: 0 of 5 trolls arrived), so a path is given only along a clear line on one level.
-- Scavengers: BONECARN, the food thieves (CURIOUSBEAST_EATER), and the species whose raws describe carrion-eating.
-- Remains: corpses and pieces of wild, unnamed creatures lying loose -- never a citizen's, the fort's civilisation's,
-- a tame animal's or a humanoid's, never in a building or on a stockpile. Opt-in (Panel, `scavenge on`).
-- v7.0.0 (scav_ext, ECO SCV/SCVW/SCVC item 'Scavenging'): the plain walk-and-delete above only ever worked for
-- walking pack scavengers (wolves: 6 of 6 kangaroo carcasses). It failed for fliers (vultures never came near --
-- they do not walk a ground path), wanderers (jackals scattered instead of closing in), swimmers (alligators in
-- water: a land path cannot cross a water tile, so SCAV.line always returned nil), and land scavengers beside a
-- corpse that lies in water just past REACH=1 (wolves reached the bank and still could not eat). scav_ext adds,
-- behind its own v7 switch: a water-tile reach/fallback (wade and swim), and timed teleport fallbacks (the same
-- lever the ecology nudge uses, ecoPlaceNear/groundTile/waterTile) for fliers, swimmers and stuck wanderers.
-- v7.1 (scav stream; user R16, R17, R18, R42, 1 Oct 2026) -- NATURAL CADENCE (cfg.scavenge.natural, on by default).
-- v7.0 cleared remains like a sweep: every scavenger on the map was re-pathed every 200 ticks at any distance, a
-- whole corpse went in one pass, swimmers were teleported to the corpse in the first pass (SCV2Wb: 6 carp gone in
-- one pass, 0 walking) and a flier was landed beside it from anywhere after 600 ticks. v7.1 replaces that with:
--   discovery   each remains gets a delay when the tool first sees it, drawn log-normally around a median that
--               falls with its size (small 18 h, medium 10 h, large 6 h; sigma 0.6; clamped 2-96 h); a scavenger
--               d tiles away notices it only after that delay plus d x scent_ticks, and only inside its perception
--               (land 20, flier 40, swimmer 16 tiles) -- the rest never go unless they wander near
--   approach    walking only, a straight line on one level as before (SCAV.line, HC1), re-issued at most every
--               reissue_ticks; at most moves_pass moves a pass and moves_day a day, map-wide. A swimmer (no
--               walkable group in water) swims in hops of hop_tiles, one a pass. The teleport is the last resort:
--               a scavenger that has not closed 2 tiles in hop_wait ticks hops hop_tiles toward its remains -- never
--               from beyond hop_max tiles, never more than hops_day a day
--   eating      takes time: a feeder eats eat_rate x its own mass an hour, up to gorge x its mass a visit, then is
--               sated for sated_h hours and walks off; the remains is deleted only when its mass (the race's adult
--               size; a piece is piece_share of it) is gone -- so a big carcass takes several visits over days
--   sharing     at most `feeders` scavengers at one remains; a smaller species waits while a heavier one feeds
--   water       carnivorous swimmers count as scavengers (R42, R17: sharks, crocodiles, alligators, pond grabbers,
--               sea serpents...; MODEL.swimScavenger, the ecology stream's table and overrides) and
--               take only remains in or beside water, from the water; a land scavenger takes a wet remains from
--               the bank (walk to a ground tile beside it, then the wet reach: 2 tiles, z +-1)
-- Every timing is a cfg.scavenge number (SCAV.RANGE), `scavenge set KEY N`. Attribution (which species ate which
-- remains) is kept per species and per pair in the fort's site data (SCAV.STATS_KEY; `scavenge stats`) and one
-- ledger line per remains finished. State that every script copy must see (the verb, the window and the job run
-- separate copies) lives in CACHE.scav7, not in this table: in v7.0 SCAV.wait and SCAV.fallbacks were per copy, so
-- a `scavenge now` run as a command never saw a wait accumulate and its status always read 'fallbacks: 0'.
local SCAV = { JOB = MODULE .. '/scavenge', CADENCE = 200, REACH = 1, MAX_UNITS = 60, WAIT = 600,
               TEXT = { BIRD_VULTURE = true, BIRD_BUZZARD = true, BEAR_BLACK = true, JACKAL = true, HYENA = true,
                        BIRD_RAVEN = true, FLESH_BALL = true },
               STATS_KEY = MODULE .. '/scavstats',
               -- v7.1: every number in cfg.scavenge, { min, max, what it means }; read through SCAV.num
               RANGE = {
                   cadence           = { 50, 2400, 'ticks between passes (200 t = 4 in-game hours)' },
                   discover_small_h  = { 0, 480, 'median hours before a small remains (< 150 kg) can be found' },
                   discover_medium_h = { 0, 480, 'median hours before a medium remains (150-1,000 kg) can be found' },
                   discover_large_h  = { 0, 480, 'median hours before a large remains (>= 1,000 kg) can be found' },
                   discover_sigma    = { 0, 3, 'log-normal spread of the discovery delay (0 = always the median)' },
                   discover_min_h    = { 0, 480, 'shortest discovery delay, hours' },
                   discover_max_h    = { 0, 960, 'longest discovery delay, hours' },
                   scent_ticks       = { 0, 600, 'ticks added to the discovery per tile between scavenger and remains' },
                   perceive_land     = { 1, 200, 'tiles a land scavenger notices remains from' },
                   perceive_flier    = { 1, 200, 'tiles a flier notices remains from' },
                   perceive_swim     = { 1, 200, 'tiles a swimmer notices remains from' },
                   feeders           = { 1, 20, 'most scavengers at one remains at once' },
                   eat_rate          = { 0.001, 2, 'share of its own mass a feeder eats per in-game hour' },
                   gorge             = { 0.01, 5, 'share of its own mass a feeder eats in one visit, then it is sated' },
                   sated_h           = { 0, 480, 'hours a sated scavenger ignores remains' },
                   near_tiles        = { 1, 20, 'a visit goes on while the feeder stays this close (it is not pinned)' },
                   piece_share       = { 0.01, 1, 'a corpse piece as a share of its creature\'s mass' },
                   moves_pass        = { 0, 200, 'most walks and hops given in one pass, map-wide' },
                   moves_day         = { 0, 5000, 'most walks and hops given in one in-game day, map-wide' },
                   reissue_ticks     = { 0, 12000, 'ticks before the same scavenger is given its walk again' },
                   hop_tiles         = { 1, 50, 'tiles one hop (teleport fallback) covers' },
                   hop_wait          = { 0, 24000, 'ticks without 2 tiles of progress before a walker hops' },
                   hop_max           = { 0, 200, 'no hop from farther than this many tiles' },
                   hops_day          = { 0, 1000, 'most hops in one in-game day, map-wide' },
                   swim_min_kg       = { 0, 100000, 'a carnivorous swimmer lighter than this is not a scavenger' },
               } }
function SCAV.num(c, k)
    local r, v = SCAV.RANGE[k], (c.scavenge or {})[k]
    if type(v) ~= 'number' then SCAV.DEF = SCAV.DEF or defaultConfig().scavenge; v = SCAV.DEF[k] or r[1] end
    return math.max(r[1], math.min(r[2], v))
end
-- v7.1: shared state for every script copy (CACHE.scav7): the remains seen, per-unit claims, the day's budget, the
-- v7.0 wait/fallback tables, and the attribution counters (persisted in the fort's site data)
function SCAV.state()
    if CACHE.scav7 then return CACHE.scav7 end
    local st = { rem = {}, units = {}, day = -1, moves = 0, hops = 0, pass = 0, wait = {}, fallbacks = {}, raceOk = {} }
    local saved = dfhack.isMapLoaded() and dfhack.persistent.getSiteData(SCAV.STATS_KEY, nil) or nil
    st.stats = type(saved) == 'table' and saved or {}
    st.stats.by, st.stats.pairs = st.stats.by or {}, st.stats.pairs or {}
    st.stats.since = st.stats.since or (dfhack.isMapLoaded() and absTick() or 0)
    if dfhack.isMapLoaded() then CACHE.scav7 = st end
    return st
end
function SCAV.saveStats(st)
    if st.dirty and dfhack.isMapLoaded() then dfhack.persistent.saveSiteData(SCAV.STATS_KEY, st.stats) end
    st.dirty = false
end
-- the counters for one scavenger species: visits begun, kg eaten, remains finished, walks, hops, wet remains eaten
function SCAV.by(st, tok)
    local b = st.stats.by[tok]
    if not b then b = { visits = 0, kg = 0, finished = 0, walks = 0, hops = 0, wet = 0 }; st.stats.by[tok] = b end
    st.dirty = true
    return b
end
-- v7.1 (R42, R17): a carnivorous swimmer, by the ecology stream's MODEL.swimScavenger (water habitat and a predator's
-- diet; per-token overrides in hunters.swim_scav_list; off with hunters.swim_scav). The scav stream's local fallback
-- (SCAV.swimLocal) is gone since the merge; a failed lookup counts as no.
function SCAV.swimmer(craw)
    local ok, yes = pcall(MODEL.swimScavenger, craw)
    return ok and yes and true or false
end
-- 'bone' (BONECARN, CURIOUS_BEAST_EATER, SCAV.TEXT), 'swim' (a carnivorous swimmer) or false; per world (CACHE)
function SCAV.kind(craw)
    CACHE.scavKind = CACHE.scavKind or {}
    local hit = CACHE.scavKind[craw.creature_id]
    if hit ~= nil then return hit end
    local kind = false
    if not ALERTS.humanoids()[raceIndex(craw.creature_id)] then
        if SCAV.TEXT[craw.creature_id] or hasCasteFlag(craw, 'BONECARN') or hasCasteFlag(craw, 'CURIOUS_BEAST_EATER') then kind = 'bone'
        elseif SCAV.swimmer(craw) then kind = 'swim' end
    end
    CACHE.scavKind[craw.creature_id] = kind
    return kind
end
function SCAV.is(craw, c)
    local k = SCAV.kind(craw)
    if k == 'bone' then return true end
    if k ~= 'swim' then return false end
    c = c or CACHE.cfg or loadConfig()
    if c.scavenge.swimmers == false then return false end
    return adultSize(craw) / 1000 >= SCAV.num(c, 'swim_min_kg')
end
-- how it moves: 'flier', 'aquatic' (never leaves the water), 'amphibious' (water and land) or 'land'
function SCAV.mover(craw)
    if hasCasteFlag(craw, 'FLIER') then return 'flier' end
    local k = classify(craw)
    if k.habitat == 'aquatic' then return 'aquatic' end
    if k.aquatic then return 'amphibious' end
    return 'land'
end
function SCAV.edible(it, h)
    if it.flags.in_inventory or it.flags.in_building or it.flags.forbid or it.flags.on_fire then return false end
    if it.flags.in_job then return false end   -- v7.0.0: a dwarf is already hauling or butchering it
    if not V7.PERF.on('legacy_scav') then return V7.PERF.edibleRest(it, h) end   -- v7.1 (perf, P12): the slow half, memoized
    local ok, hf = pcall(function() return it.hist_figure_id end)
    if ok and hf and hf >= 0 then return false end
    if h[it.race] then return false end
    local okU, uid = pcall(function() return it.unit_id end)
    local u = okU and uid and uid >= 0 and df.unit.find(uid) or nil
    if u and (dfhack.units.isCitizen(u) or dfhack.units.isOwnCiv(u) or u.flags1.tame or dfhack.units.isFortControlled(u)) then return false end
    local x, y, z = dfhack.items.getPosition(it)
    if not x or dfhack.buildings.findAtTile(xyz2pos(x, y, z)) then return false end
    return true, x, y, z
end
-- v7.1 (R60, fb_safe): never the remains of a demon, forgotten beast, megabeast, night creature, undead or anything
-- GENERATED -- the tool has no impact on them, dead or alive. Natural and unclassified (domestic) races only.
function SCAV.naturalRemains(c, st, race)
    local hit = st.raceOk[race]
    if hit ~= nil then return hit end
    local cr = df.creature_raw.find(race)
    local cls = cr and ecoOf(c, cr)
    hit = (cls == 'natural' or cls == 'unclassified') or false
    st.raceOk[race] = hit
    return hit
end
-- a clear straight line on one level: every tile walkable and in the scavenger's walk group
function SCAV.line(u, tx, ty)
    local x, y, z = u.pos.x, u.pos.y, u.pos.z
    local grp = dfhack.maps.getWalkableGroup(u.pos)
    local xs, ys = {}, {}
    while x ~= tx or y ~= ty do
        if x ~= tx then x = x + (tx > x and 1 or -1) end
        if y ~= ty then y = y + (ty > y and 1 or -1) end
        if grp == 0 or dfhack.maps.getWalkableGroup(xyz2pos(x, y, z)) ~= grp then return nil end
        xs[#xs+1], ys[#ys+1] = x, y
    end
    return xs, ys
end
-- the plain v6.9 walk: a full tile-by-tile path to (tx, ty) on the scavenger's own level (ECO S2)
function SCAV.walk(u, tx, ty, tz)
    if tz ~= u.pos.z then return false end
    local xs, ys = SCAV.line(u, tx, ty)
    if not xs then return false end
    local p = u.path.path
    p.x:resize(0); p.y:resize(0); p.z:resize(0)
    for i = 1, #xs do p.x:insert('#', xs[i]); p.y:insert('#', ys[i]); p.z:insert('#', u.pos.z) end
    u.path.dest:assign(xyz2pos(tx, ty, tz))
    u.path.goal = df.unit_path_goal.SeekStation
    return true
end
-- v7.0.0 (scav_ext): a full water tile (tile water level >= 4/7, not magma), on the surface or in a cavern -- the test a corpse's
-- own tile is held to, so swimmers (and a land scavenger wading from a bank) can reach remains lying in water.
function SCAV.wet(x, y, z)
    local pos = xyz2pos(x, y, z)
    if not dfhack.maps.isValidTilePos(pos) then return false end
    local d = dfhack.maps.getTileFlags(pos)
    return d and d.flow_size >= 4 and not d.liquid_type or false
end
-- v7.0.0 (scav_ext): teleport a stuck scavenger to a free tile beside `best` -- the same lever the ecology nudge
-- uses (ecoPlaceNear/groundTile/waterTile) -- 2 tiles out, z +-1; `water` restricts the search to water tiles
-- only (swimmers never beach themselves), otherwise it is ground (fliers land, wanderers walk the last step in).
function SCAV.fallbackMove(u, best, water)
    local tile = water and waterTile or groundTile
    for r = 1, 2 do
        for _, dz in ipairs({ 0, -1, 1 }) do   -- the corpse's own level first, then one below, then one above
            for dx = -r, r do for dy = -r, r do
                if math.abs(dx) == r or math.abs(dy) == r then
                    local pos = tile(best.x + dx, best.y + dy, best.z + dz)
                    if pos and dfhack.units.teleport(u, pos) then return true end
                end
            end end
        end
    end
    return false
end
-- v7.1: one hop of at most `step` tiles toward (tx, ty, tz) -- the rate-limited last resort (and a swimmer's way of
-- moving through water). Within step + 2 tiles it lands beside the target (SCAV.fallbackMove); otherwise on a free
-- ground (or water) tile near the point `step` tiles along the straight line, on its own level first.
function SCAV.hop(u, tx, ty, tz, water, step)
    local x0, y0 = u.pos.x, u.pos.y
    local d = math.max(math.abs(tx - x0), math.abs(ty - y0))
    if d <= step + 2 then return SCAV.fallbackMove(u, { x = tx, y = ty, z = tz }, water) end
    local f = step / d
    local px, py = math.floor(x0 + (tx - x0) * f + 0.5), math.floor(y0 + (ty - y0) * f + 0.5)
    local tile = water and waterTile or groundTile
    for _, z in ipairs({ u.pos.z, tz, u.pos.z - 1, u.pos.z + 1 }) do
        for r = 0, 2 do
            for dx = -r, r do for dy = -r, r do
                if math.max(math.abs(dx), math.abs(dy)) == r then
                    local pos = tile(px + dx, py + dy, z)
                    if pos and dfhack.units.teleport(u, pos) then return true end
                end
            end end
        end
    end
    return false
end
function SCAV.dist(u, r) return math.max(math.abs(r.x - u.pos.x), math.abs(r.y - u.pos.y)) end
-- a log-normal draw around `median` (Box-Muller); sigma 0 gives the median
function SCAV.lognormal(median, sigma)
    if sigma <= 0 then return median end
    local u1, u2 = math.max(1e-9, math.random()), math.random()
    return median * math.exp(sigma * math.sqrt(-2 * math.log(u1)) * math.cos(2 * math.pi * u2))
end
-- v7.1: a remains the tool sees for the first time: its mass and the tick from which it can be found
function SCAV.newRemains(c, it, piece, now)
    local cr = df.creature_raw.find(it.race)
    local cm3 = cr and adultSize(cr) or 1000
    local kg = math.max(0.5, cm3 / 1000 * (piece and SCAV.num(c, 'piece_share') or 1))
    local band = MODEL.band(cm3 * (piece and SCAV.num(c, 'piece_share') or 1))
    local h = SCAV.lognormal(SCAV.num(c, 'discover_' .. band .. '_h'), SCAV.num(c, 'discover_sigma'))
    h = math.max(SCAV.num(c, 'discover_min_h'), math.min(SCAV.num(c, 'discover_max_h'), h))
    return { id = it.id, prey = cr and cr.creature_id or '?', piece = piece, kg = kg, left = kg, seen = now,
             found = now + math.floor(h * TICKS_PER_DAY / 24), feeders = {}, by = {} }
end
-- v7.1: where a wet remains can be reached from: `bank`, a ground tile within 2 (z 0, +1, -1) for land scavengers
-- and fliers; `water`, a water tile within 2 for swimmers (a dry remains with water beside it is a shore remains)
function SCAV.edge(r)
    local key = ('%d,%d,%d'):format(r.x, r.y, r.z)
    if r.edgeKey == key then return end
    r.edgeKey, r.bank, r.water = key, nil, nil
    for rr = 0, 2 do
        for dx = -rr, rr do for dy = -rr, rr do
            if math.max(math.abs(dx), math.abs(dy)) == rr then
                for _, dz in ipairs({ 0, 1, -1 }) do
                    local x, y, z = r.x + dx, r.y + dy, r.z + dz
                    if not r.bank and rr > 0 and groundTile(x, y, z) then r.bank = { x = x, y = y, z = z } end
                    if not r.water and SCAV.wet(x, y, z) then r.water = { x = x, y = y, z = z } end
                end
            end
        end end
    end
end
-- can this mover take this remains at all
function SCAV.suits(r, mover)
    if mover == 'amphibious' then return true end
    if mover == 'aquatic' then
        if r.wet then return true end
        SCAV.edge(r); return r.water ~= nil
    end
    if not r.wet then return true end
    SCAV.edge(r); return r.bank ~= nil
end
-- in reach to eat: 1 tile on its level; a wet or shore remains (or a swimmer eating), 2 tiles and z +-1
function SCAV.inReach(u, r, mover)
    local dz = math.abs(r.z - u.pos.z)
    local d = SCAV.dist(u, r)
    if r.wet or mover == 'aquatic' or mover == 'amphibious' then return dz <= 1 and d <= 2 end
    return dz == 0 and d <= SCAV.REACH
end
-- a smaller species keeps off while a heavier species feeds (kleptoparasitism: jackals wait for the lions)
function SCAV.deferred(c, r, tok, mass)
    if c.scavenge.defer_larger == false then return false end
    for _, f in pairs(r.feeders) do if f.tok ~= tok and f.mass > mass then return true end end
    return false
end
function SCAV.count(t) local n = 0; for _ in pairs(t) do n = n + 1 end; return n end
function SCAV.kin(r, tok) for _, f in pairs(r.feeders) do if f.tok == tok then return true end end; return false end
-- the nearest remains this scavenger has noticed and may join
function SCAV.pick(c, st, u, tok, mass, mover, now)
    local R = mover == 'flier' and SCAV.num(c, 'perceive_flier')
           or ((mover == 'aquatic' or mover == 'amphibious') and SCAV.num(c, 'perceive_swim')) or SCAV.num(c, 'perceive_land')
    if mover == 'amphibious' then R = math.max(R, SCAV.num(c, 'perceive_land')) end
    if not V7.on(c, 'scav_mapwide') then R = math.min(R, c.scavenge.radius) end
    local scent, cap = SCAV.num(c, 'scent_ticks'), SCAV.num(c, 'feeders')
    local best, bd
    for _, r in pairs(st.rem) do
        local dz = math.abs(r.z - u.pos.z)
        if dz == 0 or (dz == 1 and (r.wet or mover ~= 'land')) then
            local d = SCAV.dist(u, r)
            -- a remains already opened, or one its own kind is at, counts 4 tiles nearer: a pack finishes a carcass
            local de = d - ((r.left < r.kg or SCAV.kin(r, tok)) and 4 or 0)
            if d <= R and now >= r.found + d * scent and (not bd or de < bd) and SCAV.count(r.feeders) < cap
               and SCAV.suits(r, mover) and not SCAV.deferred(c, r, tok, mass) then best, bd = r, de end
        end
    end
    return best
end
-- v7.1: the remains is gone -- delete it, credit every species that fed on it, one ledger line
function SCAV.finish(st, r, now)
    if not dfhack.items.remove(r.it) then return false end
    st.rem[r.id] = nil
    local parts, main, mainKg = {}, nil, -1
    for tok, kg in pairs(r.by) do
        parts[#parts+1] = ('%s %.0f kg'):format(tok, kg)
        local p = st.stats.pairs[tok .. '>' .. r.prey] or { n = 0, kg = 0 }
        p.n, p.kg = p.n + 1, p.kg + kg
        st.stats.pairs[tok .. '>' .. r.prey] = p
        if r.wet then SCAV.by(st, tok).wet = SCAV.by(st, tok).wet + 1 end
        if kg > mainKg then main, mainKg = tok, kg end
    end
    if main then SCAV.by(st, main).finished = SCAV.by(st, main).finished + 1 end
    for uid in pairs(r.feeders) do local us = st.units[uid]; if us and us.target == r.id then us.target = nil end end
    table.sort(parts)
    LEDGER.add('eco', '', 'scavenging: a %s %s (%.0f kg%s) eaten -- %s; found %.0f h after the tool saw it, gone after %.1f days',
        r.prey, r.piece and 'piece' or 'corpse', r.kg, r.wet and ', in water' or '', table.concat(parts, ', '),
        (r.found - r.seen) / (TICKS_PER_DAY / 24), (now - r.seen) / TICKS_PER_DAY)
    st.dirty = true
    return true
end
-- v7.1: one scavenger's turn in a natural pass: keep feeding, walk back, choose a remains, approach it
function SCAV.turn(c, st, u, cr, now, last)
    local tok, H = cr.creature_id, TICKS_PER_DAY / 24
    local us = st.units[u.id]
    if not us then us = { sated = 0, ate = 0 }; st.units[u.id] = us end
    us.alive = st.pass
    if now < us.sated then return end
    local mover, mass = SCAV.mover(cr), math.max(0.2, adultSize(cr) / 1000)
    local r = us.target and st.rem[us.target]
    if not r then
        us.target = nil
        r = SCAV.pick(c, st, u, tok, mass, mover, now)
        if not r then return end
        us.target, us.since, us.d0, us.issued, us.ate, us.fedAt = r.id, now, SCAV.dist(u, r), nil, 0, nil
        r.feeders[u.id] = { tok = tok, mass = mass }
        SCAV.by(st, tok).visits = SCAV.by(st, tok).visits + 1
    end
    -- a visit begins in reach and goes on while the feeder stays within near_tiles (DF's AI moves it about; the tool
    -- does not pin it -- a vulture circling its carcass or a wolf stepping off is still at its meal)
    local atMeal = us.fedAt and math.abs(r.z - u.pos.z) <= 1 and SCAV.dist(u, r) <= SCAV.num(c, 'near_tiles')
    if atMeal or SCAV.inReach(u, r, mover) then
        -- feeding: eat_rate x own mass an hour, up to gorge x own mass this visit, never more than is left
        local cad = SCAV.num(c, 'cadence')
        local dt = math.max(0, math.min(2 * cad, now - (us.fedAt or (now - cad))))
        us.fedAt = now
        local cap = mass * SCAV.num(c, 'gorge') - us.ate
        local kg = math.max(0, math.min(mass * SCAV.num(c, 'eat_rate') * dt / H, cap, r.left))
        r.left, us.ate = r.left - kg, us.ate + kg
        r.by[tok] = (r.by[tok] or 0) + kg
        SCAV.by(st, tok).kg = SCAV.by(st, tok).kg + kg
        last.feeding = last.feeding + 1
        if r.left <= 0.001 then
            if SCAV.finish(st, r, now) then last.eaten = last.eaten + 1 end
            us.sated = now + math.floor(SCAV.num(c, 'sated_h') * H * math.min(1, us.ate / math.max(0.001, mass * SCAV.num(c, 'gorge'))))
            us.target = nil
        elseif us.ate >= mass * SCAV.num(c, 'gorge') - 1e-6 then
            us.sated, us.target = now + math.floor(SCAV.num(c, 'sated_h') * H), nil   -- full: it leaves, maybe to return
            r.feeders[u.id] = nil
        end
        return
    end
    -- approach, under the pass and day budgets
    if st.passMoves >= SCAV.num(c, 'moves_pass') or st.moves >= SCAV.num(c, 'moves_day') then last.waiting = last.waiting + 1; return end
    local d = SCAV.dist(u, r)
    if d <= (us.d0 or d) - 2 then us.d0, us.since = d, now end   -- progress: the hop clock starts again
    SCAV.edge(r)   -- the bank and water tiles beside it (cached per position)
    local inWater = SCAV.wet(u.pos.x, u.pos.y, u.pos.z)
    local water = mover == 'aquatic' or (mover == 'amphibious' and inWater and (r.wet or r.water ~= nil))
    local tx, ty, tz = r.x, r.y, r.z
    if water then
        if not r.wet and r.water then tx, ty, tz = r.water.x, r.water.y, r.water.z end
    elseif r.wet and r.bank then tx, ty, tz = r.bank.x, r.bank.y, r.bank.z end
    local function hop()
        if d > SCAV.num(c, 'hop_max') or st.hops >= SCAV.num(c, 'hops_day') then last.waiting = last.waiting + 1; return end
        if SCAV.hop(u, tx, ty, tz, water, SCAV.num(c, 'hop_tiles')) then
            st.hops, st.moves, st.passMoves = st.hops + 1, st.moves + 1, st.passMoves + 1
            st.fallbacks[tok] = (st.fallbacks[tok] or 0) + 1
            SCAV.by(st, tok).hops = SCAV.by(st, tok).hops + 1
            us.since, us.d0 = now, SCAV.dist(u, r)
            last.hops = last.hops + 1
        end
    end
    if water then hop(); return end   -- a swimmer has no walkable group in water: it swims in hops, one a pass
    if us.fedAt then us.fedAt = nil end   -- it wandered off its meal: the visit ends here; walking back is a new approach
    if not us.issued or now - us.issued >= SCAV.num(c, 'reissue_ticks') then
        if SCAV.walk(u, tx, ty, tz) then
            us.issued = now
            st.moves, st.passMoves = st.moves + 1, st.passMoves + 1
            SCAV.by(st, tok).walks = SCAV.by(st, tok).walks + 1
            last.walking = last.walking + 1
            return
        end
    end
    -- the last resort: no 2 tiles of progress in hop_wait ticks (a flier that ignores a ground path, a wanderer
    -- that turns away, a line through rock or water), and only from within hop_max tiles
    if now - (us.since or now) >= SCAV.num(c, 'hop_wait') then hop() else last.waiting = last.waiting + 1 end
end
function SCAV.runNatural(c, st, now)
    local last = { units = 0, remains = 0, walking = 0, feeding = 0, hops = 0, waiting = 0, eaten = 0, t = now, mode = 'natural' }
    local day = math.floor(now / TICKS_PER_DAY)
    if st.day ~= day then st.day, st.moves, st.hops = day, 0, 0 end
    st.passMoves, st.pass = 0, st.pass + 1
    local h = ALERTS.humanoids()
    -- the remains: every edible one, each seen once with its discovery clock; one gone by other means is forgotten
    local seenNow = {}
    local okV, vec = pcall(function() return df.global.world.items.other.ANY_CORPSE end)
    local CORPSE, PIECE = df.item_type.CORPSE, df.item_type.CORPSEPIECE
    for _, it in ipairs(okV and vec or df.global.world.items.all) do
        local t = it:getType()
        if t == CORPSE or t == PIECE then
            local ok, x, y, z = SCAV.edible(it, h)
            if ok and SCAV.naturalRemains(c, st, it.race) then
                local r = st.rem[it.id]
                if not r then r = SCAV.newRemains(c, it, t == PIECE, now); st.rem[it.id] = r end
                r.it, r.x, r.y, r.z = it, x, y, z
                r.wet = SCAV.wet(x, y, z)
                seenNow[it.id] = true
                last.remains = last.remains + 1
            end
        end
    end
    for id in pairs(st.rem) do if not seenNow[id] then st.rem[id] = nil end end
    -- the scavengers: wild, natural (fb_safe), never the magma sea or the underworld (R60)
    for _, u in ipairs(V7.PERF.wild()) do   -- v7.1 (perf, P4): the wild units of the census
        if last.units >= SCAV.MAX_UNITS then break end
        if WILD.onMap(u) then
            local cr = df.creature_raw.find(u.race)
            if cr and SCAV.is(cr, c) and WILD.layerOf(u) ~= 'deep' and V7.natural(c, u) then
                last.units = last.units + 1
                if last.remains > 0 then SCAV.turn(c, st, u, cr, now, last) end
            end
        end
    end
    -- claims of scavengers that left, died or were not seen this pass are let go
    for _, r in pairs(st.rem) do
        for uid in pairs(r.feeders) do
            local us = st.units[uid]
            if not us or us.alive ~= st.pass or us.target ~= r.id then r.feeders[uid] = nil end
        end
    end
    for uid, us in pairs(st.units) do if us.alive ~= st.pass and now >= us.sated then st.units[uid] = nil end end
    CACHE.scavLast = last
    return last.eaten
end
-- v7.0's pass, kept behind cfg.scavenge.natural = false (for comparison arms): every scavenger re-pathed to the
-- nearest remains every pass, a whole remains deleted on arrival, teleport fallbacks at any distance
function SCAV.runLegacy(c, st, now)
    local last = { units = 0, remains = 0, walking = 0, feeding = 0, hops = 0, waiting = 0, eaten = 0, t = now, mode = 'v7.0' }
    CACHE.scavLast = last   -- v7.1: written on every return path (a stale line repeated the last non-empty pass)
    local units = {}
    for _, u in ipairs(V7.PERF.wild()) do   -- v7.1 (perf, P4): the wild units of the census
        if #units < SCAV.MAX_UNITS and WILD.onMap(u) then
            local cr = df.creature_raw.find(u.race)
            if cr and SCAV.is(cr, c) and WILD.layerOf(u) ~= 'deep' and V7.natural(c, u) then units[#units+1] = u end
        end
    end
    last.units = #units
    if #units == 0 then return 0 end
    local h, rem = ALERTS.humanoids(), {}
    -- DF keeps corpses and body parts in one list (items.other.ANY_CORPSE); walk all items if a build lacks it
    local okV, vec = pcall(function() return df.global.world.items.other.ANY_CORPSE end)
    local CORPSE, PIECE = df.item_type.CORPSE, df.item_type.CORPSEPIECE
    for _, it in ipairs(okV and vec or df.global.world.items.all) do
        local t = it:getType()
        if t == CORPSE or t == PIECE then
            local ok, x, y, z = SCAV.edible(it, h)
            if ok and SCAV.naturalRemains(c, st, it.race) then
                local cr = df.creature_raw.find(it.race)
                rem[#rem+1] = { it = it, x = x, y = y, z = z, prey = cr and cr.creature_id or '?' }
            end
        end
    end
    last.remains = #rem
    if #rem == 0 then return 0 end
    -- v7.0.0 (scav_mapwide; user, 30 Sep 2026: "target remains and corpses anywhere as long as they are not in
    -- stockpiles"): no radius. SCAV.edible already refuses an item in a building or on any building's tile -- a
    -- stockpile is a building -- in an inventory, forbidden, burning, or a citizen's, a tame animal's or a named
    -- figure's; v7 adds an item a job holds. The walk still needs a clear line on one level (HC1), so a remains
    -- across a wall waits until the scavenger wanders into line.
    local ext = V7.on(c, 'scav_ext')
    local R, byTok = V7.on(c, 'scav_mapwide') and math.huge or c.scavenge.radius, {}
    local function inReach(u, best, wet)
        local dz = math.abs(best.z - u.pos.z)
        local d = math.max(math.abs(best.x - u.pos.x), math.abs(best.y - u.pos.y))
        if wet then return dz <= 1 and d <= 2 end
        return dz == 0 and d <= SCAV.REACH
    end
    local function eatOne(u, best, tok)
        if dfhack.items.remove(best.it) then
            best.gone = true; last.eaten = last.eaten + 1; byTok[tok] = (byTok[tok] or 0) + 1; st.wait[u.id] = nil
            local p = st.stats.pairs[tok .. '>' .. best.prey] or { n = 0, kg = 0 }
            p.n = p.n + 1; st.stats.pairs[tok .. '>' .. best.prey] = p
            SCAV.by(st, tok).finished = SCAV.by(st, tok).finished + 1
            return true
        end
        return false
    end
    local function fellBack(tok)
        st.fallbacks[tok] = (st.fallbacks[tok] or 0) + 1; SCAV.by(st, tok).hops = SCAV.by(st, tok).hops + 1
    end
    for _, u in ipairs(units) do
        local cr = df.creature_raw.find(u.race)
        local tok = cr.creature_id
        local flier = ext and V7.PERF.rawFlag(u.race, 'FLIER') or false   -- v7.1 (perf): per-world memo
        local swimmer = ext and not flier and classify(cr).aquatic or false
        local best, bd, wet = nil, nil, false
        for _, r in ipairs(rem) do
            if not r.gone then
                local w = r.wetv   -- v7.1 (perf, P12): once per remain per pass, not per scavenger x remain
                if w == nil then w = ext and SCAV.wet(r.x, r.y, r.z) or false; r.wetv = w end
                local dz = math.abs(r.z - u.pos.z)
                if (w and dz <= 1) or (not w and dz == 0) then
                    local d = math.max(math.abs(r.x - u.pos.x), math.abs(r.y - u.pos.y))
                    if d <= R and (not bd or d < bd) then best, bd, wet = r, d, w end
                end
            end
        end
        if not best then goto nextUnit end
        if inReach(u, best, wet) then
            eatOne(u, best, tok)
        elseif swimmer then
            if SCAV.fallbackMove(u, best, true) then
                fellBack(tok)
                if inReach(u, best, wet) then eatOne(u, best, tok) end
            end
        elseif flier then
            local w0 = st.wait[u.id]
            local walked = SCAV.walk(u, best.x, best.y, u.pos.z)
            if not walked or (w0 and now - w0.since >= SCAV.WAIT and bd > 2) then
                if SCAV.fallbackMove(u, best, false) then
                    fellBack(tok)
                    LEDGER.add('eco', '', 'scavenging: %s landed beside a corpse (fallback)', tok)
                    if inReach(u, best, wet) then eatOne(u, best, tok) end
                end
                st.wait[u.id] = nil
            else
                if not w0 then st.wait[u.id] = { since = now } end
                last.walking = last.walking + 1
            end
        else
            if SCAV.walk(u, best.x, best.y, u.pos.z) then
                last.walking = last.walking + 1
                if ext then
                    local w0 = st.wait[u.id]
                    if bd <= 6 then st.wait[u.id] = nil
                    elseif not w0 then st.wait[u.id] = { since = now, retried = false }
                    elseif now - w0.since >= SCAV.WAIT then
                        if not w0.retried then w0.retried, w0.since = true, now
                        else
                            if SCAV.fallbackMove(u, best, false) then
                                fellBack(tok)
                                if inReach(u, best, wet) then eatOne(u, best, tok) end
                            end
                            st.wait[u.id] = nil
                        end
                    end
                end
            elseif ext then st.wait[u.id] = nil end
        end
        ::nextUnit::
    end
    if last.eaten > 0 then
        local parts = {}
        for tok, n in pairs(byTok) do parts[#parts+1] = ('%s %d'):format(tok, n) end
        table.sort(parts)
        LEDGER.add('eco', '', 'scavenged %d remains (%s)', last.eaten, table.concat(parts, ', '))
    end
    return last.eaten
end
function SCAV.run()
    local c = CACHE.cfg or loadConfig()
    local now = absTick()
    if not (c.enabled and c.scavenge and c.scavenge.enabled) then
        -- v7.1 (open item scav-status-diagnostics): say why nothing ran, every time
        CACHE.scavLast = { units = 0, remains = 0, walking = 0, feeding = 0, hops = 0, waiting = 0, eaten = 0, t = now,
                           why = not c.enabled and 'the tool is disabled' or 'scavenging is switched off' }
        repeatUtil.cancel(SCAV.JOB); return 0
    end
    local st = SCAV.state()
    V7.PERF.scavPass()   -- v7.1 (perf, P12): ages the edible memo
    local ok, n = pcall(c.scavenge.natural ~= false and SCAV.runNatural or SCAV.runLegacy, c, st, now)
    for uid in pairs(st.wait) do   -- v7.1 (fixes, cache-world-switch-stale): a waiter that died or left is forgotten
        local u = df.unit.find(uid)
        if not u or dfhack.units.isDead(u) or not dfhack.units.isActive(u) then st.wait[uid] = nil end
    end
    SCAV.saveStats(st)
    if not ok then error(n) end
    return n
end
function SCAV.schedule(cfg)
    if cfg.enabled and cfg.scavenge and cfg.scavenge.enabled then
        V7.PERF.every(SCAV.JOB, SCAV.num(cfg, 'cadence'), 'ticks', FUSE.job(SCAV.JOB, SCAV.run), V7.PERF.PHASE.scav)
    else repeatUtil.cancel(SCAV.JOB) end
end
-- v7.1: let go of every walk the tool gave (disable, all off): a scavenger still bound for remains gets an empty path
-- and no goal, so DF's own AI takes it from here (a hop cannot be undone, as the ecology nudge's cannot)
function SCAV.release()
    local st = CACHE.scav7
    if not st or not dfhack.isMapLoaded() then return 0 end
    local n = 0
    for uid, us in pairs(st.units) do
        local u = us.target and df.unit.find(uid)
        local r = u and st.rem[us.target]
        if r and u.path.dest.x == (r.bank or r).x and u.path.dest.y == (r.bank or r).y then
            pcall(function()
                u.path.path.x:resize(0); u.path.path.y:resize(0); u.path.path.z:resize(0)
                u.path.goal = df.unit_path_goal.None
            end)
            n = n + 1
        end
    end
    st.units = {}
    for _, r in pairs(st.rem) do r.feeders = {} end
    return n
end
-- v7.1: the counters, newest first by kg -- `scavenge stats`, and SCAV.stats() for experiments
function SCAV.stats() return SCAV.state().stats end
function SCAV.statsLines()
    local s, out = SCAV.state().stats, {}
    local toks = {}
    for tok in pairs(s.by) do toks[#toks+1] = tok end
    table.sort(toks, function(a, b) return s.by[a].kg > s.by[b].kg end)
    out[#out+1] = ('scavenging by species since %s:'):format(dfhack.isMapLoaded() and LEDGER.stamp(s.since or 0) or '?')
    for _, tok in ipairs(toks) do
        local b = s.by[tok]
        out[#out+1] = ('  %-24s visits %-4d ate %6.0f kg  finished %-3d (%d in water)  walks %-4d hops %d')
            :format(tok, b.visits or 0, b.kg or 0, b.finished or 0, b.wet or 0, b.walks or 0, b.hops or 0)
    end
    if #toks == 0 then out[#out+1] = '  none yet' end
    local ps = {}
    for k, p in pairs(s.pairs) do ps[#ps+1] = ('%s %d (%.0f kg)'):format(k, p.n or 0, p.kg or 0) end
    table.sort(ps)
    out[#out+1] = 'remains finished, scavenger>remains: ' .. (#ps > 0 and table.concat(ps, ', ') or 'none')
    return out
end
function SCAV.status(cfg)
    local sc = cfg.scavenge
    local l = CACHE.scavLast
    local st = CACHE.scav7
    -- v7.1 (open item scav-status-diagnostics): 'on' only when a pass can run -- the tool enabled and the switch on
    local state = (cfg.enabled and sc.enabled) and 'on'
        or (sc.enabled and 'off (the tool is disabled; the scavenging switch is on)' or 'off')
    local mode
    if sc.natural ~= false then
        mode = ('natural cadence: found after ~%g/%g/%g h (small/medium/large), perception land %d, flier %d, swimmer %d tiles%s; %d feeders; %d moves a pass, %d a day; hops of %d tiles after %d t, from %d tiles at most, %d a day; carnivorous swimmers %s')
            :format(SCAV.num(cfg, 'discover_small_h'), SCAV.num(cfg, 'discover_medium_h'), SCAV.num(cfg, 'discover_large_h'),
                SCAV.num(cfg, 'perceive_land'), SCAV.num(cfg, 'perceive_flier'), SCAV.num(cfg, 'perceive_swim'),
                V7.on(cfg, 'scav_mapwide') and '' or (', capped at radius ' .. sc.radius),
                SCAV.num(cfg, 'feeders'), SCAV.num(cfg, 'moves_pass'), SCAV.num(cfg, 'moves_day'), SCAV.num(cfg, 'hop_tiles'),
                SCAV.num(cfg, 'hop_wait'), SCAV.num(cfg, 'hop_max'), SCAV.num(cfg, 'hops_day'), sc.swimmers == false and 'off' or 'on')
    else
        mode = 'v7.0 sweep: ' .. (V7.on(cfg, 'scav_mapwide') and 'map-wide, off stockpiles and buildings' or ('radius ' .. sc.radius))
    end
    local lastTxt = ''
    if l then
        local age = dfhack.isMapLoaded() and math.max(0, absTick() - (l.t or 0)) or 0
        lastTxt = l.why and ('  last pass %d t ago: nothing ran (%s)'):format(age, l.why)
            or ('  last pass %d t ago: %d scavenger(s), %d remains, %d walking, %d feeding, %d hops, %d waiting, %d eaten')
                :format(age, l.units, l.remains, l.walking, l.feeding or 0, l.hops or 0, l.waiting or 0, l.eaten)
    end
    local fb = {}
    for tok, n in pairs(st and st.fallbacks or {}) do fb[#fb+1] = ('%s %d'):format(tok, n) end
    table.sort(fb)
    return ('scavenging: %s  %s%s%s'):format(state, mode, lastTxt,
        #fb > 0 and ('  fallbacks: ' .. table.concat(fb, ', ')) or (V7.on(cfg, 'scav_ext') and '  fallbacks: 0' or ''))
end

--========================================================================================
-- VERMIN.FORAGE (v7.1; R21, R18, R63): vermin eaters drawn to the vermin really on the map
--========================================================================================
-- R21 (user, 1 Oct 2026): a colony's 'count' (bumblebee, termite: 14,000-19,000) is an industry size, never a swarm
-- on the map -- ECO VR/VRL/VRR (findings.md:175-182) aimed cats, peregrines and ducks at colony spots and nothing
-- happened, because there was nothing loose to eat. So availability here is read from the vermin objects DF keeps
-- (world.event.vermin; ECO VRM, vermin_count.lua): each LOOSE object is a real animal or swarm at a position with
-- an amount; a colony (flags.is_colony / is_roaming_colony, category Colony, or an INNUMERABLE amount) is a SITE,
-- a weak attractor (insect foragers drift near a hive) whose amount is never read as prey; vermin fish are loose
-- objects in water. The index is built once per draw pass, bucketed by 16x16 block, under a deadline.
-- The behaviour: every cfg.vermin_eat.cadence ticks, up to `budget` eligible eaters (a wild, natural, non-deep unit
-- whose caste carries GOBBLE_VERMIN_CLASS or _CREATURE -- DF's own gobblers and every consumer VERMIN.gobbleApply
-- wired), each with `chance` and at most once per `cooldown` ticks, pick a vermin spot within `radius` that their
-- own gobble tokens match (the live creature classes, so a class DF would not honour is never a target), weighted
-- by nearness, the swarm's size and a diversity discount on species drawn to recently, and are given a walking
-- path to it -- a straight line on their own level (SCAV's lever, ECO S2), through water for a swimmer and open
-- air for a flier, stopping at the bank or the last clear tile within REACH. No teleport ever (R18: natural
-- cadence, no zipping). DF's own gobble does the eating when they arrive (VRM2/VRM4: within the first 250 t of
-- arrival). Between draw passes a 100-tick step keeps each forager on its line (DF may re-plan a wanderer) a few
-- times, then lets it go. R63 (cheap): a target object gone while its forager stood within REACH is a 'likely
-- eaten'; gone with nobody near is 'gone'; still there after the forager arrived is 'missed'; and every draw pass
-- adds the map's loose amount per class to a trace, so a debit shows. The walk order is undone (path cleared) on
-- switch off, disable, all off; the state is dropped with the map.
VERMIN.FORAGE = { JOB = MODULE .. '/forage', STEP = 100, MS = 25, REACH = 2, EXPIRE = 1500, REISSUE = 3, TRACE = 24,
                  GRID = 16, TRIES = 4, CAND = 160, DECAY = 0.7,
                  DENY = { 'Flee', 'Attack', 'Kill', 'Hunt', 'Chase', 'Fight', 'Raid', 'Ambush', 'Leave', 'Steal',
                           'Capture', 'SeekStation' } }   -- SeekStation: SCAV's walkers (and ours, kept apart by pending)
function VERMIN.fstate()
    local st = CACHE.vforage
    if not st then
        st = { next = {}, pending = {}, nextDraw = 0, draws = {}, race = {}, eater = {}, match = {}, owner = false,
               trace = {}, last = nil, vsrc = nil, busyErr = nil,
               tot = { drawn = 0, arrived = 0, eaten = 0, missed = 0, gone = 0, expired = 0, colony = 0, noline = 0 },
               pairs = {} }
        CACHE.vforage = st
    end
    return st
end
-- the vermin object vector, probed once per map (both names tried: a pcall'd bad path must not read as 'no vermin')
function VERMIN.vector()
    local st = VERMIN.fstate()
    if st.vsrc == nil then
        st.vsrc = false
        if pcall(function() return #df.global.world.event.vermin end) then st.vsrc = 'world.event.vermin'
        elseif pcall(function() return #df.vermin.get_vector() end) then st.vsrc = 'df.vermin.get_vector()' end
    end
    if st.vsrc == 'world.event.vermin' then return df.global.world.event.vermin end
    if st.vsrc == 'df.vermin.get_vector()' then return df.vermin.get_vector() end
    return nil
end
-- the memos below read live creature classes and gobble vectors, which gobbleApply/V7.restore rewrite; they are
-- keyed to the CACHE.gobble record of the last apply and start over when it changes
function VERMIN.forageMemo(st)
    if st.owner ~= (CACHE.gobble or false) then st.owner = CACHE.gobble or false; st.race, st.eater, st.match = {}, {}, {} end
end
function VERMIN.raceInfo(st, race)
    local hit = st.race[race]
    if hit then return hit end
    local cr = df.creature_raw.find(race)
    local info = { tok = cr and cr.creature_id or ('#' .. race), swv = cr and VERMIN.swvClass(cr) or 'SWV_OTHER', cls = {} }
    if cr then
        for _, c in ipairs(cr.caste) do
            for _, s in ipairs(c.creature_class) do info.cls[(type(s) == 'string') and s or s.value] = true end
        end
    end
    st.race[race] = info
    return info
end
-- what a unit's caste gobbles: { cls = set, tok = set } or false
function VERMIN.eaterSet(st, u)
    local k = u.race .. ':' .. u.caste
    local hit = st.eater[k]
    if hit ~= nil then return hit end
    local cr = df.creature_raw.find(u.race)
    local c = cr and cr.caste[u.caste]
    local set, any = { cls = {}, tok = {} }, false
    if c then
        for _, s in ipairs(c.gobble_vermin_class) do set.cls[(type(s) == 'string') and s or s.value] = true; any = true end
        for _, s in ipairs(c.gobble_vermin_creature) do set.tok[(type(s) == 'string') and s or s.value] = true; any = true end
    end
    st.eater[k] = any and set or false
    return st.eater[k]
end
function VERMIN.eats(st, u, race)
    local k = u.race .. ':' .. u.caste
    local row = st.match[k]
    if not row then row = {}; st.match[k] = row end
    local hit = row[race]
    if hit ~= nil then return hit end
    local set, info = VERMIN.eaterSet(st, u), VERMIN.raceInfo(st, race)
    local yes = false
    if set then
        if set.tok[info.tok] then yes = true
        else for cls in pairs(info.cls) do if set.cls[cls] then yes = true; break end end end
    end
    row[race] = yes
    return yes
end
-- one pass over the vermin objects: loose entries bucketed by block, colony sites, live ids, totals by class and
-- species. Classes switched off (cfg.vermin_eat.classes) are counted in the census but never become targets.
function VERMIN.index(cfg, deadline)
    local st = VERMIN.fstate()
    local on = cfg.vermin_eat.classes
    local idx = { t = absTick(), src = st.vsrc, objs = 0, loose = 0, colonies = 0, hidden = 0, partial = false,
                  grid = {}, alive = {}, byClass = {}, bySpecies = {} }
    local vec = VERMIN.vector()
    idx.src = st.vsrc
    if not vec then return idx end
    local G, COL, INN = VERMIN.FORAGE.GRID, nil, INNUMERABLE
    pcall(function() COL = df.vermin_category.Colony end)
    local roam, hasId, hasCat = nil, nil, nil
    for i, v in ipairs(vec) do
        if i % 256 == 0 and FUSE.over(deadline) then idx.partial = true; break end
        local fl = v.flags
        if not fl.already_deleting then
            if roam == nil then
                roam = pcall(function() return fl.is_roaming_colony end)
                hasId = pcall(function() return v.id end)
                hasCat = COL ~= nil and pcall(function() return v.category end)
                st.noId = not hasId or nil   -- without an id, the object's address names it while it lives
            end
            local vid = hasId and v.id or tostring(v)
            idx.objs = idx.objs + 1
            idx.alive[vid] = true
            local info = VERMIN.raceInfo(st, v.race)
            local amount = v.amount or 1
            local colony = fl.is_colony or (roam and fl.is_roaming_colony) or amount >= INN or (hasCat and v.category == COL)
            local bc = idx.byClass[info.swv] or { loose = 0, amount = 0, colonies = 0, species = {} }
            idx.byClass[info.swv] = bc
            local bs = idx.bySpecies[info.tok] or { swv = info.swv, loose = 0, amount = 0, colonies = 0, hidden = 0 }
            idx.bySpecies[info.tok] = bs
            bc.species[info.tok] = true
            if colony then
                idx.colonies = idx.colonies + 1; bc.colonies = bc.colonies + 1; bs.colonies = bs.colonies + 1
            else
                idx.loose = idx.loose + 1; bc.loose = bc.loose + 1; bs.loose = bs.loose + 1
                bc.amount = bc.amount + amount; bs.amount = bs.amount + amount
            end
            if v.visible == false then idx.hidden = idx.hidden + 1; bs.hidden = bs.hidden + 1 end
            if on[info.swv] ~= false and v.visible ~= false then
                local w = colony and (cfg.vermin_eat.colony or 0) or (1 + 0.5 * math.log(math.min(math.max(amount, 1), 1000)))
                if w > 0 then
                    local k = (v.pos.z * 4096) + (v.pos.y // G) * 64 + (v.pos.x // G)
                    local b = idx.grid[k]
                    if not b then b = {}; idx.grid[k] = b end
                    b[#b+1] = { x = v.pos.x, y = v.pos.y, z = v.pos.z, race = v.race, id = vid, w = w, colony = colony or false }
                end
            end
        end
    end
    return idx
end
-- a straight line from the unit toward (tx, ty) on its own level, by mode: 'walk' (its walk group), 'swim' (deep
-- water, SCAV.wet) or 'fly' (any tile that is not wall). Stops at the first tile it cannot take; nil unless the
-- last tile reached is within REACH of the target. Returns xs, ys (possibly empty: already there).
function VERMIN.openTile(x, y, z)
    local tt = dfhack.maps.getTileType(x, y, z)
    if not tt then return false end
    local shape = df.tiletype.attrs[tt].shape
    return df.tiletype_shape.attrs[shape].basic_shape ~= df.tiletype_shape_basic.Wall
end
function VERMIN.approach(u, tx, ty, mode)
    local x, y, z = u.pos.x, u.pos.y, u.pos.z
    local grp = mode == 'walk' and dfhack.maps.getWalkableGroup(u.pos) or 0
    local m = df.global.world.map
    local xs, ys = {}, {}
    while x ~= tx or y ~= ty do
        local nx = x + (tx > x and 1 or (tx < x and -1 or 0))
        local ny = y + (ty > y and 1 or (ty < y and -1 or 0))
        if nx < 0 or ny < 0 or nx >= m.x_count or ny >= m.y_count then break end
        local ok
        if mode == 'walk' then ok = grp ~= 0 and dfhack.maps.getWalkableGroup({ x = nx, y = ny, z = z }) == grp
        elseif mode == 'swim' then ok = SCAV.wet(nx, ny, z)
        else ok = VERMIN.openTile(nx, ny, z) end
        if not ok then break end
        x, y = nx, ny
        xs[#xs+1], ys[#ys+1] = x, y
    end
    if math.max(math.abs(tx - x), math.abs(ty - y)) > VERMIN.FORAGE.REACH then return nil end
    return xs, ys
end
function VERMIN.walkPath(u, xs, ys)
    local p, z = u.path.path, u.pos.z
    p.x:resize(0); p.y:resize(0); p.z:resize(0)
    for i = 1, #xs do p.x:insert('#', xs[i]); p.y:insert('#', ys[i]); p.z:insert('#', z) end
    u.path.dest:assign({ x = xs[#xs], y = ys[#ys], z = z })
    u.path.goal = df.unit_path_goal.SeekStation
end
function VERMIN.moveMode(u)
    if SCAV.wet(u.pos.x, u.pos.y, u.pos.z) then return 'swim' end
    if dfhack.maps.getWalkableGroup(u.pos) ~= 0 then return 'walk' end
    local cr = df.creature_raw.find(u.race)
    if cr and cr.flags.HAS_ANY_FLIER then return 'fly' end
    return nil
end
-- is this unit busy with something a forage order must not override? A failed read is recorded, not taken as busy
function VERMIN.busy(st, u)
    local ok, busy = pcall(function()
        if u.job.current_job then return true end
        local name = df.unit_path_goal[u.path.goal]
        if name then for _, pat in ipairs(VERMIN.FORAGE.DENY) do if name:find(pat) then return true end end end
        return false
    end)
    if not ok then st.busyErr = tostring(busy):sub(1, 80); return false end
    return busy
end
-- an eligible forager: wild natural wildlife on the map (V7.natural: never a forgotten beast, megabeast, night
-- creature, undead or GENERATED), not tame, not of the magma sea or underworld (R60), whose caste gobbles, idle
function VERMIN.forager(cfg, st, u)
    if not VERMIN.eaterSet(st, u) then return false end
    if not WILD.onMap(u) or dfhack.units.isTame(u) or not V7.natural(cfg, u) then return false end
    -- v7.1 (fixes): SCAV.wait moved into the shared scav state (CACHE.scav7) in the scav stream; this read of the old
    -- per-copy table indexed nil. A scavenger waiting on, or walking to, remains is not sent foraging.
    local sst = CACHE.scav7
    if WILD.layerOf(u) == 'deep' or (sst and (sst.wait[u.id] or (sst.units[u.id] and sst.units[u.id].target))) then return false end
    return not VERMIN.busy(st, u)
end
-- pick and walk one forager; true when a walk was given (or it already stands at its target)
function VERMIN.forageOne(cfg, st, u, idx)
    local mode = VERMIN.moveMode(u)
    if not mode then return false end
    local ve, F = cfg.vermin_eat, VERMIN.FORAGE
    local R, G = ve.radius, F.GRID
    local dzMax = mode == 'walk' and 0 or 1
    local x, y, z = u.pos.x, u.pos.y, u.pos.z
    local cand, total = {}, 0
    for zz = z - dzMax, z + dzMax do
        for by = (y - R) // G, (y + R) // G do
            for bx = (x - R) // G, (x + R) // G do
                local b = idx.grid[zz * 4096 + by * 64 + bx]
                if b then
                    for _, e in ipairs(b) do
                        if #cand >= F.CAND then break end
                        local d = math.max(math.abs(e.x - x), math.abs(e.y - y))
                        if d <= R and VERMIN.eats(st, u, e.race) then
                            local w = e.w / (1 + (ve.diversity or 0) * (st.draws[e.race] or 0)) / (1 + d / 4)
                            cand[#cand+1] = { e = e, w = w }; total = total + w
                        end
                    end
                end
            end
        end
    end
    for _ = 1, F.TRIES do
        if #cand == 0 or total <= 0 then break end
        local r, pick = math.random() * total, #cand
        for i, c in ipairs(cand) do r = r - c.w; if r <= 0 then pick = i; break end end
        local c = table.remove(cand, pick); total = total - c.w
        local xs, ys = VERMIN.approach(u, c.e.x, c.e.y, mode)
        if xs then
            if #xs > 0 then VERMIN.walkPath(u, xs, ys) end
            local e, eTok = c.e, VERMIN.raceInfo(st, u.race).tok
            st.pending[u.id] = { tx = e.x, ty = e.y, tz = e.z, vid = e.id, race = e.race, colony = e.colony, mode = mode,
                                 t0 = idx.t, eTok = eTok, vTok = VERMIN.raceInfo(st, e.race).tok, reissue = 0,
                                 dx = #xs > 0 and xs[#xs] or nil, dy = #ys > 0 and ys[#ys] or nil, dz = z,
                                 arrived = #xs == 0 and idx.t or nil }
            st.draws[e.race] = (st.draws[e.race] or 0) + 1
            if #xs == 0 then st.tot.arrived = st.tot.arrived + 1; VERMIN.pairStat(st, st.pending[u.id], 'arrived') end
            return true
        end
        st.tot.noline = st.tot.noline + 1
    end
    return false
end
function VERMIN.pairStat(st, p, what)
    local k = p.eTok .. '>' .. p.vTok
    local r = st.pairs[k] or { drawn = 0, arrived = 0, eaten = 0, missed = 0, gone = 0 }
    st.pairs[k] = r
    r[what] = r[what] + 1
end
-- the 100-tick step: arrivals, and a forager DF re-planned is put back on its line a few times
function VERMIN.forageStep(st, now)
    local F = VERMIN.FORAGE
    for uid, p in pairs(st.pending) do
        local u = df.unit.find(uid)
        if not u or dfhack.units.isDead(u) or u.flags1.inactive then st.pending[uid] = nil
        elseif not p.arrived then
            if math.abs(u.pos.z - p.tz) <= 1 and math.max(math.abs(u.pos.x - p.tx), math.abs(u.pos.y - p.ty)) <= F.REACH then
                p.arrived = now; st.tot.arrived = st.tot.arrived + 1; VERMIN.pairStat(st, p, 'arrived')
            elseif p.dx and p.reissue < F.REISSUE and (u.path.dest.x ~= p.dx or u.path.dest.y ~= p.dy) and u.pos.z == p.dz then
                local xs, ys = VERMIN.approach(u, p.tx, p.ty, p.mode)
                if xs and #xs > 0 then VERMIN.walkPath(u, xs, ys); p.dx, p.dy, p.reissue = xs[#xs], ys[#ys], p.reissue + 1 end
            end
        end
    end
end
-- settle every pending forage against a fresh index (R63): likely eaten, gone, missed, expired, colony visit
function VERMIN.forageResolve(st, idx, now)
    local ate = {}
    for uid, p in pairs(st.pending) do
        local vanished = not idx.alive[p.vid]
        if p.colony then
            if p.arrived or now - p.t0 >= VERMIN.FORAGE.EXPIRE then
                if p.arrived then st.tot.colony = st.tot.colony + 1 else st.tot.expired = st.tot.expired + 1 end
                st.pending[uid] = nil
            end
        elseif vanished and not idx.partial then
            if p.arrived then
                st.tot.eaten = st.tot.eaten + 1; VERMIN.pairStat(st, p, 'eaten')
                local k = p.eTok .. '>' .. p.vTok
                ate[k] = (ate[k] or 0) + 1
            else st.tot.gone = st.tot.gone + 1; VERMIN.pairStat(st, p, 'gone') end
            st.pending[uid] = nil
        elseif now - p.t0 >= VERMIN.FORAGE.EXPIRE then
            if p.arrived then st.tot.missed = st.tot.missed + 1; VERMIN.pairStat(st, p, 'missed')
            else st.tot.expired = st.tot.expired + 1 end
            st.pending[uid] = nil
        end
    end
    return ate
end
-- the job: a cheap step every 100 ticks, a draw pass every cfg.vermin_eat.cadence ticks (or at once with force)
function VERMIN.forageRun(force)
    local c = CACHE.cfg or loadConfig()
    local ve = c.vermin_eat
    if not force and not (c.enabled and ve and ve.forage) then
        repeatUtil.cancel(VERMIN.FORAGE.JOB); VERMIN.forageRelease(); return 0
    end
    local st, now = VERMIN.fstate(), absTick()
    VERMIN.forageStep(st, now)
    if st.nextDraw - now > ve.cadence then st.nextDraw = now end   -- a clock jump or a shorter cadence
    if not force and now < st.nextDraw then return 0 end
    st.nextDraw = now + ve.cadence
    local deadline = FUSE.deadline(VERMIN.FORAGE.MS)
    VERMIN.forageMemo(st)
    local idx = VERMIN.index(c, deadline)
    local ate = VERMIN.forageResolve(st, idx, now)
    -- the R63 trace: the map's loose amount per class at each draw pass
    local snap = { t = now }
    for swv, bc in pairs(idx.byClass) do snap[swv] = bc.amount end
    st.trace[#st.trace+1] = snap
    while #st.trace > VERMIN.FORAGE.TRACE do table.remove(st.trace, 1) end
    for r, n in pairs(st.draws) do st.draws[r] = n * VERMIN.FORAGE.DECAY end
    for id, t in pairs(st.next) do if t <= now then st.next[id] = nil end end
    local eligible = {}
    for _, u in ipairs(V7.PERF.wild()) do   -- v7.1 (perf, P4): the wild units of the census
        if not st.pending[u.id] and (st.next[u.id] or 0) <= now and VERMIN.forager(c, st, u) then eligible[#eligible+1] = u end
    end
    for i = #eligible, 2, -1 do local j = math.random(i); eligible[i], eligible[j] = eligible[j], eligible[i] end
    local drawn = 0
    for _, u in ipairs(eligible) do
        if drawn >= ve.budget or FUSE.over(deadline) then break end
        if force or math.random() < ve.chance then
            st.next[u.id] = now + ve.cooldown
            if VERMIN.forageOne(c, st, u, idx) then
                drawn = drawn + 1; st.tot.drawn = st.tot.drawn + 1; VERMIN.pairStat(st, st.pending[u.id], 'drawn')
            end
        end
    end
    local nEat, parts = 0, {}
    for k, n in pairs(ate) do nEat = nEat + n; parts[#parts+1] = ('%s %d'):format(k, n) end
    if nEat > 0 and ve.log then
        table.sort(parts)
        LEDGER.add('eco', '', 'vermin: %d likely eaten by foragers (%s)', nEat, table.concat(parts, ', '):sub(1, 160))
    end
    local nSp = 0
    for _ in pairs(idx.bySpecies) do nSp = nSp + 1 end
    st.last = { t = now, eligible = #eligible, drawn = drawn, eaten = nEat, objs = idx.objs, loose = idx.loose,
                colonies = idx.colonies, species = nSp, partial = idx.partial, src = idx.src }
    return drawn
end
-- undo: every forage walk still in force is cleared (DF re-plans the unit); pending dropped. Returns units released.
function VERMIN.forageRelease()
    local st = CACHE.vforage
    if not st then return 0 end
    local n = 0
    for uid, p in pairs(st.pending) do
        local u = df.unit.find(uid)
        if u and p.dx and u.path.dest.x == p.dx and u.path.dest.y == p.dy and u.path.dest.z == p.dz then
            pcall(function()
                local q = u.path.path
                q.x:resize(0); q.y:resize(0); q.z:resize(0)
                u.path.dest:assign({ x = -30000, y = -30000, z = -30000 })
            end)
            pcall(function() u.path.goal = df.unit_path_goal.None end)
            n = n + 1
        end
    end
    st.pending = {}
    return n
end
function VERMIN.forageSchedule(cfg)
    if cfg.enabled and cfg.vermin_eat and cfg.vermin_eat.forage then
        V7.PERF.every(VERMIN.FORAGE.JOB, VERMIN.FORAGE.STEP, 'ticks', FUSE.job(VERMIN.FORAGE.JOB, VERMIN.forageRun), V7.PERF.PHASE.forage)
    else
        repeatUtil.cancel(VERMIN.FORAGE.JOB)
        if dfhack.isMapLoaded() then VERMIN.forageRelease() end
    end
end
function VERMIN.forageStatus(cfg)
    local ve = cfg.vermin_eat
    local off = {}
    for _, swv in ipairs(VERMIN.SWV) do if ve.classes[swv] == false then off[#off+1] = swv end end
    local st, l = CACHE.vforage, CACHE.vforage and CACHE.vforage.last
    local t = st and st.tot
    local n = 0
    if st then for _ in pairs(st.pending) do n = n + 1 end end
    return ('vermin forage: %s  every %d t, radius %d, budget %d, chance %.2f, cooldown %d, colony %.2f, diversity %.2f, source %s%s%s%s%s')
        :format(ve.forage and 'on' or 'off', ve.cadence, ve.radius, ve.budget, ve.chance, ve.cooldown, ve.colony, ve.diversity, ve.source,
            #off > 0 and ('  classes off: ' .. table.concat(off, ' ')) or '',
            l and ('  last pass: %d eligible, %d drawn, %d pending; %d loose / %d colony sites, %d species (%s%s)')
                :format(l.eligible, l.drawn, n, l.loose, l.colonies, l.species, l.src or 'NO VERMIN VECTOR', l.partial and ', PARTIAL' or '') or '',
            t and ('  since load: drawn %d, arrived %d, likely eaten %d, missed %d, gone %d, expired %d, colony visits %d, no line %d')
                :format(t.drawn, t.arrived, t.eaten, t.missed, t.gone, t.expired, t.colony, t.noline) or '',
            st and st.busyErr and ('  busy-check read failed: ' .. st.busyErr) or '')
end
-- `vermin census` (R21): the vermin really on the map, read from DF's objects -- loose animals and swarms by class
-- and species, colony sites (their amount is an industry size, never prey), hidden objects, and the eaters present
function VERMIN.censusLines(cfg)
    local st = VERMIN.fstate()
    VERMIN.forageMemo(st)
    local idx = VERMIN.index(cfg, FUSE.deadline(FUSE.SCAN_MS))
    local out = { ('vermin objects: %d (%d loose, %d colony sites, %d hidden) from %s%s%s'):format(idx.objs, idx.loose, idx.colonies,
        idx.hidden, idx.src or 'NO VERMIN VECTOR (neither world.event.vermin nor df.vermin.get_vector() read)',
        idx.partial and ' -- PARTIAL (scan deadline)' or '', st.noId and ' -- objects carry no id (addresses used)' or '') }
    out[#out+1] = ('%-18s %6s %8s %7s  %s'):format('CLASS', 'loose', 'amount', 'sites', 'SPECIES (loose amount / colony sites)')
    for _, swv in ipairs(VERMIN.SWV) do
        local bc = idx.byClass[swv]
        if bc then
            local sp = {}
            for tok in pairs(bc.species) do
                local bs = idx.bySpecies[tok]
                sp[#sp+1] = bs.colonies > 0 and ('%s %d/%dc'):format(tok, bs.amount, bs.colonies) or ('%s %d'):format(tok, bs.amount)
            end
            table.sort(sp)
            out[#out+1] = ('%-18s %6d %8d %7d  %s%s'):format(swv, bc.loose, bc.amount, bc.colonies, table.concat(sp, ', '):sub(1, 150),
                cfg.vermin_eat.classes[swv] == false and '  [class off]' or '')
        end
    end
    local eaters = {}
    for _, u in ipairs(df.global.world.units.active) do
        local set = VERMIN.eaterSet(st, u)
        if set and WILD.onMap(u) then
            local tok = VERMIN.raceInfo(st, u.race).tok
            local r = eaters[tok]
            if not r then
                local cls = {}
                for k in pairs(set.cls) do cls[#cls+1] = k end
                for k in pairs(set.tok) do cls[#cls+1] = k end
                table.sort(cls)
                r = { n = 0, cls = table.concat(cls, ' ') }; eaters[tok] = r
            end
            r.n = r.n + 1
        end
    end
    local el = {}
    for tok, r in pairs(eaters) do el[#el+1] = ('  %-22s x%-3d eats %s'):format(tok, r.n, r.cls:sub(1, 110)) end
    table.sort(el)
    out[#out+1] = ('wild vermin eaters on the map: %d species'):format(#el)
    for _, l in ipairs(el) do out[#out+1] = l end
    return out
end
-- `vermin eats` (R63): forage outcomes by eater > vermin pair, and the loose amount per class at each draw pass
function VERMIN.eatsLines()
    local st = CACHE.vforage
    if not st then return { 'vermin eats: no forage pass yet this session' } end
    local out, rows = {}, {}
    for k, r in pairs(st.pairs) do rows[#rows+1] = { k = k, r = r } end
    table.sort(rows, function(a, b) return a.r.drawn > b.r.drawn or (a.r.drawn == b.r.drawn and a.k < b.k) end)
    out[#out+1] = ('%-40s %5s %7s %6s %6s %5s'):format('EATER>VERMIN', 'drawn', 'arrived', 'eaten', 'missed', 'gone')
    for i, x in ipairs(rows) do
        if i > 30 then out[#out+1] = ('  ... %d more pairs'):format(#rows - 30); break end
        out[#out+1] = ('%-40s %5d %7d %6d %6d %5d'):format(x.k:sub(1, 40), x.r.drawn, x.r.arrived, x.r.eaten, x.r.missed, x.r.gone)
    end
    out[#out+1] = ('loose amount by class at each draw pass (oldest first, %d passes):'):format(#st.trace)
    for _, swv in ipairs(VERMIN.SWV) do
        local vals, any = {}, false
        for _, snap in ipairs(st.trace) do vals[#vals+1] = tostring(snap[swv] or 0); if snap[swv] then any = true end end
        if any then out[#out+1] = ('  %-18s %s'):format(swv, table.concat(vals, ' ')) end
    end
    return out
end

local function enableSched()
    local cfg = loadConfig(); cfg.enabled = true
    -- v6.3.0 (W1): the roster is made whole before any job reads it -- every managed species explicit, every
    -- active one seasoned -- so no pass ever meets a species it does not know how to treat
    if dfhack.isMapLoaded() then
        V7.WAT.autoLayer(cfg)   -- v7.1 (fixes, R45 ruling): the water layer on where the map has water, unless the player set it
        local pool = buildPool(cfg)
        ROSTER.normalize(cfg, pool); CACHE.managedPops()   -- the entry index is built at load, not on the first job's clock
        HUNT.apply(cfg, pool)   -- v6.6.0 (W6)
        CURIOUS.apply(cfg)      -- v6.9.0
        V7.apply(cfg, pool)     -- v7.0.0
    end
    saveConfig(cfg); lastSeason = nil
    FUSE.reset()
    V7.PERF.warm()   -- v7.1 (perf, P10): the load-time surveys, sliced over the next ticks
    V7.PERF.every(MODULE, 1, 'days', FUSE.job(MODULE, tick), V7.PERF.PHASE.daily)
    scheduleWater(cfg)
    STOCK.schedule(cfg)
    ALERTS.schedule(cfg)
    SCAV.schedule(cfg)   -- v6.9.0
    VERMIN.forageSchedule(cfg)   -- v7.1 (R21)
    CURIOUS.schedule(cfg)   -- v7.1 (scav, R30): thieves that stay
    if cfg.groups.enabled then scheduleGroups() end
end
local function disableSched()
    if dfhack.isMapLoaded() then
        local n = CAVERN.restoreAll()
        if n > 0 then print(('restored %d cavern creature frequencies'):format(n)) end
        local t = PATTERN.trickleRestore()
        if t > 0 then print(('restored %d cluster ranges (trickle)'):format(t)) end
        local z = PATTERN.sizeRestore()
        if z > 0 then print(('restored %d cluster ranges (group sizes)'):format(z)) end
        local h = HUNT.restore()
        if h > 0 then print(('restored %d vermin-hunting caste flags'):format(h)) end
        local cu = CURIOUS.restore()
        if cu > 0 then print(('restored %d curious-beast caste flags'):format(cu)) end
        local cr = CURIOUS.unreform()   -- v7.1 (scav): reformed thieves put back as DF had them
        if cr > 0 then print(('restored %d reformed curious beasts'):format(cr)) end
        SCAV.release()                  -- v7.1 (scav): walks the scavenging pass gave are let go
        local v7 = V7.restore()
        if v7 > 0 then print(('restored %d v7 raw writes (seasons, solitary package, fishers, gobble)'):format(v7)) end
        local vf = VERMIN.forageRelease()   -- v7.1 (R21)
        if vf > 0 then print(('released %d vermin forager walk(s)'):format(vf)) end
    end
    local cfg = loadConfig(); cfg.enabled = false
    V7.WAT.spillRoll(cfg, true)   -- v7.1 (fixes): the water season spill's borrowed seasons given back
    saveConfig(cfg)
    repeatUtil.cancel(MODULE); repeatUtil.cancel(GROUPS_JOB); repeatUtil.cancel(ECOLOGY_JOB); repeatUtil.cancel(WATER.JOB); repeatUtil.cancel(STOCK.JOB)
    repeatUtil.cancel(ALERTS.JOB); repeatUtil.cancel(VERMIN.FORAGE.JOB)
    repeatUtil.cancel(SCAV.JOB); repeatUtil.cancel(CURIOUS.JOB)   -- v7.1 (scav): the scavenging job outlived disable
    do local ok, n = pcall(IRRUPT.restoreAll, 'rotation disabled'); if ok and n > 0 then print(('restored %d irruption write(s)'):format(n)) end end   -- v7.1: every irruption write
end
-- v7.1 (Alpha Four 6.8, 6.13): after `undo` (console, window, browser) restored the config, the world follows it. The
-- undo verb only re-ran the season stocks (applyLive) and the window's Z nothing at all, so an undone hunters, extinct,
-- vermin or curious setting stayed written in the raws until the next load. Rotation on: the same path as enable (raws
-- restored and re-applied from the restored config, jobs re-armed), then the season stocks; off: everything restored.
function UNDO.after(c)
    if not dfhack.isMapLoaded() then return end
    CACHE.class = {}; CACHE.predset = nil   -- the model re-reads every creature (extinct, class and role settings)
    if c.enabled then enableSched(); applyLive(loadConfig(), df.global.cur_season) else disableSched() end
end
--========================================================================================
-- PANEL (v6.3.0, W8; alpha 1 steps 4.3 and 12.2): every switch, the jobs, all on / all off
--========================================================================================
-- The window's Panel tab reads this. SWITCHES are every on/off the tool has apart from single creatures,
-- each with a getter and a setter on the config; `optin` marks the ones a player turns on deliberately
-- (they change what animals do to the fort, or place animals), which 'all on' leaves as they were.
-- All off stops every job and puts back everything the tool wrote into the game -- cavern frequencies, the
-- trickle's cluster sizes, a coupling's closed pool, an irruption's flag -- and remembers the switches so
-- all on can restore them.
local PANEL = { SAVED_KEY = MODULE .. '/panel' }
PANEL.SWITCHES = {
    { id = 'rotation',  label = 'Seasonal rotation', note = 'the season roster at each boundary; out-of-season species held daily',
      get = function(c) return c.enabled end, set = function(c, v) c.enabled = v end },
    { id = 'land',      label = 'Layer: land', note = 'the surface: its roster, gate and groups', get = function(c) return c.layers.land end, set = function(c, v) c.layers.land = v end },
    { id = 'water',     label = 'Layer: water', note = 'rivers, lakes and sea: roster and placement', get = function(c) return c.layers.water end, set = function(c, v) c.layers.water = v; c.water.layer_set = true end },
    { id = 'cavern',    label = 'Layer: caverns', note = 'the three caverns: roster by frequency, gate', get = function(c) return c.layers.cavern end, set = function(c, v) c.layers.cavern = v end },
    { id = 'groups',    label = 'Groups and the arrival gate', note = 'tracks every group; releases DF\'s gate so groups share the map',
      get = function(c) return c.groups.enabled end, set = function(c, v) c.groups.enabled = v end },
    { id = 'cavegate',  label = 'Cavern gate', note = 'cavern groups gated on their own count and clock', get = function(c) return c.groups.cavern end, set = function(c, v) c.groups.cavern = v end },
    { id = 'cohesion',  label = 'Cohesion', note = 'a group keeps behind a leader: herd, pack, flock', get = function(c) return c.groups.cohesion end, set = function(c, v) c.groups.cohesion = v end },
    { id = 'ecology',   label = 'Ecology', note = 'predators and prey related in DF\'s table: predators hunt', get = function(c) return c.ecology.enabled end, set = function(c, v) c.ecology.enabled = v end },
    { id = 'nudge',     label = 'Nudge', note = 'a predator far from prey for 3,000 ticks is moved nearer', optin = true, get = function(c) return c.ecology.nudge ~= false end, set = function(c, v) c.ecology.nudge = v end },   -- v7.1 (R38): off by default, so opt-in
    { id = 'waterjob',  label = 'Water draws', note = 'the tool draws river, lake and pool groups (DF sends none in play)', get = function(c) return c.water.enabled end, set = function(c, v) c.water.enabled = v end },
    { id = 'deep',      label = 'Layer: deep', note = 'the magma sea\'s natural species, by frequency', get = function(c) return c.layers.deep end, set = function(c, v) c.layers.deep = v end },
    { id = 'coupling',  label = 'Coupling', note = 'a prey arrival calls its predators next', optin = true, get = function(c) return c.groups.coupling end, set = function(c, v) c.groups.coupling = v end },
    { id = 'livestock', label = 'Livestock as prey', note = 'your own animals become targets', optin = true, get = function(c) return c.ecology.livestock end, set = function(c, v) c.ecology.livestock = v end },
    { id = 'exhaust',   label = 'Exhaustion and replacement', note = 'a species out of stock mid-season: its nearest group-mate fills in',
      get = function(c) return c.exhaust.enabled end, set = function(c, v) c.exhaust.enabled = v end },
    { id = 'scavenge',  label = 'Scavenging', note = 'bone-eaters and food thieves walk to wild remains and eat them', optin = true,
      get = function(c) return c.scavenge.enabled end, set = function(c, v) c.scavenge.enabled = v end },
    { id = 'curiousreform', label = 'Curious thieves stay', note = 'a curious beast steals, then that animal loses the habit and stays',   -- v7.1 (scav, R30)
      get = function(c) return c.curious.reform ~= false end, set = function(c, v) c.curious.reform = v end },
    { id = 'quietfights', label = 'Quiet wildlife fights', note = 'no combat alert for fights with no humanoid in them',
      get = function(c) return c.alerts.quiet_wildlife end, set = function(c, v) c.alerts.quiet_wildlife = v end },
    { id = 'hunting',   label = 'Vermin hunting', note = 'predatory and water birds dive for vermin; small predators hunt them', optin = true,
      get = function(c) return c.hunting.enabled end, set = function(c, v) c.hunting.enabled = v end },
    { id = 'irruption', label = 'Cavern irruptions', note = 'the fort stirs a cavern; after a warning, waves of its dwellers surge (v7.1)', optin = true, get = function(c) return c.irruption.enabled end, set = function(c, v) c.irruption.enabled = v end },
    -- v7.1 (R21): vermin foraging (VERMIN.FORAGE)
    { id = 'forage',    label = 'Vermin foraging', note = 'vermin eaters walk to real vermin on the map; DF\'s gobble eats',
      get = function(c) return c.vermin_eat.forage end, set = function(c, v) c.vermin_eat.forage = v end },
}
function PANEL.jobs(cfg)
    return {
        { name = MODULE,      label = 'season roster', cadence = TICKS_PER_DAY,       on = cfg.enabled },
        { name = GROUPS_JOB,  label = 'groups and gate', cadence = GROUPS_CADENCE,    on = cfg.enabled and cfg.groups.enabled },
        { name = ECOLOGY_JOB, label = 'ecology', cadence = cfg.ecology.cadence,       on = cfg.enabled and cfg.groups.enabled and cfg.ecology.enabled },
        { name = ALERTS.JOB,  label = 'quiet fights', cadence = ALERTS.CADENCE,        on = cfg.enabled and cfg.alerts.quiet_wildlife },
        { name = SCAV.JOB,    label = 'scavenging', cadence = SCAV.num(cfg, 'cadence'), on = cfg.enabled and cfg.scavenge.enabled },
        { name = VERMIN.FORAGE.JOB, label = 'vermin foraging', cadence = VERMIN.FORAGE.STEP, on = cfg.enabled and cfg.vermin_eat.forage },   -- v7.1
        { name = CURIOUS.JOB, label = 'curious thieves', cadence = CURIOUS.num(cfg, 'cadence'), on = cfg.enabled and CURIOUS.on(cfg) },   -- v7.1 (scav)

    }
end
-- Put back every raw and flag the tool holds written. Returns a summary.
function PANEL.restoreAll()
    local out = {}
    if dfhack.isMapLoaded() then
        local n = CAVERN.restoreAll(); if n > 0 then out[#out+1] = n .. ' cavern frequencies' end
        local t = PATTERN.trickleRestore() + PATTERN.sizeRestore(); if t > 0 then out[#out+1] = t .. ' cluster sizes' end
        local h = HUNT.restore(); if h > 0 then out[#out+1] = h .. ' hunting flags' end
        local cu = CURIOUS.restore(); if cu > 0 then out[#out+1] = cu .. ' curious-beast flags' end
        local cr = CURIOUS.unreform(); if cr > 0 then out[#out+1] = cr .. ' reformed curious beasts' end   -- v7.1 (scav)
        SCAV.release()   -- v7.1 (scav)
        local v7 = V7.restore(); if v7 > 0 then out[#out+1] = v7 .. ' v7 raw writes' end
        local vf = VERMIN.forageRelease(); if vf > 0 then out[#out+1] = vf .. ' forager walks' end   -- v7.1
        local okI, ni = pcall(IRRUPT.restoreAll, 'all off')   -- v7.1: every irruption write (before g is loaded: it saves its own)
        if okI and ni > 0 then out[#out+1] = ni .. ' irruption writes' end
        local g = loadGroups()
        if g.exclusion then out[#out+1] = endCoupling(g) .. ' pool entries (coupling)' end
        saveGroups(g)
    end
    return #out > 0 and table.concat(out, ', ') or 'nothing held'
end
function PANEL.allOff(cfg)
    local keep = {}
    for _, sw in ipairs(PANEL.SWITCHES) do keep[sw.id] = sw.get(cfg) and true or false end
    dfhack.persistent.saveSiteData(PANEL.SAVED_KEY, keep)
    local restored = PANEL.restoreAll()
    for _, sw in ipairs(PANEL.SWITCHES) do if sw.id ~= 'land' and sw.id ~= 'water' and sw.id ~= 'cavern' and sw.id ~= 'deep' then sw.set(cfg, false) end end
    LEDGER.add('edit', '', 'all off: every job stopped; restored %s', restored)
    return restored
end
function PANEL.allOn(cfg)
    local keep = dfhack.persistent.getSiteData(PANEL.SAVED_KEY, nil)
    for _, sw in ipairs(PANEL.SWITCHES) do
        if keep and keep[sw.id] ~= nil then sw.set(cfg, keep[sw.id])
        elseif not sw.optin then sw.set(cfg, true) end
    end
    cfg.enabled = true
    LEDGER.add('edit', '', 'all on: %s', keep and 'the switches as they were before all off' or 'the usual set (opt-ins left as they were)')
    return keep ~= nil
end
-- v7.1 (user 4 Oct): `enable` turns EVERYTHING on: every panel switch (the opt-ins too), every layer the map has,
-- the extinct corrections, the Lua aquarium master and the native `aquarium` plugin (water you can see into). A fort's
-- first full enable builds its roster with the preset (one season each, every present layer); later ones never
-- reshuffle a roster the player has shaped (cfg.full_enable_roster). `enable rotation` is the old rotation-only switch.
function PANEL.enableAll()
    local out = {}
    local c = loadConfig()
    if dfhack.isMapLoaded() and not c.full_enable_roster then
        captureDefault(c)
        local pool, biomeSet = buildPool(c)
        local name, allowed, seasons, layerNote = applyPreset(c, pool, biomeSet)
        c.full_enable_roster = true
        out[#out+1] = ('roster: preset %s, %d species active, one season each on %d; %s'):format(name, allowed, seasons, layerNote)
    end
    -- every switch, every layer: a layer with nothing on the map to manage simply stays idle
    for _, sw in ipairs(PANEL.SWITCHES) do sw.set(c, true) end
    if dfhack.isMapLoaded() then ROSTER.normalize(c, buildPool(c)) end   -- the new layers' species join the roster whole
    c.extinct.fix = true
    c.aquarium.enabled = true
    c.aquarium.legend = true
    c.enabled = true
    saveConfig(c)
    enableSched()
    if dfhack.isMapLoaded() then applyLive(loadConfig(), df.global.cur_season) end
    local on = {}
    for _, sw in ipairs(PANEL.SWITCHES) do if sw.get(loadConfig()) then on[#on+1] = sw.id end end
    out[#out+1] = ('switches on (%d of %d): %s'):format(#on, #PANEL.SWITCHES, table.concat(on, ' '))
    local ls = {}; for _, l in ipairs(LAYERS) do ls[#ls+1] = l .. '=' .. (loadConfig().layers[l] and 'on' or 'off') end
    out[#out+1] = 'layers: ' .. table.concat(ls, '  ') .. '; extinct corrections on; aquarium on'
    -- the native plugin: enable (it turns its depth on with the map) and force depth on in case it was turned off
    local okE = pcall(dfhack.run_command_silent, 'enable', 'aquarium')
    local t, plug = {}, false
    if okE and pcall(dfhack.open_plugin, t, 'aquarium') and t.isEnabled then plug = t.isEnabled() == true end
    if plug and dfhack.isMapLoaded() then pcall(dfhack.run_command_silent, 'aquarium-plugin', 'depth', 'on') end
    out[#out+1] = plug and 'aquarium plugin: enabled, depth on (water you can see into, foam, shimmer, streaks)'
        or 'aquarium plugin: NOT available (install aquarium.plug.dll into DFHack/hack/plugins for the full water look)'
    LEDGER.add('edit', '', 'enable: everything on')
    return out
end
function PANEL.fps()
    local ok, e = pcall(function() return df.global.enabler end)
    if not ok or not e then return nil end
    return e.calculated_fps, e.fps   -- READ ONLY: writing either to 0 freezes DF for good
end

--========================================================================================
-- PERF (v7.1, perf stream; R48, R55; DwarfCron data/perf/SW-PERF-ANALYSIS.md, docs/v7.1/perf.md)
--========================================================================================
-- Every cache here is shared (CACHE, one per DFHack session, see the CACHE note) and every one has a stated owner of its
-- invalidation: world unload (raws), map load/unload (CACHE.drop), CACHE.ver (a config save), or a tool placement.
-- P0: DFHack's own counters (r1.1 and r2 carry getPerfCounters; feature-detected all the same)
function V7.PERF.counters()
    local f = dfhack.internal and dfhack.internal.getPerfCounters
    if not f then return nil, 'dfhack.internal.getPerfCounters is not in this DFHack build' end
    local ok, summary, _, _, _, _, perRepeat, perWidget = pcall(f)
    if not ok then return nil, tostring(summary) end
    return { summary = summary or {}, rep = perRepeat or {}, widget = perWidget or {} }
end
function V7.PERF.lines()
    local out = {}
    local names = {}
    for n in pairs(FUSE.stats) do names[#names+1] = n end
    table.sort(names)
    out[#out+1] = ('%-34s %6s %6s %6s %5s %8s %9s %9s %5s'):format('job / lap', 'runs', 'last', 'worst', 'over', 'ms/run', 'KB last', 'KB worst', 'defer')
    for _, n in ipairs(names) do
        local st = FUSE.stats[n]
        out[#out+1] = ('%-34s %6d %6d %6d %5d %8.1f %9s %9s %5d'):format((n:gsub('^' .. MODULE, '~')), st.runs or 0, st.last or 0, st.worst or 0,
            st.over or 0, st.ms_sum and st.runs > 0 and st.ms_sum / st.runs or 0,
            st.kb and ('%.0f'):format(st.kb) or '-', st.kb_worst and ('%.0f'):format(st.kb_worst) or '-', st.deferred or 0)
    end
    local W = CACHE.perfTickWorst
    out[#out+1] = W and ('worst single tick: %d ms (tick %d: %s); ticks shared by two or more jobs: %d'):format(W.ms, W.tick, W.jobs, CACHE.perfShared or 0)
                 or 'worst single tick: none recorded yet'
    local c, why = V7.PERF.counters()
    if not c then out[#out+1] = 'perf counters: ' .. why; return out end
    local el = (c.summary.elapsed_ms or 0)
    out[#out+1] = ('DFHack perf counters: elapsed %d ms (%s), lua updates %d ms, overlay %d ms'):format(el,
        c.summary.unpaused_only == 1 and 'unpaused only' or 'paused too', c.summary.update_lua_ms or 0, c.summary.total_overlay_ms or 0)
    local rows = {}
    for n, ms in pairs(c.rep) do if tostring(n):find(MODULE, 1, true) then rows[#rows+1] = { n = tostring(n), ms = ms } end end
    for n, ms in pairs(c.widget) do if tostring(n):find(MODULE, 1, true) then rows[#rows+1] = { n = 'overlay ' .. tostring(n), ms = ms } end end
    table.sort(rows, function(a, b) return a.n < b.n end)
    for _, r in ipairs(rows) do
        out[#out+1] = ('  %-40s %8d ms  %6.2f%% of elapsed'):format(r.n, r.ms, el > 0 and 100 * r.ms / el or 0)
    end
    if #rows == 0 then out[#out+1] = '  (no seasonal-wildlife repeat or overlay recorded since the last reset)' end
    return out
end
function V7.PERF.reset()
    for k in pairs(FUSE.stats) do FUSE.stats[k] = nil end
    CACHE.perfTick, CACHE.perfTickWorst, CACHE.perfShared = nil, nil, 0
    local f = dfhack.internal and dfhack.internal.resetPerfCounters
    if f then pcall(f) end
end
function V7.PERF.statusLine()
    local W, on = CACHE.perfTickWorst, {}
    for _, k in ipairs{ 'stagger', 'events', 'slice', 'forEachTile' } do if V7.PERF.on(k) then on[#on+1] = k end end
    local leg = {}
    for k in pairs(V7.PERF.DEF) do if k:match('^legacy_') and V7.PERF.on(k) then leg[#leg+1] = k:sub(8) end end
    table.sort(leg)
    -- v7.1-perf2: passes that waited on a load-time scan this map (V7.PERF.passWaits), and whether one is running
    local scans = {}
    for _, n in ipairs({ 'warm', 'wbscan' }) do if V7.PERF.warming(n) then scans[#scans+1] = n end end
    return ('perf: %s; legacy paths: %s; worst tick %s; caches %s; load scans %s, passes waited: survey %d, registry %d  (`perf` for the table)'):format(table.concat(on, ' '),
        #leg > 0 and table.concat(leg, ' ') or 'none', W and (W.ms .. ' ms') or '-', V7.PERF.cacheLine and V7.PERF.cacheLine() or '-',
        #scans > 0 and ('running: ' .. table.concat(scans, ' ')) or 'done', CACHE.warmWaits or 0, CACHE.wbWaits or 0)
end
-- P1: per-race memos. raceTok (race index -> raw id) lives for the world; raceEco (race -> ecoOf class) is keyed by
-- CACHE.ver and only used when the caller's config IS the cached one (or nil, which ecoOf reads as the cached one):
-- a verb or window holding an edited copy gets a fresh answer.
-- P2: compact write-through. saveSiteDataString (r1.1 and r2) with json.encode(pretty=false); the reader is unchanged
-- (getSiteData decodes compact JSON the same). Falls back to saveSiteData if either is missing or the encode raises.
function V7.PERF.persist(key, data)
    local put = dfhack.persistent.saveSiteDataString
    if put then
        local ok, txt
        if not V7.PERF.on('legacy_json') then ok, txt = pcall(V7.PERF.encode, data) end   -- a4fix perf (P2b)
        if not ok then ok, txt = pcall(function() return require('json').encode(data, { pretty = false }) end) end
        if ok and type(txt) == 'string' then put(key, txt); return end
    end
    dfhack.persistent.saveSiteData(key, data)
end
-- P2b (a4fix perf): the groups record cost ~18 ms to save on every groups pass on RinghatchetsReady (alpha 4 round
-- 003228: groups:save last 18, worst 25; section 7: worst 16-18). DFHack's encoder (json/internal.lua, Friedl's JSON.lua)
-- does per table: two key lists built with table.insert, a sort of the keys (even compact), a tostring(T) probe, and
-- per key a gsub of the key, a gsub of every string value and a string.format of the pair. This writes the SAME JSON
-- values in one pass over the table into one buffer: plain ASCII strings (no quote, backslash, slash or control byte)
-- are copied as they are, any other string goes through the same gsub with the same replacements; numbers are
-- tostring with JSON.lua's NaN/inf spellings; an array is exactly JSON.lua's (only positive numeric keys below
-- math.huge: 1..max, holes null); a table with string keys only is an object. Anything else -- mixed or non-positive
-- numeric keys, boolean keys, a metatable, nesting past 64 -- is handed to DFHack's encoder for that table alone, so its
-- text is JSON.lua's. Object keys come out in pairs() order instead of sorted, which getSiteData's decode does not see:
-- decode(this) equals decode(json.encode(x, {pretty=false})) for every record (tests: host check on the saved records).
-- A function or userdata value raises, and persist then falls back to DFHack's encoder (which raises as it always did).
-- Why not save less often: DFHack writes its site data to disk when it first sees a save request (Core::doUpdate, before
-- any Lua timer of that frame runs; r2 library/Core.cpp:1546-1551), and Lua gets no event before it (SC_WORLD_UNLOADED
-- comes after the write). A record held back for N passes would be N passes stale in any save made meanwhile -- an
-- autosave, a quicksave, a manual save -- so the record stays written through on every save, and the write is made cheap.
-- perf legacy json on = DFHack's encoder (compact), as before.
V7.PERF.JSON_ESC = '[%"%\\/%z\001-\031]'
V7.PERF.JSON_REP = { ['\n'] = '\\n', ['\r'] = '\\r', ['\t'] = '\\t', ['\b'] = '\\b', ['\f'] = '\\f', ['"'] = '\\"', ['\\'] = '\\\\', ['/'] = '/' }
function V7.PERF.jsonRep(c) return V7.PERF.JSON_REP[c] or ('\\u%04x'):format(c:byte()) end
function V7.PERF.encode(data)
    local out, n, Q = {}, 0, {}
    local find, gsub, huge, PAT, REP = string.find, string.gsub, math.huge, V7.PERF.JSON_ESC, V7.PERF.jsonRep
    local json
    local function q(s)   -- a string as JSON, memoized for the call (keys and tokens repeat in every group)
        local r = Q[s]
        if r then return r end
        if find(s, PAT) then r = '"' .. gsub(s, PAT, REP) .. '"' else r = '"' .. s .. '"' end
        Q[s] = r
        return r
    end
    local function scalar(v, t)
        if t == 'string' then return q(v)
        elseif t == 'number' then return (v ~= v and 'null') or (v >= huge and '1e+9999') or (v <= -huge and '-1e+9999') or tostring(v)
        elseif t == 'boolean' then return v and 'true' or 'false' end
        error('V7.PERF.encode: cannot write a ' .. t)
    end
    local enc
    enc = function(v, depth)
        local t = type(v)
        n = n + 1
        if t ~= 'table' then out[n] = (v == nil) and 'null' or scalar(v, t); return end
        local str, num, other, max = false, false, getmetatable(v) ~= nil or depth >= 64, 0
        if not other then
            for k in pairs(v) do
                local kt = type(k)
                if kt == 'string' then str = true
                elseif kt == 'number' and k > 0 and k < huge then num = true; if k > max then max = k end
                else other = true; break end
            end
        end
        if other or (str and num) then
            json = json or require('json')
            out[n] = json.encode(v, { pretty = false })
        elseif num then
            out[n] = '['
            for i = 1, max do
                local x = v[i]
                local tx = type(x)
                if tx == 'table' then
                    if i > 1 then n = n + 1; out[n] = ',' end
                    enc(x, depth + 1)
                else n = n + 1; out[n] = (i > 1 and ',' or '') .. ((x == nil) and 'null' or scalar(x, tx)) end
            end
            n = n + 1; out[n] = ']'
        elseif str then
            out[n] = '{'
            local sep = ''
            for k, x in pairs(v) do
                local tx = type(x)
                n = n + 1
                if tx == 'table' then out[n] = sep .. q(k) .. ':'; enc(x, depth + 1)
                else out[n] = sep .. q(k) .. ':' .. scalar(x, tx) end
                sep = ','
            end
            n = n + 1; out[n] = '}'
        else out[n] = '[]' end
    end
    enc(data, 0)
    return table.concat(out)
end
-- Every perf cache and the event it dies with. Map load/unload: the map's records and derived state. World unload: the
-- raw-keyed memos too (raws reload with the world).
function V7.PERF.drop(world)
    CACHE.groups, CACHE.undo, CACHE.census, CACHE.raceEco, CACHE.poolMemo, CACHE.ovl = nil, nil, nil, nil, nil, nil
    CACHE.wildIds, CACHE.wildSeedAt, CACHE.scavMemo, CACHE.webStatic, CACHE.perfTick = nil, nil, nil, nil, nil
    if CACHE.slices then for _, sl in pairs(CACHE.slices) do sl.dead = true end; CACHE.slices = nil end
    CACHE.warmWaits, CACHE.wbWaits, CACHE.ecoPassT0 = nil, nil, nil   -- v7.1-perf2: per map
    if world then CACHE.ecoClass, CACHE.raceTok, CACHE.rawFlag = nil, nil, nil end
end
-- P5: each repeat starts behind a one-shot tick timeout, so jobs scheduled together never share a tick at the default
-- cadences (groups 300 at +31 (the load-time slice's head start, P10), ecology 3000 at +150, daily at +77, scavenging 200 at +37, alerts 10 at +5, curious 50 at
-- +23, forage 100 at +61: no two coincide). The pending start is registered in repeat-util's own table, so every
-- existing repeatUtil.cancel(name) cancels it, and isScheduled(name) is true while it waits. Tick timeouts die with the
-- world. perf stagger off = scheduleEvery at once, as before.
V7.PERF.PHASE = { groups = 31, daily = 77, ecology = 150, scav = 37, alerts = 5, curious = 23, forage = 61 }
function V7.PERF.every(name, delta, unit, fn, phase)
    local R = type(repeatUtil.repeating) == 'table' and repeatUtil.repeating or nil
    if not (V7.PERF.on('stagger') and R and phase and phase > 0 and dfhack.isMapLoaded()) then
        return repeatUtil.scheduleEvery(name, delta, unit, fn)
    end
    repeatUtil.cancel(name)
    local id
    id = dfhack.timeout(phase, 'ticks', function()
        local now = type(repeatUtil.repeating) == 'table' and repeatUtil.repeating or {}
        if now[name] == id then now[name] = nil; repeatUtil.scheduleEvery(name, delta, unit, fn) end
    end)
    if not id then return repeatUtil.scheduleEvery(name, delta, unit, fn) end
    R[name] = id
end
-- P7: the jobs read the shared config (CACHE.cfg) instead of a deep copy of it each pass. Audited writers on the job paths
-- (every saveConfig caller reachable from tick, groupsJob or ecologyJob): ROSTER.exhaustRoll/exhaustCheck and
-- V7.WAT.spillRoll/spillCheck. They mutate the table they are given, so the job hands them a private copy when one of
-- them has work (writersDue; tick() at a season change). CURIOUS, SCAV, ALERTS and the forager already read CACHE.cfg.
-- perf legacy_cfg on = loadConfig()'s deep copy every pass, as before.
function V7.PERF.cfgRO()
    if V7.PERF.on('legacy_cfg') then return loadConfig() end
    if not CACHE.cfg then loadConfig() end
    return CACHE.cfg
end
function V7.PERF.writersDue(cfg)
    local x = cfg.exhaust
    if x and x.enabled then
        if x.stamp ~= ROSTER.exhaustStamp() then return true end
        local all, season, live = df.global.world.populations.all, df.global.cur_season, {}
        for _, r in ipairs(CACHE.managedPops()) do
            if not x.done[r.key] and cfg.stock[r.key] ~= 0 and ROSTER.wants(cfg, r.key, season) then
                local pop = all[r.i]
                if pop and pop.race == r.race then live[r.key] = (live[r.key] or 0) + math.max(0, pop.quantity) end
            end
        end
        for _, q in pairs(live) do if q == 0 then return true end end
    end
    local S = cfg.water and cfg.water.spill
    -- v7.1-perf2: no copy for a spill that would wait on the load-time scans (V7.WB.ready in spillCheck)
    if S and S.enabled and cfg.layers.water and cfg.water.enabled and (V7.WB.isReady() or not CACHE.censusOpen) then
        local now = absTick()
        if not (CACHE.watSpillAt and now >= CACHE.watSpillAt and now - CACHE.watSpillAt < TICKS_PER_DAY) then return true end
    end
    return false
end
-- P4: one unit census per job pass. Built on first use inside a FUSE.job pass and dropped when the pass ends (unit
-- refs never outlive the pass: a unit freed between ticks would be a dangling userdata); a tool placement in the pass
-- bumps CACHE.censusGen and the next caller rebuilds. Outside a pass (verbs, window, overlay) every call builds afresh.
-- Holds: by (wild counts per layer, WILD.countByLayer's figures), wild (WILD.onMap units) with layer[i], gated (units
-- gatedLayer accepts) with gatedLayer[i]. Walks the wild-id set (P11) when it is live, else units.active.
function V7.PERF.emptyCensus() return { by = { land = 0, water = 0, cavern = 0, deep = 0 }, wild = {}, layer = {}, gated = {}, gatedLayer = {} } end
function V7.PERF.census()
    if not dfhack.isMapLoaded() then return V7.PERF.emptyCensus() end
    local now, gen = absTick(), CACHE.censusGen or 0
    local C = CACHE.census
    if C and CACHE.censusOpen and C.tick == now and C.gen == gen then C.hits = C.hits + 1; return C end
    C = V7.PERF.emptyCensus(); C.tick, C.gen, C.hits = now, gen, 0
    local by, wild, layer, gated, gl = C.by, C.wild, C.layer, C.gated, C.gatedLayer
    local function visit(u)
        if WILD.onMap(u) then
            local L = WILD.layerOf(u)
            by[L] = by[L] + 1; wild[#wild+1] = u; layer[#wild] = L
        end
        local g = gatedLayer(u)
        if g then gated[#gated+1] = u; gl[#gated] = g end
    end
    local ids = V7.PERF.wildIds()
    if ids then
        local list = {}
        for id in pairs(ids) do list[#list+1] = id end
        table.sort(list)   -- ids, so the walk order is the same every pass (units.all is id-ordered too)
        for _, id in ipairs(list) do
            local u = df.unit.find(id)
            if not u or dfhack.units.isDead(u) or not dfhack.units.isActive(u) then ids[id] = nil   -- gone: a return re-fires the event
            else visit(u) end
        end
        C.walk = 'wild'
    else
        for _, u in ipairs(df.global.world.units.active) do visit(u) end
        C.walk = 'all'
    end
    if CACHE.censusOpen then CACHE.census = C end
    local S = CACHE.censusStat or { builds = 0, wild = 0, all = 0 }
    CACHE.censusStat = S
    S.builds = S.builds + 1; S[C.walk] = S[C.walk] + 1; S.last = #wild
    return C
end
function V7.PERF.wild()
    if V7.PERF.on('legacy_census') then return df.global.world.units.active end
    return V7.PERF.census().wild
end
function V7.PERF.placed(u)
    CACHE.censusGen = (CACHE.censusGen or 0) + 1
    if CACHE.wildIds and u then CACHE.wildIds[u.id] = true end
end
-- P11: a maintained set of wild unit ids, so the census walks W (the wild units) rather than U (every active unit).
-- Fed three ways: (1) one scan of units.active at the first census after a load, and again every perf.rescan_ticks
-- (self-healing); (2) eventful's onUnitNewActive (EventManager's native diff of units.active; units present at load
-- fire nothing, hence the seed) for arrivals and returns; (3) creations since the last look, read off the tail of
-- units.all (id-ordered) down to the last unit_next_id, so a wave that arrived after the event's last check is never
-- late. The tool's own placements add themselves (V7.PERF.placed). The census prunes dead and departed ids. One
-- handler, keyed by the tool's name, touching only the shared CACHE. Feature-detected; perf events off = U walks.
function V7.PERF.eventsOn()
    if not V7.PERF.on('events') then return false end
    if CACHE.evReg ~= nil then return CACHE.evReg end
    local ok, ev = pcall(require, 'plugins.eventful')
    if not (ok and type(ev) == 'table' and ev.onUnitNewActive and ev.enableEvent and ev.eventType) then CACHE.evReg = false; return false end
    local C = CACHE
    ev.onUnitNewActive[MODULE] = function(id)
        local set = C.wildIds
        if not set then return end
        local u = df.unit.find(id)
        if u and dfhack.units.isWildlife(u) then set[id] = true; C.evArrivals = (C.evArrivals or 0) + 1 end
    end
    local okE = pcall(ev.enableEvent, ev.eventType.UNIT_NEW_ACTIVE, V7.PERF.on('events_freq'))
    CACHE.evReg = okE and true or false
    return CACHE.evReg
end
function V7.PERF.eventsOff()
    local ok, ev = pcall(require, 'plugins.eventful')
    if ok and type(ev) == 'table' and ev.onUnitNewActive then ev.onUnitNewActive[MODULE] = nil end
    CACHE.evReg, CACHE.wildIds, CACHE.wildSeedAt = nil, nil, nil
end
function V7.PERF.wildIds()
    if V7.PERF.on('legacy_census') or not V7.PERF.eventsOn() then return nil end
    local now, set = absTick(), CACHE.wildIds
    local okN, nxt = pcall(function() return df.global.unit_next_id end)
    if not set or not CACHE.wildSeedAt or now < CACHE.wildSeedAt or now - CACHE.wildSeedAt >= V7.PERF.on('rescan_ticks') or not okN then
        if not okN then return nil end
        set = {}
        for _, u in ipairs(df.global.world.units.active) do if dfhack.units.isWildlife(u) then set[u.id] = true end end
        CACHE.wildIds, CACHE.wildSeedAt, CACHE.wildNext = set, now, nxt
        CACHE.wildSeeds = (CACHE.wildSeeds or 0) + 1
        return set
    end
    if nxt ~= CACHE.wildNext then
        local okT = pcall(function()
            local all, lo = df.global.world.units.all, CACHE.wildNext
            for i = #all - 1, 0, -1 do
                local u = all[i]
                if u.id < lo then break end
                if dfhack.units.isActive(u) and dfhack.units.isWildlife(u) then set[u.id] = true end
            end
        end)
        if not okT then CACHE.wildSeedAt = nil; return nil end   -- reseed next time
        CACHE.wildNext = nxt
    end
    return set
end
function V7.PERF.censusLines()
    local C, S = V7.PERF.census(), CACHE.censusStat or {}
    local n = 0; for _ in pairs(CACHE.wildIds or {}) do n = n + 1 end
    return { ('census: %d wild on the map (land %d, water %d, cavern %d, deep %d), %d gated; walked %s'):format(#C.wild, C.by.land, C.by.water,
                C.by.cavern, C.by.deep, #C.gated, C.walk == 'wild' and ('the wild-id set (' .. n .. ' ids)') or ('units.active (' .. #df.global.world.units.active .. ')')),
             ('builds %d (wild-set %d, full %d); wild-id set: events %s, seeds %d, arrivals by event %d'):format(S.builds or 0, S.wild or 0, S.all or 0,
                CACHE.evReg and 'registered' or (V7.PERF.on('events') and 'unavailable' or 'off'), CACHE.wildSeeds or 0, CACHE.evArrivals or 0) }
end
-- a switch changed by the verb: side effects that cannot wait for the next pass
function V7.PERF.changed(k)
    if k == 'events' or k == 'legacy_census' or k == 'events_freq' then V7.PERF.eventsOff() end
    if k == 'legacy_groups' then CACHE.groups = nil end
    if k == 'legacy_undo' then CACHE.undo = nil end
    if k == 'legacy_pool' then CACHE.poolMemo = nil end
    if k == 'legacy_class' then CACHE.ecoClass, CACHE.raceEco, CACHE.rawFlag = nil, nil, nil end
end
-- P8: buildPool memoized for the JOB callers (exhaustCheck, startCoupling, ecoPredatorSet, PATTERN.openOnly and
-- trickleApply), keyed by the cached config (CACHE.ver; only when the caller holds CACHE.cfg itself), the embark's region
-- set and #populations.all (append-only), dropped with the map. Audit: none of those five writes to a pool entry; the
-- entries' `quantity` is the build-time reading, which none of them reads. Verbs, the window and the web still call
-- buildPool (fresh, theirs to edit): a pool handed to code that may edit it is never the shared one. legacy_pool = fresh.
function V7.PERF.pool(cfg)
    if V7.PERF.on('legacy_pool') or cfg ~= CACHE.cfg or not dfhack.isMapLoaded() then return buildPool(cfg) end
    local rs, n = getEmbarkRegions(), #df.global.world.populations.all
    local m = CACHE.poolMemo
    if m and m.ver == CACHE.ver and m.rs == rs and m.n == n then m.hits = m.hits + 1; return m.pool, m.biomeSet, m.regionSet end
    local pool, biomeSet, regionSet = buildPool(cfg)
    CACHE.poolMemo = { ver = CACHE.ver, rs = rs, n = n, pool = pool, biomeSet = biomeSet, regionSet = regionSet, hits = 0, builds = ((m and m.builds) or 0) + 1 }
    return pool, biomeSet, regionSet
end
function V7.PERF.cacheLine()
    local function cnt(t) local k = 0; for _ in pairs(t or {}) do k = k + 1 end; return k end
    local m = CACHE.poolMemo
    return ('pool %s, eco classes %d, races %d, groups %s, undo %s'):format(m and ('memo ' .. m.hits .. ' hits') or 'cold', cnt(CACHE.ecoClass),
        cnt(CACHE.raceTok), CACHE.groups and 'held' or '-', CACHE.undo and (#CACHE.undo.ring .. ' held') or '-')
end
-- P9 (R55; DwarfCron data/dfhack-r2/REPORT.md section 3.1): dfhack.maps.forEachTile (DFHack 53.16-r2, experimental) for
-- the surveys, feature-detected and pcall'd with the Lua loop as the fallback (players on r1.1 run this file too). Used
-- count-only, never with a per-tile Lua callback: a callback pushes a block userdata per matched tile, which on a sea
-- fort (most band tiles wet) costs more than the sampled Lua loop it would replace. So: vegSurvey's floor and grass are
-- two native counts per level; PLACE.tiles and ENGINE.waterTiles skip a level the native count proves empty. CAVE and
-- WET read only the map-edge tiles of each edge block in Lua (V7.PERF.edgeCells), on any build.
function V7.PERF.fet()
    if V7.PERF.on('legacy_survey') or not V7.PERF.on('forEachTile') then return nil end
    local f = dfhack.maps.forEachTile
    if type(f) ~= 'function' or CACHE.fetBroken then return nil end
    return f
end
function V7.PERF.enums()
    if V7.PERF.ENUM then return V7.PERF.ENUM end
    local E = { walk = {}, nontree = {}, grass = {} }
    for i = df.tiletype_shape._first_item, df.tiletype_shape._last_item do
        local a = i >= 0 and df.tiletype_shape.attrs[i]
        if a and a.walkable then E.walk[#E.walk+1] = i end
    end
    for i = df.tiletype_material._first_item, df.tiletype_material._last_item do
        if i >= 0 and i ~= df.tiletype_material.TREE then E.nontree[#E.nontree+1] = i end
    end
    for _, n in ipairs{ 'GRASS_LIGHT', 'GRASS_DARK', 'GRASS_DRY', 'GRASS_DEAD' } do E.grass[#E.grass+1] = df.tiletype_material[n] end
    V7.PERF.ENUM = E
    return E
end
-- a native call that raises once is not tried again this session (CACHE.fetBroken) and the caller falls back
function V7.PERF.count(f, box, spec)
    local ok, r = pcall(f, box, spec)
    if ok and type(r) == 'table' and type(r.matched) == 'number' then return r.matched end
    CACHE.fetBroken = tostring(r)
    return nil
end
-- true when level z certainly holds no tile the caller's scan could accept; nil when unknown (then scan as before).
-- wantWater: flow 4..7, not magma; else walkable non-tree floor. underground: subterranean and not outside; else outside
-- (the water survey, anyBand, accepts any tile: a continuing run need not be outside).
function V7.PERF.levelEmpty(z, wantWater, underground, W, H, anyBand)
    local f = V7.PERF.fet()
    if not f then return nil end
    local E = V7.PERF.enums()
    local box = { 1, 1, z, W - 2, H - 2, z }
    if anyBand then box = { 0, 0, z, W - 1, H - 1, z } end
    local des = {}
    if not anyBand then
        if underground then des.subterranean, des.outside = true, false else des.outside = true end
    end
    if wantWater then
        des.liquid_type = false
        for k = 4, 7 do
            des.flow_size = k
            local spec = { designation = des }
            if not anyBand then spec.occupancy = { unit = false }; spec.material = E.nontree end
            local n = V7.PERF.count(f, box, spec)
            if n == nil then return nil end
            if n > 0 then return false end
        end
        return true
    end
    local n = V7.PERF.count(f, box, { designation = des, occupancy = { unit = false }, shape = E.walk, material = E.nontree })
    if n == nil then return nil end
    return n == 0
end
function V7.PERF.vegNative(band, deadline)
    local f = V7.PERF.fet()
    if not f then return nil end
    local E = V7.PERF.enums()
    local W, H = df.global.world.map.x_count, df.global.world.map.y_count
    local floor, grass, stopped = 0, 0, false
    for z = band.zhi, band.zlo, -1 do
        local box = { 0, 0, z, W - 1, H - 1, z }
        local a = V7.PERF.count(f, box, { designation = { outside = true }, shape = E.walk, material = E.nontree })
        local b = a and V7.PERF.count(f, box, { designation = { outside = true }, shape = E.walk, material = E.grass })
        if not b then return nil end
        floor, grass = floor + a, grass + b
        if floor >= 4 * ENGINE.TILE_CAP then break end   -- the Lua scan's cap, in every-tile units
        deadline = deadline + V7.PERF.slicePoint()   -- v7.1 (perf, P10): yields between levels only inside a slice
        if FUSE.over(deadline) then stopped = true; break end
    end
    return { floor = floor // 4, grass = grass // 4, stopped = stopped }   -- scaled to the Lua scan's every-2nd-x-and-y units
end
-- CAVE and WET: a block's map-edge cells as a flat list {lx1, ly1, lx2, ly2, ...}, exactly the tiles the v7.0 loop kept
-- (x == 0, x == W-1, y == 0 or y == H-1, inside the map), memoized per block position for the survey
function V7.PERF.edgeCells(memo, bx, by, W, H)
    local k = bx * 4096 + by
    local c = memo[k]
    if c then return c end
    c = {}
    for lx = 0, 15 do
        local x = bx * 16 + lx
        if x < W then
            for ly = 0, 15 do
                local y = by * 16 + ly
                if y < H and (x == 0 or x == W - 1 or y == 0 or y == H - 1) then c[#c+1] = lx; c[#c+1] = ly end
            end
        end
    end
    memo[k] = c
    return c
end
-- P10 (R55): coroutine slicing. V7.PERF.slice runs fn as a coroutine, resumed once a tick for at most perf.slice_ms;
-- fn yields only at V7.PERF.slicePoint() calls, placed between the levels of the load-time surveys (CAVE, WET, the
-- water band, vegetation) and between ROSTER.build's steps. Across a yield only Lua tables, ids and raws (which live as
-- long as the world) are held: never a unit, block or population userdata. Each survey's own FUSE deadline is pushed
-- back by the time spent suspended, so a sliced survey gets the same CPU budget. World unload kills every slice
-- (V7.PERF.drop); tick timeouts die with the world too. A synchronous caller that needs a survey a slice has not
-- finished runs the slice to its end on the spot (finishSlice). Caps: SLICE_MAX resumes, FUSE.TRIP_MS of CPU, then the
-- rest runs at once. perf slice off = everything synchronous, as before.
V7.PERF.SLICE_MAX = 600
function V7.PERF.slicePoint()
    local sl = CACHE.sliceNow
    if not sl or sl.finish or nowMs() < sl.until_ms or not coroutine.isyieldable() then return 0 end
    local t = nowMs()
    coroutine.yield()
    -- a slice that edits a config copy (perf build) must not save over a config another writer saved meanwhile
    if sl.ver0 and CACHE.ver ~= sl.ver0 then error('the configuration was saved while this slice waited', 0) end
    return nowMs() - t
end
function V7.PERF.resume(sl)
    CACHE.sliceNow = sl
    sl.until_ms = nowMs() + (sl.ms or V7.PERF.on('slice_ms'))
    local t = nowMs()
    local ok, err = coroutine.resume(sl.co)
    CACHE.sliceNow = nil
    sl.cpu, sl.n = sl.cpu + (nowMs() - t), sl.n + 1
    if not ok then sl.dead, sl.err = true, tostring(err) end
    if coroutine.status(sl.co) == 'dead' then sl.dead = true end
    return sl.dead
end
function V7.PERF.sliceEnd(name, sl)
    if sl.ended then return end   -- finished on the spot, then its pending timeout fired: once only
    sl.ended = true
    if CACHE.slices and CACHE.slices[name] == sl then CACHE.slices[name] = nil end
    CACHE.sliceLog = CACHE.sliceLog or {}
    CACHE.sliceLog[name] = { n = sl.n, cpu = sl.cpu, wall = nowMs() - sl.t0, err = sl.err, aborted = sl.aborted }
    if sl.err then dfhack.printerr(('seasonal-wildlife: slice %s failed: %s'):format(name, sl.err)) end
    if sl.done and not sl.aborted then pcall(sl.done, sl.err == nil, sl.err) end
end
-- opts (v7.1-place, the water body registry): { ms = CPU per resume, max = resumes, cpu = total CPU } in place of
-- slice_ms, SLICE_MAX and FUSE.TRIP_MS
function V7.PERF.slice(name, fn, done, guardVer, opts)
    if not V7.PERF.on('slice') or not dfhack.isMapLoaded() then
        local ok, err = pcall(fn)
        if done then pcall(done, ok, not ok and tostring(err) or nil) end
        return true
    end
    CACHE.slices = CACHE.slices or {}
    local cur = CACHE.slices[name]
    if cur and not cur.dead then return false, 'already running' end
    local sl = { co = coroutine.create(fn), n = 0, cpu = 0, t0 = nowMs(), done = done, ver0 = guardVer and CACHE.ver or nil,
                 ms = opts and opts.ms, max = opts and opts.max, cpuMax = opts and opts.cpu }
    CACHE.slices[name] = sl
    local step
    step = function()
        if sl.dead or not dfhack.isMapLoaded() then sl.aborted = not sl.finished; return V7.PERF.sliceEnd(name, sl) end
        if sl.n >= (sl.max or V7.PERF.SLICE_MAX) or sl.cpu >= (sl.cpuMax or FUSE.TRIP_MS) then sl.finish = true end
        if V7.PERF.resume(sl) then sl.finished = true; return V7.PERF.sliceEnd(name, sl) end
        if not dfhack.timeout(1, 'ticks', step) then sl.dead, sl.aborted = true, true; V7.PERF.sliceEnd(name, sl) end
    end
    step()
    return true
end
function V7.PERF.finishSlice(name)
    local sl = CACHE.slices and CACHE.slices[name]
    if not sl or sl.dead or CACHE.sliceNow then return false end   -- inside a slice: never resume another (or itself)
    sl.finish = true
    while not V7.PERF.resume(sl) do end
    sl.finished = true
    V7.PERF.sliceEnd(name, sl)
    return true
end
-- v7.1-forcefix (validate-full 20261002-220014, --only w0 on RinghatchetsReady: the Live tab's first refresh after the
-- load took 234 ms, budget 100; full runs 0). The warm slice resumes once a TICK, so with the game paused since the load
-- it never advanced, and the first synchronous reader -- the Live tab's V7.GRP.layerRows (ENGINE.waterTiles, CAVE.get)
-- -- ran the whole of it on the spot (finishSlice). Now, while the game is paused, it also resumes once a rendered
-- frame (same slice_ms budget and caps), so it finishes within a few frames of the load paused or not; and a window
-- reads the surveys without waiting (layerRows/CAVE.status nowait) while warming() is true.
function V7.PERF.warming(name)
    local sl = CACHE.slices and CACHE.slices[name or 'warm']
    return (sl and not sl.dead and not sl.ended) and true or false
end
-- v7.1-perf2: a scheduled pass that meets a load-time slice still running waits for it (the slice is resumed every tick
-- and, paused, every frame) instead of finishing it on the spot. Fail-fast fallback: after WAIT_PASSES such waits on one
-- slice (counted once per game tick) the next pass stops waiting and its readers finish the slice as before. True = wait.
V7.PERF.WAIT_PASSES = 20
function V7.PERF.passWaits(name)
    local sl = CACHE.slices and CACHE.slices[name]
    if not (sl and not sl.dead and not sl.ended) then return false end
    local now = dfhack.isMapLoaded() and absTick() or 0
    if sl.waitAt ~= now then sl.waitAt = now; sl.waits = (sl.waits or 0) + 1 end   -- once per pass (game tick), not per reader
    return sl.waits <= V7.PERF.WAIT_PASSES
end
-- the load-time surveys, sliced: started by enableSched before the jobs (the groups job's first pass waits PHASE.groups)
-- v7.1-rc (forcefix) + v7.1-place: a sliced job advances on game ticks (V7.PERF.slice); while the game is paused this
-- frame driver advances it instead, with the same per-slice budget and caps, so a paused fort finishes its load-time
-- survey and its water-body scan. One driver per running slice; it stops when the slice ends or is replaced.
function V7.PERF.drivePaused(name)
    local mine = CACHE.slices and CACHE.slices[name]
    if not mine or mine.dead or mine.ended or mine.pausedDriver then return end
    mine.pausedDriver = true
    local fstep
    fstep = function()
        local sl = CACHE.slices and CACHE.slices[name]
        if sl ~= mine or sl.dead or sl.ended or not dfhack.isMapLoaded() then return end
        local okP, paused = pcall(dfhack.world.ReadPauseState)
        if okP and paused and not CACHE.sliceNow then
            if sl.n >= (sl.max or V7.PERF.SLICE_MAX) or sl.cpu >= (sl.cpuMax or FUSE.TRIP_MS) then sl.finish = true end
            if V7.PERF.resume(sl) then sl.finished = true; V7.PERF.sliceEnd(name, sl); return end
        end
        dfhack.timeout(1, 'frames', fstep)
    end
    dfhack.timeout(1, 'frames', fstep)
end
function V7.PERF.warm()
    if not (V7.PERF.on('slice') and dfhack.isMapLoaded()) then return end
    V7.PERF.slice('warm', function()
        if not CACHE.cave then CAVE.get() end
        if not CACHE.wet then WET.get() end
        if not CACHE.wtiles then ENGINE.waterTiles() end
        if not CACHE.veg then V7.vegSurvey() end
    end)
    if not CACHE.wb then V7.WB.start(CACHE.cfg or loadConfig(), 'load') end   -- v7.1-place: the water body registry, sliced
    V7.PERF.drivePaused('warm'); V7.PERF.drivePaused('wbscan')
end
-- P12 (scavenging): SCAV.edible's cheap flag tests run every pass; the rest -- the historical figure, the owner of
-- the body (a citizen's, the fort's, a tame animal's) and the building at the item's tile -- is kept per item id and
-- the building test redone only when the item moved. Entries not seen for SCAV_KEEP passes are dropped; the memo
-- goes with the map. legacy_scav = the v7.0 test every time.
V7.PERF.SCAV_KEEP = 20
function V7.PERF.edibleRest(it, h)
    if h[it.race] then return false end
    local M = CACHE.scavMemo
    if not M then M = { pass = 0, items = {} }; CACHE.scavMemo = M end
    local x, y, z = dfhack.items.getPosition(it)
    local m = M.items[it.id]
    if not m then
        m = {}
        local ok, hf = pcall(function() return it.hist_figure_id end)
        m.fig = ok and hf and hf >= 0 or false
        local okU, uid = pcall(function() return it.unit_id end)
        local u = okU and uid and uid >= 0 and df.unit.find(uid) or nil
        m.owned = (u and (dfhack.units.isCitizen(u) or dfhack.units.isOwnCiv(u) or u.flags1.tame or dfhack.units.isFortControlled(u))) and true or false
        M.items[it.id] = m
    end
    m.seen = M.pass
    if m.fig or m.owned then return false end
    if not x then return false end
    if m.x ~= x or m.y ~= y or m.z ~= z then
        m.x, m.y, m.z = x, y, z
        m.bld = dfhack.buildings.findAtTile({ x = x, y = y, z = z }) and true or false   -- (xyz2pos's table)
    end
    if m.bld then return false end
    return true, x, y, z
end
function V7.PERF.scavPass()   -- called once per scavenging pass: ages the memo
    local M = CACHE.scavMemo
    if not M then return end
    M.pass = M.pass + 1
    if M.pass % V7.PERF.SCAV_KEEP == 0 then
        for id, m in pairs(M.items) do   -- the stale go; the rest re-test their tile (a building may have gone up on it)
            if M.pass - (m.seen or 0) > V7.PERF.SCAV_KEEP then M.items[id] = nil else m.x = nil end
        end
    end
end
-- P12 (web, engine side): what the web companion's snapshot can call instead of its own unit walk and per-species raw
-- reads. webCensus(g): one walk of the census's wild units (the wild-id set when live) giving the wild counts per
-- layer, the on-map count per key, and the untracked animals by key and origin, exactly as the snapshot builds them.
-- webStatic(idx): a species' name, ASCII glyph and diet flags, cached per world and config version (V7.apply may write
-- GRAZER; every apply follows a save). The web stream wires these in; nothing here changes the snapshot by itself.
function V7.PERF.webCensus(g)
    g = g or loadGroups()
    local tracked = {}
    for _, grp in ipairs(g.groups) do for _, id in ipairs(grp.ids) do tracked[id] = grp end end
    local C = V7.PERF.census()
    local out = { wild = { land = C.by.land, water = C.by.water, cavern = C.by.cavern, deep = C.by.deep }, onMap = {}, untracked = {}, n = #C.wild }
    for i, u in ipairs(C.wild) do
        local l = C.layer[i]
        local key = keyFor(l, V7.PERF.raceTok(u.race))
        out.onMap[key] = (out.onMap[key] or 0) + 1
        if not tracked[u.id] and l ~= 'deep' then
            local o = WILD.origin(u, tracked)
            local k = key .. '|' .. o
            local r = out.untracked[k]
            if not r then r = { key = key, n = 0, origin = o }; out.untracked[k] = r end
            r.n = r.n + 1
        end
    end
    return out
end
function V7.PERF.webStatic(idx)
    local W = CACHE.webStatic
    if not W or W.ver ~= CACHE.ver then W = { ver = CACHE.ver, map = {} }; CACHE.webStatic = W end
    local r = W.map[idx]
    if r then return r end
    local cr = df.creature_raw.find(idx)
    r = { name = cr and cr.name[0] or '?' }
    if cr then
        pcall(function() r.ascii = { ch = cr.creature_tile, fg = cr.color[0], bg = cr.color[1], br = cr.color[2] } end)
        r.diet = { carnivore = hasCasteFlag(cr, 'CARNIVORE') and true or false, bonecarn = hasCasteFlag(cr, 'BONECARN') and true or false,
                   grazer = hasCasteFlag(cr, 'GRAZER') and true or false }
    end
    W.map[idx] = r
    return r
end
function V7.PERF.raceTok(race)
    local m = CACHE.raceTok
    if not m then m = {}; CACHE.raceTok = m end
    local t = m[race]
    if t == nil then
        local cr = df.creature_raw.find(race)
        t = cr and cr.creature_id or '?'
        m[race] = t
    end
    return t
end
-- caste flags the tool never writes (FLIER, IMMOBILE), per race per world; any other flag is read live (hasCasteFlag),
-- because HUNT, CURIOUS, V7.apply and IRRUPT write caste flags and a memo would go stale
V7.PERF.STATIC_FLAGS = { FLIER = true, IMMOBILE = true }
function V7.PERF.rawFlag(race, flag)
    local cr = (V7.PERF.STATIC_FLAGS[flag] and not V7.PERF.on('legacy_class')) and nil or df.creature_raw.find(race)
    if cr then return hasCasteFlag(cr, flag) end
    local m = CACHE.rawFlag
    if not m then m = {}; CACHE.rawFlag = m end
    local k = race * 64 + (flag == 'FLIER' and 1 or 2)
    local v = m[k]
    if v == nil then
        local c = df.creature_raw.find(race)
        v = c and hasCasteFlag(c, flag) or false
        m[k] = v
    end
    return v
end
function V7.PERF.raceEco(cfg, race)
    local memo = (cfg == nil or cfg == CACHE.cfg) and not V7.PERF.on('legacy_class')
    local m = CACHE.raceEco
    if memo then
        if not m or m.ver ~= CACHE.ver then m = { ver = CACHE.ver, map = {} }; CACHE.raceEco = m end
        local c = m.map[race]
        if c ~= nil then return c or nil end
    end
    local cr = df.creature_raw.find(race)
    local cls = cr and (ecoOf(cfg, cr)) or nil
    if memo then m.map[race] = cls or false end
    return cls
end
-- PERF0's probe as a verb: each target N times in one call, ms per call (over N, to beat the clock step) and KB per call
-- (the collector stopped for the call: the shared heap grows by what the target allocates). No game time passes. The
-- writers it times rewrite the same records (saveGroups of the held record). Run once with the new paths and once with
-- `perf legacy NAME on` for the v7.0 figure, in one fresh DF process.
function V7.PERF.bench(N)
    if not dfhack.isMapLoaded() then print('perf bench: no map loaded') return end
    N = math.max(1, math.min(200, math.floor(N or 10)))
    local cfg = V7.PERF.cfgRO()
    local rows = {
        { 'loadConfig (deep copy)', function() return loadConfig() end },
        { 'cfgRO (shared)', function() return V7.PERF.cfgRO() end },
        { 'loadGroups', function() return loadGroups() end },
        { 'saveGroups (rewrite)', function() saveGroups(loadGroups()) end },
        { 'UNDO.depth', function() return UNDO.depth() end },
        { 'census (outside a pass)', function() return V7.PERF.census() end },
        { 'countByLayer', function() return WILD.countByLayer() end },
        { 'raceEco x active units', function() for _, u in ipairs(df.global.world.units.active) do V7.PERF.raceEco(cfg, u.race) end end },
        { 'buildPool (fresh)', function() return buildPool(cfg) end },
        { 'V7.PERF.pool (memo)', function() return V7.PERF.pool(cfg) end },
        { 'ENGINE.candidates', function() return ENGINE.candidates(cfg) end },
        { 'ecoLivePairs', function() return ecoLivePairs() end },
        { 'overlay data (fresh)', function() CACHE.ovl = nil; return V7.PERF.overlayData() end },
    }
    print(('perf bench: %d call(s) each; legacy paths on: %s'):format(N, (V7.PERF.statusLine():match('legacy paths: ([^;]+)')) or '?'))
    print(('  %-26s %10s %10s'):format('target', 'ms/call', 'KB/call'))
    for _, r in ipairs(rows) do
        collectgarbage('stop')
        local kb0, t0 = collectgarbage('count'), nowMs()
        local ok, err = true, nil
        for _ = 1, N do ok, err = pcall(r[2]); if not ok then break end end
        local ms, kb = nowMs() - t0, collectgarbage('count') - kb0
        collectgarbage('restart')
        if ok then print(('  %-26s %10.2f %10.1f'):format(r[1], ms / N, kb / N))
        else print(('  %-26s failed: %s'):format(r[1], tostring(err))) end
    end
end
function V7.PERF.verb(args, dispatchFn)
    local sub = args[2]
    if sub == 'build' then   -- P10: `roster build LAYER`, sliced over ticks; reruns at once if the config changed meanwhile
        if not (dispatchFn and dfhack.isMapLoaded()) then print('perf build: no map loaded') return end
        local layer = args[3] or 'land'
        local ok, why = V7.PERF.slice('build', function() dispatchFn({ 'roster', 'build', layer }) end, function(okB, err)
            if not okB then
                print(('perf build: %s; building at once'):format(tostring(err)))
                dispatchFn({ 'roster', 'build', layer })
            end
        end, true)
        if not ok then print('perf build: ' .. tostring(why)) else print('perf build: started (sliced, prints when done)') end
        return
    end
    if sub == 'reset' then V7.PERF.reset(); print('perf: job stats, tick worst and DFHack perf counters reset') return end
    if sub == 'set' or sub == 'legacy' then
        local k, v = args[3], args[4]
        if sub == 'legacy' and k then k = 'legacy_' .. k end
        local d = k and V7.PERF.DEF[k]
        if d == nil then print('usage: seasonal-wildlife perf set KEY VALUE | perf legacy NAME on|off   (keys: `perf keys`)') return end
        local c = loadConfig()
        if type(d) == 'boolean' and (v == 'on' or v == 'off') then c.perf[k] = (v == 'on')
        elseif type(d) == 'number' and tonumber(v) then
            local lim = V7.PERF.NUM[k] or { 0, 1e9 }
            c.perf[k] = math.max(lim[1], math.min(lim[2], math.floor(tonumber(v))))
        else print(('usage: seasonal-wildlife perf set %s %s'):format(k, type(d) == 'boolean' and 'on|off' or 'N')) return end
        saveConfig(c); LEDGER.add('edit', '', 'perf %s %s', k, tostring(c.perf[k]))
        if V7.PERF.changed then pcall(V7.PERF.changed, k) end
        print(('perf %s = %s'):format(k, tostring(c.perf[k]))) return
    end
    if sub == 'keys' then
        local c, ks = loadConfig(), {}
        for k in pairs(V7.PERF.DEF) do ks[#ks+1] = k end
        table.sort(ks)
        for _, k in ipairs(ks) do print(('  %-18s %-6s (default %s)'):format(k, tostring(c.perf[k]), tostring(V7.PERF.DEF[k]))) end
        return
    end
    if sub == 'bench' then if V7.PERF.bench then V7.PERF.bench(tonumber(args[3]) or 10) end return end
    if sub == 'census' then if V7.PERF.censusLines then for _, l in ipairs(V7.PERF.censusLines()) do print(l) end end return end
    if sub and sub ~= 'status' then
        print('usage: seasonal-wildlife perf [status|reset|keys|set KEY VALUE|legacy NAME on|off|bench [N]|census|build [LAYER]]') return
    end
    print(V7.PERF.statusLine())
    for _, l in ipairs(V7.PERF.lines()) do print(l) end
end

-- v6.3.0: every in-memory copy is dropped with the map or the world it came from
function CACHE.drop(world)
    if CACHE.irr and CACHE.irr.casteHeld then pcall(IRRUPT.casteUndo, CACHE.irr.casteHeld) end   -- v7.1 (irruption)
    CACHE.irr = nil   -- v7.1 (irruption): the per-map memo (civ races, active caverns, scarcity)
    CACHE.cfg = nil; CACHE.ledger = nil; CACHE.ledgerDirty = false; CACHE.cave = nil; CACHE.wet = nil
    CACHE.align = nil   -- v7.0.0
    CACHE.scav7, CACHE.curious7, CACHE.scavLast, CACHE.curiousLast, CACHE.scavKind = nil, nil, nil, nil, nil   -- v7.1 (scav)
    CACHE.veg = nil; CACHE.deepCols = nil   -- v7.0.0 (roster builder): vegetation and column-depth surveys
    CACHE.watCensus, CACHE.watLandAq = nil, nil   -- v7.1 (water)
    CACHE.wb, CACHE.wbErr, CACHE.wbStarted = nil, nil, nil   -- v7.1-place: the water body registry is this map's
    CACHE.watLayerWhy = nil   -- v7.1 (Alpha Four 2.12): why the auto layer turned on is this map's, not the last one's
    CACHE.vforage = nil; CACHE.gobbleNative = nil   -- v7.1 (R21): forage state and the native-gobbler memo go with the map
    if world then CACHE.realmOverride = nil end   -- v7.1 (fixes2): the user's realms json is read again for the next world
    CACHE.ecoDone = {}; CACHE.predset = nil; CACHE.pops = nil; CACHE.reserve = nil; CACHE.wtiles = nil; CACHE.call = nil; CACHE.cavsnap = nil
    CACHE.waterLater, CACHE.passJob = nil, nil   -- v7.1-rc (V7.PASS): a pending water pass dies with the map's timers
    V7.PERF.drop(world)   -- v7.1 (perf stream): groups, undo, census, pool, overlay, raceEco; per world: class and race memos
    if world then CACHE.class, CACHE.climate, CACHE.rawBiomes, CACHE.animalRoot = {}, {}, {}, nil; CACHE.rawByToken = nil; CACHE.spongeRace = nil; CACHE.raceIdx = {}; CACHE.cliIds = nil
        CACHE.depth = {} end   -- v7.1 (fixes): cave depths and race indices are per world, in every copy
end
dfhack.onStateChange[MODULE] = function(code)
    if code == SC_MAP_LOADED or code == SC_WORLD_UNLOADED then CACHE.drop(code == SC_WORLD_UNLOADED) end
    if code == SC_WORLD_UNLOADED then CACHE.region = nil; CACHE.humanoid = nil; repeatUtil.cancel(ALERTS.JOB); CURIOUS.restore(); V7.restore(); PATTERN.trickleRestore(); PATTERN.sizeRestore(); HUNT.restore(); repeatUtil.cancel(MODULE); repeatUtil.cancel(GROUPS_JOB); repeatUtil.cancel(ECOLOGY_JOB); repeatUtil.cancel(WATER.JOB); repeatUtil.cancel(STOCK.JOB); lastSeason = nil
        repeatUtil.cancel(SCAV.JOB); repeatUtil.cancel(CURIOUS.JOB)   -- v7.1 (scav)
    elseif code == SC_MAP_LOADED then local cfg = loadConfig(); if cfg.enabled then enableSched() end end
    if code == SC_WORLD_UNLOADED then repeatUtil.cancel(VERMIN.FORAGE.JOB) end   -- v7.1 (R21)
    -- v7.1-rc (item 1): the syndrome lever's syndromes are re-made and its units re-pointed at every map load, enabled or not
    if code == SC_WORLD_UNLOADED then IRRUPT.MASK.syn = {}
    elseif code == SC_MAP_LOADED then
        local ok, err = pcall(IRRUPT.MASK.onLoad)
        if not ok then dfhack.printerr('seasonal-wildlife: irruption masks after the load: ' .. tostring(err)) end
    end
end

local function seasonLabel(cfg, token)
    local arr = cfg.assign[token] or {}
    if #arr == 0 then return '-' end
    if #arr == 4 then return 'All' end
    local o = {}; for _, s in ipairs(arr) do o[#o+1] = SEASON_SH[s] end
    return table.concat(o)
end

-- (v5.9.8) the window lives in gui/seasonal-wildlife.lua; the engine only knows how to open it.
function show_gui() return reqscript('gui/seasonal-wildlife').show_gui() end

--========================================================================================
-- map overlay: where the groups are
--========================================================================================
-- Registered with the overlay framework (`overlay enable seasonal-wildlife.groups`).
-- Paints a marker beside each tracked group's first member that is on screen, so the
-- ecology shows where it happens rather than only in a window.
-- luacheck: globals GroupsOverlay OVERLAY_WIDGETS xyz2pos
local overlay = require('plugins.overlay')
local guidm = require('gui.dwarfmode')
GroupsOverlay = defclass(GroupsOverlay, overlay.OverlayWidget)
GroupsOverlay.ATTRS{
    desc='Marks each tracked wildlife group on the map and draws the live predator-prey links (v6.2.0).',
    default_pos={ x=1, y=1 }, viewscreens='dwarfmode/Default', default_enabled=false,
    fullscreen=true, frame={ w=1, h=1 },
}
-- the v7.0 overlay, kept behind perf legacy_overlay: a groups decode and an O(M^2) relation scan on every frame
function V7.PERF.overlayLegacy()
    local _, g = groupsStatus()
    if #g.groups == 0 then return end
    local vp = guidm.Viewport.get()
    for _, grp in ipairs(g.groups) do
        for _, id in ipairs(grp.ids) do
            local u = df.unit.find(id)
            if u and not dfhack.units.isDead(u) then
                local pos = xyz2pos(dfhack.units.getPosition(u))
                if pos.z == vp.z and vp:isVisible(pos) then   -- v6.5.0 (W10, alpha 1 step 6.2): only on the level being viewed
                    local sp = vp:tileToScreen(pos)
                    local pen = grp.resident and COLOR_LIGHTGREEN or COLOR_YELLOW
                    dfhack.screen.paintString({ fg=pen, bg=COLOR_BLACK }, sp.x + 1, sp.y, (grp.resident and 'r' or 'g') .. #grp.ids)
                    break
                end
            end
        end
    end
    -- v6.2.0: the live predator-prey links -- a dotted line between every related pair on this z-level
    -- and on screen, the same cells the ecology job writes (ecoLivePairUnits). Capped so a crowded map
    -- costs one frame, not many.
    for _, p in ipairs(ecoLivePairUnits(60)) do
        if p.apos.z == p.bpos.z and p.apos.z == vp.z then
            local a, b = xyz2pos(p.apos.x, p.apos.y, p.apos.z), xyz2pos(p.bpos.x, p.bpos.y, p.bpos.z)
            if vp:isVisible(a) or vp:isVisible(b) then
                local sa, sb = vp:tileToScreen(a), vp:tileToScreen(b)
                local dx, dy = math.abs(sb.x - sa.x), math.abs(sb.y - sa.y)
                local steps = math.max(dx, dy)
                if steps > 1 and steps < 200 then
                    for i = 1, steps - 1 do
                        local x = sa.x + math.floor((sb.x - sa.x) * i / steps + 0.5)
                        local y = sa.y + math.floor((sb.y - sa.y) * i / steps + 0.5)
                        dfhack.screen.paintString({ fg=COLOR_LIGHTRED, bg=COLOR_BLACK }, x, y, '.')
                    end
                end
            end
        end
    end
end
-- v7.1 (perf, P3): the overlay paints from CACHE.ovl, refreshed at most once per perf.overlay_ms (1,000): the groups
-- (the shared CACHE.groups, P2: no decode) with each member's position, and the live predator-prey pairs. A frame reads
-- no DF unit and builds no table. Markers and links may be up to one refresh old. Dropped with the map (V7.PERF.drop).
function V7.PERF.overlayData()
    local now, o = nowMs(), CACHE.ovl
    if o and now >= o.at and now - o.at < V7.PERF.on('overlay_ms') then return o end
    o = { at = now, groups = {}, links = {} }
    local g = loadGroups()
    for _, grp in ipairs(g.groups) do
        local G = { pen = grp.resident and COLOR_LIGHTGREEN or COLOR_YELLOW, text = (grp.resident and 'r' or 'g') .. #grp.ids, pos = {} }
        for _, id in ipairs(grp.ids) do
            local u = df.unit.find(id)
            if u and not dfhack.units.isDead(u) then
                local x, y, z = dfhack.units.getPosition(u)
                if x then G.pos[#G.pos+1] = { x = x, y = y, z = z } end
            end
        end
        if #G.pos > 0 then o.groups[#o.groups+1] = G end
    end
    for _, p in ipairs(ecoLivePairUnits(60)) do
        if p.apos.z == p.bpos.z then o.links[#o.links+1] = p end
    end
    CACHE.ovl = o
    return o
end
-- v7.1 (user 3 Oct: the links sat several cells off): paint in MAP-TILE space (paintString's map flag), against the
-- main viewport's own size. guidm.Viewport sizes the view by the interface text grid and paints there, which in graphics
-- mode is a different, finer grid than the map's tiles -- every marker and dot landed offset and stretched.
local function mapView()
    local mv = df.global.gps.main_viewport
    local W, H = mv and mv.dim_x or 0, mv and mv.dim_y or 0
    if W <= 0 or H <= 0 then local L = guidm.getPanelLayout().map; W, H = L.width, L.height end
    return df.global.window_x, df.global.window_y, df.global.window_z, W, H
end
function GroupsOverlay:onRenderFrame(dc) -- luacheck: ignore 212
    if not dfhack.isMapLoaded() then return end
    if V7.PERF.on('legacy_overlay') then return V7.PERF.overlayLegacy() end
    local o = V7.PERF.overlayData()
    if #o.groups == 0 and #o.links == 0 then return end
    local wx, wy, wz, W, H = mapView()
    local function inView(x, y) return x >= 0 and y >= 0 and x < W and y < H end
    for _, G in ipairs(o.groups) do
        for _, p in ipairs(G.pos) do
            local sx, sy = p.x - wx, p.y - wy
            if p.z == wz and inView(sx, sy) then
                dfhack.screen.paintString({ fg=G.pen, bg=COLOR_BLACK }, sx + 1, sy, G.text, true)
                break
            end
        end
    end
    local dot = { fg=COLOR_LIGHTRED, bg=COLOR_BLACK }
    for _, p in ipairs(o.links) do
        if p.apos.z == wz then
            local ax, ay, bx, by = p.apos.x - wx, p.apos.y - wy, p.bpos.x - wx, p.bpos.y - wy
            if inView(ax, ay) or inView(bx, by) then
                local steps = math.max(math.abs(bx - ax), math.abs(by - ay))
                if steps > 1 and steps < 200 then
                    for k = 1, steps - 1 do
                        local x = ax + math.floor((bx - ax) * k / steps + 0.5)
                        local y = ay + math.floor((by - ay) * k / steps + 0.5)
                        if inView(x, y) then dfhack.screen.paintString(dot, x, y, '.', true) end
                    end
                end
            end
        end
    end
end
OVERLAY_WIDGETS = { groups=GroupsOverlay }
-- what the overlay would draw, for a test without a screen: the related pairs and how many share a z-level
local function overlayLinks()
    local ps = ecoLivePairUnits()
    local same = 0
    for _, p in ipairs(ps) do if p.apos.z == p.bpos.z then same = same + 1 end end
    return { pairs = #ps, same_z = same }
end

--========================================================================================
-- SPECIES (v5.10.7): one animal, every fact -- the Roster's drill-down
--========================================================================================
-- The design's Species detail view, assembled here so a test can read it without a window:
-- what it is, what it weighs and how it travels, where it is on this embark, its state and
-- the reason (whyFor), its place in the web, what is on the map now, and its ledger history.
local function speciesDetail(cfg, pool, e)
    local season, L, F = df.global.cur_season, {}, {}
    local function add(k, v) L[#L+1] = ('%-11s %s'):format(k, v); F[k] = v end
    add('species', ('%s   %s . %s . %s%s'):format(e.token, e.cat, e.size, tostring(e.eco or '?'), e.locked and '   (left to DF)' or ''))
    -- v6.4.0 (W2): the model's three readings, each with its source and any override
    local wb, ws = {}, {}
    for k in pairs((e.waters or {}).bodies or {}) do wb[#wb+1] = k end
    for k in pairs((e.waters or {}).salt or {}) do ws[#ws+1] = k end
    table.sort(wb); table.sort(ws)
    add('habitat', ('%s%s   water %s%s'):format(e.habitat or '?', (cfg.habitat_override or {})[e.token] and (' (you; the raws say ' .. tostring(e.habitat0) .. ')') or ' (raws)',
        #wb > 0 and table.concat(wb, '/') or 'none', #ws > 0 and (' ' .. table.concat(ws, '/')) or ''))
    add('role', ('%s%s'):format(e.role or '?', (cfg.role_override or {})[e.token] and (' (you; the raws say ' .. tostring(e.role0) .. ')') or (' (' .. tostring(e.roleWhy) .. ')')))
    add('body', ('adult %s cm3, %s   group size %d   clade %s'):format(tostring(e.mass), e.size, e.group or 1, tostring(e.clade)))
    local bl = {}; for b in pairs(e.biomes or {}) do bl[#bl+1] = b end; table.sort(bl)
    add('embark', e.inEmbark and ('%s layer   stocked %d   biomes %s'):format(e.layer, e.quantity or 0, table.concat(bl, ' ')) or 'not on this embark')
    add('allowed', ('%s   why: %s'):format(isAllowed(cfg, e) and 'active' or 'inactive', whyFor(cfg, e)))
    -- v6.5.0 (W5): stock and odds, two controls; the group size; what a call would do
    local live, held = RESERVE.of(e.key)
    local mine = cfg.stock[e.key]
    if mine and not ROSTER.wants(cfg, e.key, df.global.cur_season) then
        -- v6.5.1: a stock set out of season is written when the season comes (applyLive), so say that number, not the old reserve
        add('stock', ('%d in the region, %d come back in season (you set it)'):format(live, mine))
    else
        add('stock', ('%d in the region%s%s'):format(live, held > 0 and (', %d held while out of season'):format(held) or '',
            mine and (' (you set %d)'):format(mine) or ''))
    end
    local w, share, here = ODDS.share(cfg, pool, e)
    add('odds', ('weight %d, %.0f%% of the %s layer%s%s'):format(w, share, e.layer, here and '' or ' (if it were in season)', cfg.odds[e.key] and ' (you set it)' or ' (the raw\'s)'))
    local gs = cfg.group_size[e.key]
    local cr = df.creature_raw.find(e.idx)
    add('group size', gs and gs > 0 and ('%d (you set it)'):format(gs) or (cr and ('%d-%d (the raw\'s)'):format(math.min(cr.cluster_number[1], cr.cluster_number[0]), cr.cluster_number[0]) or '?'))
    add('seasons', ('%s   %s'):format(seasonLabel(cfg, e.key), inSeason(cfg, e.key, season) and 'in season now' or 'out of season now'))
    local function names(list)
        local o = {}
        for _, q in ipairs(list) do o[#o+1] = q.token .. (isAllowed(cfg, q) and '' or '(blocked)') end
        return #o > 0 and table.concat(o, ' ') or '-'
    end
    add('eats', names(matchPrey(cfg, e, pool)))
    add('eaten by', names(matchPredators(cfg, e, pool)))
    local n = 0
    for _, u in ipairs(df.global.world.units.active) do if WILD.onMap(u) and u.race == e.idx then n = n + 1 end end
    local mine = {}
    for _, r in ipairs((groupsStatus())) do if r:find(e.token, 1, true) then mine[#mine+1] = r end end
    add('on the map', ('%d wild now%s'):format(n, #mine > 0 and ('   ' .. table.concat(mine, ' | ')) or ''))
    local ll = LEDGER.lines(300)
    local recent = {}
    for i = #ll, 1, -1 do
        if ll[i]:find(e.token, 1, true) then table.insert(recent, 1, ll[i]); if #recent >= 5 then break end end
    end
    add('history', #recent > 0 and ('%d ledger line(s), newest last'):format(#recent) or 'nothing in the ledger')
    for _, r in ipairs(recent) do L[#L+1] = '            ' .. r end
    return L, F, { on_map = n, groups = mine }
end

