local function classReview(cfg, pool)
    local counts, unclassified = {}, {}
    for _, c in ipairs(ECOLOGY_CLASSES) do counts[c] = 0 end
    for _, e in ipairs(pool) do
        if e.inEmbark or e.eligible then
            counts[e.eco] = (counts[e.eco] or 0) + 1
            if e.eco == 'unclassified' then
                local _, why = ecoOf(cfg, df.creature_raw.find(e.idx))
                unclassified[#unclassified+1] = { token = e.token, why = table.concat(why, ', ') }
            end
        end
    end
    return counts, unclassified
end

local function cmdStatus()
    local cfg = loadConfig()
    local pool, biomeSet = buildPool(cfg)
    local names = {}; for id in pairs(biomeSet) do names[#names+1] = df.biome_type[id] end; table.sort(names)
    print('Biomes: ' .. table.concat(names, ', '))
    local ls = {}; for l in pairs(enabledLayers(cfg)) do ls[#ls+1] = l end; table.sort(ls)
    print('Layers: ' .. table.concat(ls, ', '))
    print(QUOTA.status(cfg))
    if dfhack.isMapLoaded() then for i, l in ipairs(V7.GRP.status(cfg)) do if i > 1 then print(l) end end end   -- v7.1: per-layer groups
    print(PATTERN.status(cfg))
    if dfhack.isMapLoaded() then local ll, lt = LEDGER.lines(1); print(('ledger: %d recorded; last: %s'):format(lt, ll[1] or '-')) end
    if dfhack.isMapLoaded() then print(CAVERN.status(cfg)); print(CAVE.status()); print(ENGINE.status(cfg)); print(HUNT.status(cfg)); print(VERMIN.gobbleStatus(cfg)); print(VERMIN.forageStatus(cfg)); print(FUSE.status()) end
    if dfhack.isMapLoaded() then for _, l in ipairs(V7.H.status(cfg, loadGroups())) do print(l) end end   -- v7.1 (ecology stream)
    print(V7.WAT.layerLine(cfg))   -- v7.1 (fixes): the water layer's default and the season spill
    if dfhack.isMapLoaded() then print(SCAV.status(cfg)); print(CURIOUS.status(cfg)) end   -- v7.1 (scav)
    if dfhack.isMapLoaded() then print(ROSTER.statusLine(cfg)) end   -- v7.1 (roster stream)
    print(V7.EXTINCT.statusLine(cfg))   -- v7.1 (extinct stream)
    print(V7.PERF.statusLine())   -- v7.1 (perf stream)
    print(V7.AQ.statusLine(cfg))  -- v7.1 (aquarium stream)
    if dfhack.isMapLoaded() then print(IRRUPT.status(cfg)) end   -- v7.1 (irruption): `irruption status` has the full readout
    if dfhack.isMapLoaded() then
        local by = WILD.countByLayer()
        print(('On the map now: land %d  water %d  cavern %d  (+%d in the magma sea and underworld, never managed)')
            :format(by.land, by.water, by.cavern, by.deep))
        print(('  DF invasions excluded via unit.%s')
            :format(WILD.field or '?? -- NO INVASION FIELD FOUND, nothing is excluded'))
    end
    print('Embark subset (what can actually come to THIS fort):')
    for _, e in ipairs(pool) do
        if e.inEmbark then
            local codes = {}; for id in pairs(e.biomes) do codes[#codes+1] = abbrevBiome(id) end
            print(('  %-6s %-22s %-9s %-6s M=%-7d G=%-3d [%s] season=%s')
                :format(e.layer, e.token, e.cat, e.size, e.mass, e.group, table.concat(codes, ','), seasonLabel(cfg, e.key)))
        end
    end
end

--========================================================================================
-- engine exports
--========================================================================================
-- Everything above is file-local, which is right for a GUI tool and wrong for a testable
-- one: until this block existed the module exported only `show_gui`, so the only way to
-- reach fillCategory, resetToDefault, toggleSeason or the tallies was for a human to click
-- them. Four of the ten release checks were unverifiable for that reason alone.
--
-- These are the engine, not the GUI. They take an explicit cfg and return values; none of
-- them touch a widget. Reading them from a test costs nothing at runtime -- assignment to
-- the script environment is what `reqscript` hands back, and the GUI path is unchanged.
--
-- ⚠️ Written as `_ENV.name = name`, never `name = name`: the bare form resolves its
-- left-hand side to the in-scope local and is a no-op self-assignment, so the module
-- exports nothing and the failure is silent.
--
--   local sw = reqscript('seasonal-wildlife')
--   local cfg = sw.loadConfig()
--   local pool, biomeSet = sw.buildPool()
--   sw.countsFor(cfg, pool, false)        -- current-roster tallies
--   sw.fillCategory(cfg, pool, 'prey', 4) -- returns the new allowed count
--
-- ⚠️ These mutate live game state and the persisted config exactly as the GUI does. A
-- caller is responsible for the same backup discipline the README demands.

