-- v7.1 (fixes, open item spaced-raw-ids-cli; design R12.9): 36 vanilla raw ids hold a space or a comma ('SEA OTTER',
-- 'HONEY BADGER', 'BADGER, GIANT'), which the console split into two words. Every argument after the verb is resolved
-- once, so every verb that takes a TOKEN or KEY accepts three forms besides the quoted id ("SEA OTTER"):
--   #N          the creature's raw index (`seasonal-wildlife stock '#212' 5`); a layer prefix works: water:#212
--   SEA_OTTER   the id with each run of spaces and commas written as one underscore (BADGER_GIANT)
-- An argument that is itself a raw id, or matches no raw, is left alone; so are lowercase words and numbers.
V7.CLI = {}
function V7.CLI.ids()
    if CACHE.cliIds then return CACHE.cliIds end
    local exact, norm, dup = {}, {}, {}
    for _, cr in ipairs(df.global.world.raws.creatures.all) do
        local id = cr.creature_id
        exact[id] = true
        local n = id:gsub('[%s,]+', '_')
        if n ~= id then if norm[n] and norm[n] ~= id then dup[n] = true end; norm[n] = id end
    end
    for n in pairs(dup) do norm[n] = nil end   -- ambiguous: never guess
    CACHE.cliIds = { exact = exact, norm = norm }
    return CACHE.cliIds
end
function V7.CLI.resolve(a)
    if type(a) ~= 'string' or not (a:find('#', 1, true) or a:find('_', 1, true)) then return a end
    local pre, tok = a:match('^([%a%d]+:)(.+)$')   -- water:, cavern:, deep:, cavern2: (groups hold)
    if not pre then pre, tok = '', a end
    local all = df.global.world.raws.creatures.all
    local n = tok:match('^#(%d+)$')
    if n then
        local cr = all[tonumber(n)]
        return cr and (pre .. cr.creature_id) or a
    end
    local T = V7.CLI.ids()
    if T.exact[tok] or not T.norm[tok] then return a end
    return pre .. T.norm[tok]
end
function V7.CLI.args(args)
    if not (dfhack.isWorldLoaded and dfhack.isWorldLoaded()) then return args end
    local ok, out = pcall(function()
        local o = { args[1] }
        for i = 2, #args do o[i] = V7.CLI.resolve(args[i]) end
        return o
    end)
    return ok and out or args
end
_ENV.resolveArg = function(a) local ok, r = pcall(V7.CLI.resolve, a); return ok and r or a end   -- the window and web may reuse it

-- v7.1 (aquarium stream; docs/v7.1/aquarium.md): `seasonal-wildlife aquarium ...`. The switches are config keys set here;
-- install / restore / uninstall / status / probe / rearm run in scripts/seasonal-wildlife-aquarium.lua (the overlays'
-- module), which builds the graphics mod with -aquarium-gfx.lua. No unit, raw or save is written by any of it.
V7.AQ.WORDS = { lens = 'lens', legend = 'legend', schools = 'schools', surf = 'surf', foam = 'foam', veil = 'veil',
                depth = 'depth', fade = 'fade', rows = 'legend_rows', hz = 'scan_hz', budget = 'budget_ms',
                trip = 'trip_frames', marks = 'marks', color = 'color', waves = 'waves', preset = 'preset',
                bed = 'bed', beddepth = 'bed_depth', bedtint = 'bed_tint', bedriver = 'bed_river', bedlift = 'bed_lift',
                bedabsorb = 'bed_absorb', bedmaterial = 'bed_material', bedbelow = 'bed_below', bedrivermud = 'bed_river_mud', streaks = 'streaks', streakslayer = 'streaks_layer', shimmer = 'shimmer',
                shimmerdepth = 'shimmer_depth' }
-- v7.1-bed: `aquarium bed depth N | tint X | river pebbles|floor|df` reads as the one-word forms above
V7.AQ.BEDWORDS = { depth = 'beddepth', tint = 'bedtint', river = 'bedriver', lift = 'bedlift', absorb = 'bedabsorb',
                   material = 'bedmaterial', below = 'bedbelow', ['river-mud'] = 'bedrivermud' }
-- v7.1-waves: `aquarium streaks layer top|under` and `aquarium shimmer depth N` likewise
V7.AQ.SUBWORDS = { streaks = { layer = 'streakslayer' }, shimmer = { depth = 'shimmerdepth' } }
V7.AQ.USAGE = 'usage: seasonal-wildlife aquarium [status | on|off | lens|legend|schools|surf|foam|veil on|off | depth N | fade X | '
    .. 'rows N | color level|kind|group | waves auto|on|off | bed auto|on|off | bed depth N | bed tint X | bed absorb X | bed lift on|off | '
    .. 'bed river pebbles|floor|df | bed material sand-mud|auto | bed below on|off | bed river-mud on|off | streaks on|off | streaks layer top|under | shimmer on|off | shimmer depth N | '
    .. 'budget MS | trip N | marks N | hz N | rearm | '
    .. 'preset vanilla|subtle|aquarium|clear|shallows|custom | alpha A7 A6 A5 A4 A3 A2 A1 | install [PRESET] | restore | '
    .. 'uninstall [force] | probe]'
function V7.AQ.statusLine(cfg)
    local a = (cfg or loadConfig()).aquarium or V7.aqDefaults()
    return ('aquarium: %s; lens %s (depth %d, %s colours), legend %s, waves %s, veil %s, bed %s, river streaks %s, shimmer %s; mod preset %s (`aquarium status`: overlays, fuses, the mod)')
        :format(a.enabled and 'on' or 'OFF', a.lens and 'on' or 'off', a.depth, a.color, a.legend and 'on' or 'off', a.waves,
                a.veil and 'ON (experimental)' or 'off', tostring(a.bed or 'auto'), a.streaks == false and 'off' or 'on',
                a.shimmer == false and 'off' or 'on', a.preset)
end
function V7.AQ.runtime(words, a)
    local ok, mod = pcall(reqscript, 'seasonal-wildlife-aquarium')
    if not ok or type(mod) ~= 'table' or not mod.verb then
        print('the aquarium module is not installed (copy scripts/seasonal-wildlife-aquarium.lua and -aquarium-gfx.lua next to this script): ' .. tostring(mod))
        return false
    end
    local rok, lines, good = pcall(mod.verb, words, a)
    if not rok then print('aquarium: ' .. tostring(lines)); return false end
    for _, l in ipairs(lines or {}) do print(l) end
    return good
end
function V7.AQ.verb(args)
    local c = loadConfig()
    local a = c.aquarium
    local w, v = args[2], args[3]
    if w == 'bed' and V7.AQ.BEDWORDS[v] then w, v = V7.AQ.BEDWORDS[v], args[4] end
    if V7.AQ.SUBWORDS[w] and V7.AQ.SUBWORDS[w][v] then w, v = V7.AQ.SUBWORDS[w][v], args[4] end
    local function set(key, val, label)
        a[key] = val
        saveConfig(c)
        LEDGER.add('edit', 'water', 'aquarium %s %s', label or key, tostring(val))
        print(('aquarium %s: %s'):format(label or key, tostring(val)))
    end
    if not w or w == 'status' then
        print(V7.AQ.statusLine(c)); V7.AQ.runtime({ 'status' }, a); return
    elseif w == 'on' or w == 'off' then set('enabled', w == 'on', 'overlays')
    elseif w == 'install' or w == 'restore' or w == 'uninstall' or w == 'probe' or w == 'rearm' then
        if w == 'install' and v then
            local okP = false
            for _, o in ipairs(V7.AQ.ENUM.preset) do if o == v then okP = true end end
            if not okP then print(V7.AQ.USAGE); return end
            a.preset = v; saveConfig(c)
        end
        local good = V7.AQ.runtime({ w, v }, a)
        if good and (w == 'install' or w == 'restore' or w == 'uninstall') then
            LEDGER.add('edit', 'water', 'aquarium mod %s%s', w, w == 'install' and (' (preset ' .. a.preset .. ')') or '')
        end
    elseif w == 'alpha' then
        local vals = {}
        for i = 3, 9 do
            local n = tonumber(args[i])
            if not n or n < 0 or n > 255 or n ~= math.floor(n) then print('aquarium alpha takes 7 whole numbers 0-255 (tile water level 7 to 1)'); return end
            vals[#vals + 1] = n
        end
        a.alpha = vals
        set('preset', 'custom', 'preset')
        print('custom alphas set; `seasonal-wildlife aquarium install` writes them into the mod')
    elseif V7.AQ.WORDS[w] then
        local key = V7.AQ.WORDS[w]
        local d, lim, opts = V7.AQ.DEF[key], V7.AQ.NUM[key], V7.AQ.ENUM[key]
        if type(d) == 'boolean' then
            if v ~= 'on' and v ~= 'off' then print(V7.AQ.USAGE); return end
            set(key, v == 'on', w)
        elseif lim then
            local n = tonumber(v)
            if not n or n < lim[1] or n > lim[2] or (lim[3] and n ~= math.floor(n)) then
                print(('aquarium %s takes %s %s-%s'):format(w, lim[3] and 'a whole number' or 'a number', lim[1], lim[2])); return
            end
            set(key, lim[3] and math.floor(n) or n, w)
        elseif opts then
            local okO = false
            for _, o in ipairs(opts) do if o == v then okO = true end end
            if not okO then print(('aquarium %s takes one of %s'):format(w, table.concat(opts, ', '))); return end
            set(key, v, w)
            if key == 'preset' then print('`seasonal-wildlife aquarium install` writes this preset into the mod; a world using it shows it after a reload') end
        end
    else
        print(V7.AQ.USAGE)
    end
end

if dfhack_flags and dfhack_flags.module then return end
-- v6.3.0: the console dispatch is a function of its own. Its branch locals used to count against the main
-- chunk's 200-local limit, which the engine had reached (the `place` verb read its depth argument inline
-- to stay under it); inside a function they are that function's, and the engine has room to grow.
local function dispatch(args)
local cmd = args[1]
if not cmd or cmd == 'gui' then show_gui()
elseif cmd == 'water' then
    -- v6.5.0 (W4): the water layer's draws (Driver B). on|off, now (one draw at once, past the gap and the group
    -- count but under the ceiling), survey (re-read the map's water), countdown N (ticks a drawn group stays)
    local c = loadConfig()
    local sub = args[2]
    if sub == 'on' or sub == 'off' then
        c.water.enabled = (sub == 'on')
        if sub == 'on' then
            c.layers.water = true; c.water.layer_set = true
            if dfhack.isMapLoaded() then ROSTER.normalize(c, buildPool(c)) end   -- v6.3.0: the layer's species join the roster whole
        end
        saveConfig(c); LEDGER.add('edit', 'water', 'water draws %s', sub)
    elseif sub == 'countdown' then
        local v = tonumber(args[3])
        if not v or v < 1 then print('usage: seasonal-wildlife water countdown <ticks>') return end
        c.water.countdown = math.floor(v); saveConfig(c)
    elseif sub == 'target' or sub == 'cadence' then
        print('water: retired in v6.5 -- each water body is drawn in groups under its cap (`limits formula|fixed N`; `limits water ceiling N`), on the adaptive clock (`groups clock`)') return
    elseif sub == 'now' then
        if not dfhack.isMapLoaded() then print('water: no map loaded') return end
        local t0, g = nowMs(), loadGroups()
        local ceil, present = c.limits.water.ceiling, WILD.countByLayer().water
        local body = (args[3] == 'ocean' or args[3] == 'lake' or args[3] == 'river' or args[3] == 'pool') and args[3] or nil   -- v7.1: `water now BODY` draws with that body's community weights
        local grp, why = ENGINE.draw(c, g, nil, ceil > 0 and math.max(0, ceil - present) or nil, body)
        if grp then V7.GRP.cohere(c, g, grp) end
        saveGroups(g)
        print(grp and ('water: drew %s x%d into the %s (%s); %s  [%d ms]'):format(grp.token, #grp.ids, grp.body, grp.salt,
                          grp.entry and ('entered %s #%d %s at %d,%d,%d, level %d/7'):format(grp.body, grp.wb or 0, grp.entry.how == 'edge' and 'at the map edge' or 'nearest its centroid',
                              grp.entry.x, grp.entry.y, grp.entry.z, grp.entry.level or 0) or 'no entry record', nowMs() - t0)
                   or ('water: drew nothing -- %s  [%d ms]'):format(why or '?', nowMs() - t0))
    elseif sub == 'survey' or sub == 'depth' then
        -- v7.1 (water, R22, C §8.1): `survey` re-reads the water; `depth` prints the column-depth histogram (`depth full`
        -- re-reads every column once, stride 1, whatever water.survey_stride says)
        if not dfhack.isMapLoaded() then print('water: no map loaded') return end
        if sub == 'survey' or args[3] == 'full' then
            CACHE.cfg = CACHE.cfg or c
            local w = ENGINE.waterTiles(true, args[3] == 'full' and 1 or nil)
            CACHE.watCensus = nil
            print(('water: the surface water re-read in %d ms -- %d sampled water tile(s) in %d column(s)%s'):format(w.ms or 0, #w.tiles, w.ncols or 0, w.stopped and ' (stopped at its budget)' or ''))
        end
        for _, l in ipairs(V7.WAT.depthLines(c)) do print(l) end
        if sub == 'depth' then return end
    elseif sub == 'layer' then
        -- v7.1 (fixes, R45 ruling): `water layer auto|on|off` -- auto follows the map (on where it has water)
        local v = args[3]
        if v == 'on' or v == 'off' then c.layers.water = (v == 'on'); c.water.layer_set = true
        elseif v == 'auto' then
            c.water.layer_set, c.water.layer_auto = false, true
            -- v7.1 (web-live ctl.registry_restored): auto is read from the map when the tool runs on this fort (enable, a
            -- load while enabled, the first-open preset) -- and here at once only when it is running. On a fort where the
            -- tool is off the stored layer stays as it was, so the registry's (water.layer_mode, switch.water) pair puts
            -- back what it read: the run's baseline (auto, off) on a disabled wet fort came back (auto, on).
            if not c.enabled then print('water: the layer follows the map from now on; it is read when the tool runs on this fort (it is off)')
            elseif V7.WAT.autoLayer(c) then print('water: the map has ' .. tostring(CACHE.watLayerWhy) .. '; the layer is on') end
        else print('usage: seasonal-wildlife water layer auto|on|off   (auto: on wherever the map has water, the default)') return end
        if dfhack.isMapLoaded() then ROSTER.normalize(c, buildPool(c)) end
        saveConfig(c); LEDGER.add('edit', 'water', 'water layer %s', v)
    elseif sub == 'spill' then
        -- v7.1 (fixes, R45 ruling): `water spill [on|off] [min N]` -- a thin body borrows the season for water species
        local rest = {}
        for i = 3, #args do rest[#rest+1] = args[i] end
        local err = V7.WAT.setArgs(c, 'spill', rest, 1)
        if err then print('usage: seasonal-wildlife water spill [on|off] [min N]   -- ' .. err) return end
        if not c.water.spill.enabled then V7.WAT.spillRoll(c, true) end
        CACHE.watSpillAt = nil
        if #rest > 0 then saveConfig(c); LEDGER.add('edit', 'water', 'water spill %s', table.concat(rest, ' ')) end
        if c.enabled and c.water.spill.enabled and dfhack.isMapLoaded() then
            local g = loadGroups(); local n = V7.WAT.spillCheck(c, g)
            if n > 0 then print(('water: %d species borrowed the season'):format(n)) end
        end
    elseif sub == 'guard' then
        -- v7.1-place (user 2 Oct 2026): the stranding guard is removed; placement itself is fixed instead
        print('water guard: removed (v7.1-place, user ruling 2 Oct 2026) -- every swimmer enters at its body\'s map edge, or nearest the centroid of an enclosed lake or pool, in water at level 4/7 or more; real beaching is left to DF (`water bodies`)')
        return
    elseif sub == 'scan' then
        -- v7.1-place: `water scan` -- rescan the water bodies now (sliced; the current registry stays in use until done)
        if not dfhack.isMapLoaded() then print('water: no map loaded') return end
        CACHE.cfg = CACHE.cfg or c
        local old = CACHE.wb
        local ok, why = V7.WB.start(c, 'water scan')
        local sl = CACHE.slices and CACHE.slices.wbscan
        local R = CACHE.wb
        if ok and R and R ~= old and not (sl and not sl.dead) then   -- it ran at once (slicing off): the result now
            for _, l in ipairs(V7.WB.lines(R, 40)) do print(l) end
            print('  changes: ' .. V7.WB.changeText(R))
        else
            print(ok and 'water scan: started; the new registry replaces the current one when it is done (`water bodies`)' or ('water scan: ' .. tostring(why)))
        end
        return
    elseif sub == 'bodies' then
        -- v7.1-place: `water bodies [TYPE]` lists the registry; `water bodies [min N] [pool_max N] [slice MS]` sets it (the
        -- next scan reads the new values; `water scan` runs one now)
        if args[3] and not V7.WB.ISTYPE[args[3]] then
            local rest = {}
            for i = 3, #args do rest[#rest+1] = args[i] end
            local err = V7.WAT.setArgs(c, 'bodies', rest, 1)
            if err or rest[1] == 'on' or rest[1] == 'off' then print('usage: seasonal-wildlife water bodies [TYPE] | [min N] [pool_max N] [slice MS]   -- ' .. (err or 'no on/off here')) return end
            V7.watSanitize(c, { water = c.water })
            saveConfig(c); LEDGER.add('edit', 'water', 'water bodies %s', table.concat(rest, ' '))
            if CACHE.wb then CACHE.wb.stale = true end
            print(('water bodies: min %d tiles, pool under %d columns, %d ms slices -- read by the next scan (`water scan` now, or the next day\'s check)'):format(
                c.water.bodies.min_tiles, c.water.bodies.pool_max, c.water.bodies.scan_ms))
            return
        end
        if not dfhack.isMapLoaded() then print('water: no map loaded') return end
        CACHE.cfg = CACHE.cfg or c
        local okR, R = pcall(V7.WB.get)
        if not okR or not R then print('water bodies: no registry -- ' .. tostring(R)) return end
        local L = V7.WB.lines(R, 60)
        print(L[1])
        for i = 2, #L do if not args[3] or L[i]:find(' ' .. args[3] .. ' ', 1, true) then print(L[i]) end end
        for _, l in ipairs(V7.WB.statusLines(c, loadGroups(), R)) do print(l) end
        return
    elseif sub == 'mix' or sub == 'pull' then
        -- v7.1 (water): `water mix [on|off] [balance X] [balance_cap X] [feed X] [pyramid X] [apex N] [cap X] [BODY]`,
        -- `water pull [on|off] [k X] [min X] [cap X] [floor on|off]` (v7.1-place: the seed settings went with the seed).
        -- With no settings, `water mix` prints the census and every species' weight per body (a dry run).
        local body = (sub == 'mix') and (args[#args] == 'ocean' or args[#args] == 'lake' or args[#args] == 'river' or args[#args] == 'pool') and args[#args] or nil
        local rest = {}
        for i = 3, #args - (body and 1 or 0) do rest[#rest+1] = args[i] end
        if #rest > 0 then
            local err = V7.WAT.setArgs(c, sub, rest, 1)
            if err then print(('usage: seasonal-wildlife water %s ...  -- %s (see `seasonal-wildlife help`)'):format(sub, err)) return end
            saveConfig(c); CACHE.watCensus = nil
            LEDGER.add('edit', 'water', 'water %s %s', sub, table.concat(rest, ' '))
        end
        if sub == 'mix' and #rest == 0 and dfhack.isMapLoaded() then
            for _, l in ipairs(V7.WAT.mixLines(c, loadGroups(), body)) do print(l) end
            return
        end
    elseif sub == 'levels' then
        local v = tonumber(args[3])
        if not v or v < 1 or v > 20 then print('usage: seasonal-wildlife water levels <N>   (the column depth, in stacked water tiles, that counts as deep; 1-20)') return end
        c.water.column_levels = math.floor(v); c.water.deep_levels = nil; saveConfig(c); CACHE.deepCols = nil
    elseif sub == 'aquatic' then
        if args[3] ~= 'on' and args[3] ~= 'off' then print('usage: seasonal-wildlife water aquatic on|off   (draw AQUATIC species listed on land-layer entries too)') return end
        c.water.land_aquatic = (args[3] == 'on'); saveConfig(c); CACHE.watLandAq = nil
    elseif sub == 'budget' then
        local v, st = tonumber(args[3]), tonumber(args[5])
        if not v or v < 100 or v > 1900 or (args[4] and (args[4] ~= 'stride' or not (st == 1 or st == 2))) then
            print('usage: seasonal-wildlife water budget <ms 100-1900> [stride 1|2]   (the water survey\'s deadline and sampling)') return
        end
        c.water.survey_ms = math.floor(v); if st then c.water.survey_stride = st end; saveConfig(c)
    elseif sub == 'retry' then
        local v = tonumber(args[3])
        if not v or v < 0.1 or v > 30 then print('usage: seasonal-wildlife water retry <days 0.1-30>   (back-off after a draw that found nothing)') return end
        c.water.retry_days = v; saveConfig(c)
    elseif sub and sub ~= 'status' then
        print('usage: seasonal-wildlife water [on|off|now [BODY]|scan|bodies [TYPE|min N|pool_max N|slice MS]|survey|depth [full]|mix ...|pull ...|layer auto|on|off|spill [on|off] [min N]|levels N|aquatic on|off|budget MS [stride N]|retry D|countdown N|status]   (limits: `limits formula|fixed N`)') return
    end
    print(ENGINE.status(c))
    print(('  %d group(s) at once per water body, ceiling %s, a drawn group stays ~%d ticks'):format(QUOTA.groupsFor(c, 'water'),   -- v7.1 (R45)
        c.limits.water.ceiling > 0 and tostring(c.limits.water.ceiling) or 'none', c.water.countdown))
    print(V7.WAT.layerLine(c))   -- v7.1 (fixes): the layer's default and the season spill
    if dfhack.isMapLoaded() then for _, l in ipairs(V7.WAT.statusLines(c, loadGroups())) do print(l) end end   -- v7.1 (water)

elseif cmd == 'limits' or cmd == 'quota' then
    -- v6.5.0 (W4, Q6): `limits [land|water|cavern] [groups N] [ceiling N]`. `quota` is the retired name, kept as an
    -- alias with its old meaning: `quota land N` was the land group count, `quota water|cavern N` the ceiling.
    local c = loadConfig()
    local lay = args[2]
    -- v7.1 (R7): `limits formula` | `limits fixed N` -- the one toggle: the map-size formula on every layer, or one fixed
    -- cap on every layer (for slower computers). The cavern cap is R44's own (`groups cavern cap N`).
    if lay == 'formula' or lay == 'fixed' then
        if lay == 'fixed' then
            local n = tonumber(args[3])
            if args[3] and not (n and n >= 1) then print('usage: seasonal-wildlife limits fixed <N>   (N >= 1; every layer, caverns at most their own cap)') return end
            c.limits.mode = 'fixed'; if n then c.limits.fixed = math.floor(n) end
        else c.limits.mode = 'formula' end
        saveConfig(c); LEDGER.add('edit', '', 'limits %s%s', c.limits.mode, c.limits.mode == 'fixed' and (' ' .. c.limits.fixed) or '')
        lay = nil
    end
    if lay then
        if not (lay == 'land' or lay == 'water' or lay == 'cavern') then print('usage: seasonal-wildlife limits [formula | fixed N | land|water|cavern [groups N|auto] [ceiling N]]   (ceiling 0 = none)') return end
        local pairs_ = {}
        if cmd == 'quota' then
            if not (tonumber(args[3]) and tonumber(args[3]) >= 0) then print('usage: seasonal-wildlife quota [land|water|cavern] <n>   (n >= 0; retired: see `limits`)') return end   -- v6.6.0: -1 was taken (validation 224926)
            pairs_[#pairs_+1] = { lay == 'land' and 'groups' or 'ceiling', tonumber(args[3]) }
            print('note: quota is retired; every layer has the same two limits now -- groups at once and ceiling (`limits`)')
        else
            local i = 3
            while args[i] do
                if (args[i] == 'groups' or args[i] == 'ceiling') and tonumber(args[i+1]) and tonumber(args[i+1]) >= 0 then pairs_[#pairs_+1] = { args[i], tonumber(args[i+1]) }
                elseif args[i] == 'groups' and args[i+1] == 'auto' then pairs_[#pairs_+1] = { 'auto', true }
                else print('usage: seasonal-wildlife limits [land|water|cavern] [groups N|auto] [ceiling N]   (ceiling 0 = none; auto = sqrt(embark) + 1)') return end
                i = i + 2
            end
        end
        for _, kv in ipairs(pairs_) do
            -- v7.1 (R7): a per-layer group number is retired. `groups auto` is the formula; `groups N` is the single fixed
            -- cap N on EVERY layer (said so below), and on the caverns it is R44's cavern cap
            if kv[1] == 'auto' then c.limits.mode = 'formula'; LEDGER.add('edit', '', 'limits formula (map size, every layer)')
            elseif kv[1] == 'groups' and lay == 'cavern' then
                c.groups.cavern_cap = math.max(1, math.floor(kv[2])); c.groups.cavern_max = c.groups.cavern_cap
                LEDGER.add('edit', 'cavern', 'cavern cap %d', c.groups.cavern_cap)
            elseif kv[1] == 'groups' then
                c.limits.mode, c.limits.fixed = 'fixed', math.max(1, math.floor(kv[2]))
                print(('note: per-layer group numbers are retired (R7): every layer now has the single fixed cap %d (`limits formula` goes back to the map-size formula)'):format(c.limits.fixed))
                LEDGER.add('edit', '', 'limits fixed %d (from `limits %s groups`)', c.limits.fixed, lay)
            else
                QUOTA.set(c, lay, kv[1], kv[2]); LEDGER.add('edit', lay, '%s %s %d', lay, 'ceiling', kv[2])
            end
        end
        saveConfig(c)
        if lay == 'cavern' and (c.limits.cavern.ceiling or 0) > 0 then
            print('note: the cavern ceiling holds new ARRIVALS (managed cavern species at frequency 1 while the caverns are over it);')
            print('      it removes nothing already there -- measured at 44 days from 28 to 9 as DF walked residents off (addendum 57).')
        end
    end
    print(QUOTA.status(c))
    if dfhack.isMapLoaded() then
        local by = WILD.countByLayer()
        print(('  on the map now: land %d  water %d  cavern %d  deep %d'):format(by.land, by.water, by.cavern, by.deep))
    end

elseif cmd == 'status' then cmdStatus()
elseif cmd == 'now' then
    local t0 = nowMs(); local c = loadConfig()
    local _, seasoned, cleared = ROSTER.normalize(c, buildPool(c)); saveConfig(c)
    local n = applyLive(c, df.global.cur_season)
    print(('active: %d  [%d ms]%s'):format(n, nowMs() - t0, (seasoned + cleared > 0) and (' (roster made whole: %d given a season, %d inactive cleared)'):format(seasoned, cleared) or ''))
elseif cmd == 'classes' then
    local cfg = loadConfig()
    local pool = buildPool(cfg)
    local counts, uncl = classReview(cfg, pool)
    for _, c in ipairs(ECOLOGY_CLASSES) do
        print(('  %-13s %-9s %d'):format(c, c == 'natural' and 'managed' or 'left to DF', counts[c] or 0))
    end
    if #uncl > 0 then
        print('  unclassified -- review and set an override with: seasonal-wildlife class <TOKEN> <class>')
        for _, u in ipairs(uncl) do print(('    %-26s %s'):format(u.token, u.why)) end
    end
elseif cmd == 'class' then
    -- v6.3.0 (D8): a creature can be brought in as natural, or handed back to its own class ('auto'); the
    -- special classes (demons, megabeasts, night creatures, mythic) are DF's and cannot be switched on
    local cfg = loadConfig(); local tok, cls = args[2], args[3]
    if not tok or (cls ~= 'natural' and cls ~= 'auto') then
        print('usage: seasonal-wildlife class <TOKEN> natural|auto   (special creatures -- demons, megabeasts, titans, forgotten beasts, night creatures, mythic -- are left to DF)') return
    end
    cfg.class_override[tok] = (cls == 'natural') and 'natural' or nil; saveConfig(cfg); print(tok .. ' -> ' .. cls)
elseif cmd == 'groups' then
    local sub = args[2]
    if sub == 'on' then enableGroups(); print('resident groups: on')
    elseif sub == 'off' then disableGroups(); print('resident groups: off')
    elseif sub == 'coupling' or sub == 'piggyback' then  -- 'piggyback' kept as an alias
        local c = loadConfig(); c.groups.coupling = (args[3] ~= 'off'); saveConfig(c)
        print('migratory coupling: ' .. (c.groups.coupling and 'on' or 'off'))
    elseif sub == 'ecology' then
        local c = loadConfig()
        if args[3] == 'on' or args[3] == 'off' then
            c.ecology.enabled = (args[3] == 'on'); saveConfig(c)
            if c.enabled and c.groups.enabled then scheduleGroups() end
            if dfhack.isMapLoaded() then CURIOUS.apply(c) end   -- v6.9.0: curated predators lose or regain BENIGN
            print('ecology: ' .. (c.ecology.enabled and 'on' or 'off'))
        elseif args[3] == 'now' then
            local g = loadGroups(); ecologyRun(c, g); saveGroups(g); print(ecologyStatus(c, g))
        elseif args[3] == 'cadence' and tonumber(args[4]) then   -- v7.1 (R37): default 3,000
            c.ecology.cadence = math.max(100, math.floor(tonumber(args[4]))); saveConfig(c)
            if c.enabled and c.groups.enabled then scheduleGroups() end
            LEDGER.add('edit', '', 'ecology cadence %d', c.ecology.cadence)
            print(('ecology: every %d ticks'):format(c.ecology.cadence))
        else print(ecologyStatus(c, loadGroups())) end
    elseif sub == 'cavern' then
        -- v7.1 (R44): `groups cavern [on|off | cap N | hold any|all|off | mix on|off | trim on|off | trim_days N | shared on|off | natives on|off]`
        local c = loadConfig()
        local a, v = args[3], args[4]
        if a == 'on' or a == 'off' then c.groups.cavern = (a == 'on')
        elseif (a == 'cap' or a == 'max') and tonumber(v) then c.groups.cavern_cap = math.max(1, math.floor(tonumber(v))); c.groups.cavern_max = c.groups.cavern_cap
        elseif a == 'hold' and (v == 'any' or v == 'all' or v == 'off') then c.groups.cavern_hold = v
        elseif a == 'trim' and (v == 'on' or v == 'off') then c.groups.cavern_trim = (v == 'on')
        elseif a == 'trim_days' and tonumber(v) then c.groups.cavern_trim_days = math.max(1, math.floor(tonumber(v)))
        elseif a == 'trim_gated' and (v == 'on' or v == 'off') then c.groups.cavern_trim_gated = (v == 'on')   -- v7.1-rc-trimgated
        elseif a == 'shared' and (v == 'on' or v == 'off') then c.groups.cavern_hold_shared = (v == 'on')
        elseif a == 'mix' and (v == 'on' or v == 'off') then c.groups.cavern_hold_mix = (v == 'on')   -- v7.1 (Alpha Four 3.8)
        elseif a == 'natives' and (v == 'on' or v == 'off') then c.groups.natives_cavern = (v == 'on')
        elseif a then print('usage: seasonal-wildlife groups cavern [on|off | cap N | hold any|all|off | mix on|off | trim on|off | trim_days N | trim_gated on|off | shared on|off | natives on|off]') return end
        if a then saveConfig(c); LEDGER.add('edit', 'cavern', 'groups cavern %s %s', a, v or '') end
        print(('groups: cavern gate %s, cap %d groups per cavern (R44); hold %s%s, %s; trim %s every %d day(s)%s; natives %s'):format(
            c.groups.cavern and 'on' or 'off', QUOTA.groupsFor(c, 'cavern'), c.groups.cavern_hold, c.groups.cavern_hold_shared and ' (shared species too)' or '',
            V7.GRP.holdWords(c),
            c.groups.cavern_trim and 'on' or 'off', c.groups.cavern_trim_days, c.groups.cavern_trim_gated and ' (DF waves too)' or '',
            c.groups.natives_cavern and 'counted' or 'not counted'))
    elseif sub == 'adopt' then
        -- v7.1 (H3): `groups adopt <unit id> <unit id> ...` -- these units become ONE tracked group, led by R32's rule
        if not dfhack.isMapLoaded() then print('groups adopt: no map loaded') return end
        local ids = {}
        for i = 3, #args do ids[#ids+1] = args[i] end
        if #ids == 0 then print('usage: seasonal-wildlife groups adopt <unit id> [unit id ...]') return end
        local grp, why = V7.GRP.adoptPlaced(ids, { placed = false })
        if not grp then print('groups adopt: ' .. tostring(why)) return end
        print(('adopted %s x%d as one %s group on %s%s'):format(grp.token, #grp.ids, grp.label or 'group', V7.GRP.lk(grp) or grp.layer,
            grp.leader and (', led by #' .. grp.leader) or (', unled: ' .. (grp.unled or 'one animal'))))
    elseif sub == 'layers' or sub == 'limits' then   -- v7.1: the per-layer lines (cap, target, groups, W, next release, leaders)
        local c = loadConfig()
        for _, l in ipairs(V7.GRP.status(c, loadGroups())) do print(l) end
    elseif sub == 'adaptive' or sub == 'clock' then
        -- v7.1 (R31): `groups clock [on|off] [band N] [catchup X] [jitter X] [floor DAYS] [max DAYS] [alpha X] [prior land|water|cavern TICKS]`
        local c = loadConfig()
        local i = 3
        while args[i] do
            local a, v = args[i], args[i+1]
            if a == 'on' or a == 'off' then c.groups.adaptive = (a == 'on'); i = i + 1
            elseif a == 'band' and tonumber(v) and tonumber(v) >= 0 and tonumber(v) <= 10 then c.groups.target_band = tonumber(v); i = i + 2
            elseif a == 'catchup' and tonumber(v) and tonumber(v) >= 0 and tonumber(v) <= 10 then c.groups.catchup = tonumber(v); i = i + 2
            elseif a == 'jitter' and tonumber(v) and tonumber(v) >= 0 and tonumber(v) <= 0.9 then c.groups.gap_jitter = tonumber(v); i = i + 2
            elseif a == 'floor' and tonumber(v) and tonumber(v) >= 0.1 then c.groups.gap_floor_days = tonumber(v); i = i + 2
            elseif a == 'max' and tonumber(v) and tonumber(v) >= 1 then c.groups.gap_max_days = math.floor(tonumber(v)); i = i + 2
            elseif a == 'alpha' and tonumber(v) and tonumber(v) > 0 and tonumber(v) <= 1 then c.groups.w_alpha = tonumber(v); i = i + 2
            elseif a == 'prior' and (v == 'land' or v == 'water' or v == 'cavern') and tonumber(args[i+2]) and tonumber(args[i+2]) >= 1 then
                c.groups['w_prior_' .. v] = math.floor(tonumber(args[i+2])); i = i + 3
            else print('usage: seasonal-wildlife groups clock [on|off] [band N] [catchup X] [jitter X] [floor DAYS] [max DAYS] [alpha X] [prior land|water|cavern TICKS]') return end
        end
        if args[3] then saveConfig(c); LEDGER.add('edit', '', 'groups clock %s', table.concat(args, ' ', 3)) end
        print(V7.GRP.status(c, loadGroups())[2])
    elseif sub == 'panic' then
        -- v7.1 (R32): `groups panic [on|off] [days N] [tiles N] [mode scatter|edge] [flocks on|off] [reelect on|off] [leader male|lowest]`
        local c = loadConfig()
        local i = 3
        while args[i] do
            local a, v = args[i], args[i+1]
            if a == 'on' or a == 'off' then c.groups.panic = (a == 'on'); i = i + 1
            elseif a == 'days' and tonumber(v) and tonumber(v) >= 1 then c.groups.panic_days = math.floor(tonumber(v)); i = i + 2
            elseif a == 'tiles' and tonumber(v) and tonumber(v) >= 1 then c.groups.panic_tiles = math.floor(tonumber(v)); i = i + 2
            elseif a == 'mode' and (v == 'scatter' or v == 'edge') then c.groups.panic_mode = v; i = i + 2
            elseif a == 'flocks' and (v == 'on' or v == 'off') then c.groups.panic_flocks = (v == 'on'); i = i + 2
            elseif a == 'reelect' and (v == 'on' or v == 'off') then c.groups.reelect_after_panic = (v == 'on'); i = i + 2
            elseif a == 'leader' and (v == 'male' or v == 'lowest') then c.v7.leader_male = (v == 'male'); i = i + 2
            else print('usage: seasonal-wildlife groups panic [on|off] [days N] [tiles N] [mode scatter|edge] [flocks on|off] [reelect on|off] [leader male|lowest]') return end
        end
        if args[3] then saveConfig(c); LEDGER.add('edit', '', 'groups panic %s', table.concat(args, ' ', 3)) end
        local st = V7.GRP.status(c, loadGroups())
        print(st[#st - 1])
    elseif sub == 'natives' then
        -- v7.1: `groups natives [cavern|land|water on|off | now]` -- which unflagged wild animals become groups
        local c = loadConfig()
        local a, v = args[3], args[4]
        local k = ({ cavern = 'natives_cavern', land = 'natives_land', water = 'seeded_water' })[a or '']
        if k and (v == 'on' or v == 'off') then c.groups[k] = (v == 'on'); saveConfig(c); LEDGER.add('edit', '', 'groups natives %s %s', a, v)
        elseif a == 'now' and dfhack.isMapLoaded() then
            local g = loadGroups(); local n, born = V7.GRP.adoptNatives(c, g, true); saveGroups(g)
            print(('adopted %d native or seeded group(s); %d young joined their mothers\' groups'):format(n, born))
        elseif a then print('usage: seasonal-wildlife groups natives [cavern|land|water on|off | now]') return end
        print(('natives: cavern %s, land %s (counted against their cap); DF\'s seeded water schools %s (led, never counted)'):format(
            c.groups.natives_cavern and 'adopted' or 'not adopted', c.groups.natives_land and 'adopted' or 'not adopted', c.groups.seeded_water and 'adopted' or 'not adopted'))
    elseif sub == 'apcap' then
        -- v7.1 (R35): `groups apcap N|off` -- the animal-people group size in the caverns (lifted during an irruption)
        local c = loadConfig()
        local v = args[3]
        if v == 'off' then c.groups.apcap = 0
        elseif tonumber(v) and tonumber(v) >= 1 then c.groups.apcap = math.floor(tonumber(v))
        elseif v then print('usage: seasonal-wildlife groups apcap <N|off>') return end
        if v then saveConfig(c); LEDGER.add('edit', 'cavern', 'animal-people cap %s', v) end
        local n = dfhack.isMapLoaded() and V7.GRP.apCap(c) or 0
        print(('animal-people cap: %s; %d species capped now'):format(c.groups.apcap > 0 and (c.groups.apcap .. ' a group') or 'off', n))
    elseif sub == 'livestock' then
        local c = loadConfig(); c.ecology.livestock = (args[3] == 'on'); saveConfig(c)
        print('fort livestock is ' .. (c.ecology.livestock and 'a target' or 'safe'))
    elseif sub == 'nudge' then
        local c = loadConfig()
        c.ecology.far_tiles = math.max(1, tonumber(args[3]) or c.ecology.far_tiles)
        c.ecology.far_ticks = math.max(1, tonumber(args[4]) or c.ecology.far_ticks)
        c.ecology.radius = math.max(2, tonumber(args[5]) or c.ecology.radius); saveConfig(c)
        print(('nudge: after %d ticks more than %d tiles apart, to within %d'):format(c.ecology.far_ticks, c.ecology.far_tiles, c.ecology.radius))
    elseif sub == 'pack' then
        local c = loadConfig(); c.groups.pack = math.max(0, tonumber(args[3]) or 0); saveConfig(c)
        print('coupling pack size: ' .. (c.groups.pack > 0 and tostring(c.groups.pack) or 'raw default'))
    elseif sub == 'cohesion' then
        local c = loadConfig()
        if args[3] == 'on' or args[3] == 'off' then c.groups.cohesion = (args[3] == 'on')
        else
            local i = 3
            while args[i] and args[i+1] do
                local k = 'follow_' .. args[i]
                if c.groups[k] and tonumber(args[i+1]) then c.groups[k] = math.max(1, math.floor(tonumber(args[i+1]))) end
                i = i + 2
            end
        end
        saveConfig(c)
        local g = loadGroups(); local led, newly = applyCohesion(c, g); saveGroups(g)
        print(('cohesion: %s  herd %d  pack %d  flock %d  (%d group(s) led, %d follower(s) set)'):format(
            c.groups.cohesion and 'on' or 'off', c.groups.follow_herd, c.groups.follow_pack, c.groups.follow_flock, led, newly))
    elseif sub == 'hold' or sub == 'dismiss' then
        local token, days = args[3], tonumber(args[4])
        if not token or (sub == 'hold' and not days) then print('usage: seasonal-wildlife groups hold <TOKEN> <days> | groups dismiss <TOKEN>') return end
        -- v5.9.4: the status line prefixes a cavern group 'cavern2:ELK_BIRD'; accept that form here and,
        -- when given, act only on the group at that depth
        local depth = tonumber(token:match('^cavern(%d+):'))
        if depth then token = token:gsub('^cavern%d+:', '') end
        local g = loadGroups(); local hit = findGroups(g, token)
        if depth then
            local only = {}
            for _, grp in ipairs(hit) do if grp.layer == 'cavern' and grp.depth == depth then only[#only+1] = grp end end
            hit = only
        end
        if #hit == 0 then print('no tracked group of ' .. token) return end
        for _, grp in ipairs(hit) do
            if sub == 'hold' then print(('held %s x%d: %d countdown(s) raised to %d days'):format(grp.token, #grp.ids, holdGroup(grp, days), days))
            else print(('dismissed %s x%d: %d countdown(s) zeroed, leader cleared'):format(grp.token, #grp.ids, dismissGroup(grp))) end
        end
        saveGroups(g)
    else
        local rows, g = groupsStatus()
        local c = loadConfig()
        print(('resident groups: %s  max=%d  gap=%d-%d days  detached=%d departed=%d  coupling=%s (%d done%s)  cohesion=%s  swept=%d')
            :format(c.groups.enabled and 'on' or 'off', QUOTA.land(c),
                    c.groups.gap_min_days, c.groups.gap_max_days, g.detached, g.departed or 0,
                    c.groups.coupling and 'on' or 'off', g.couplings or 0,
                    g.exclusion and (', pool closed for ' .. g.exclusion.prey) or '',
                    c.groups.cohesion and 'on' or 'off', g.swept or 0))
        for _, r in ipairs(rows) do print('  ' .. r) end
        for _, l in ipairs(V7.GRP.status(c, g)) do print(l) end   -- v7.1: per layer cap, target, W, next release, leaders
        print(ecologyStatus(c, g))
    end
elseif cmd == 'place' then
    -- seasonal-wildlife place <TOKEN> [n] [layer]   -- headless: no menu, no pointer, no arena
    local tok, n, want = args[2], tonumber(args[3]) or 1, args[4]   -- the optional depth is args[5], read inline: the main chunk is at Lua's 200-local limit
    if not tok then print('usage: seasonal-wildlife place <CREATURE_TOKEN> [count] [land|water|cavern [depth]]') return end
    if not dfhack.isMapLoaded() then print('place: no map loaded') return end
    local cfg = loadConfig()
    local regionSet = getEmbarkRegions()
    local best, bestLayer
    for _, pop in ipairs(df.global.world.populations.all) do
        local craw = df.creature_raw.find(pop.race)
        if craw and craw.creature_id == tok and pop.type == df.world_population_type.Animal and pop.quantity > 0 then
            local l = layerOf(pop)
            -- v5.9.5: an optional cavern depth picks the entry of THAT cavern (a species may be stocked in several)
            if (not want or l == want) and ((not tonumber(args[5])) or (l == 'cavern' and WILD.caveDepth(pop.population.cave_id) == tonumber(args[5])))
               and (not best or pop.quantity > best.quantity) then best, bestLayer = pop, l end
        end
    end
    if not best then print(('place: no stocked %s entry%s on this map'):format(tok, want and (' on the ' .. want .. ' layer') or '')) return end
    local before = best.quantity
    local t0 = nowMs()
    -- v7.1 (C §9.3 F1-F2): placed together and tracked as ONE group, led at once
    local g = loadGroups()
    local grp, why = V7.GRP.place(cfg, g, best, n)
    if not grp then print(('place: placed none -- %s  [%d ms]'):format(why or 'unknown', nowMs() - t0)) return end
    saveGroups(g)
    local ids = grp.ids
    print(('placed %d %s on the %s layer at ids %s; entry %d debited %d -> %d; one %s group%s  [%d ms]')
        :format(#ids, tok, bestLayer, table.concat(ids, ','), best.population.population_idx, before, best.quantity, grp.label or 'group',
                grp.leader and (' led by #' .. grp.leader) or (', unled: ' .. (grp.unled or 'one animal')), nowMs() - t0))
elseif cmd == 'cavern' then
    -- v6.5.0 (W4, Q5): cavern stocking is retired -- DF waves the caverns itself, and the tool steers who comes
    -- by frequency and when by the cavern gate; the cavern ceiling is `limits cavern ceiling N`
    print('cavern stocking: retired in v6.5 -- DF draws the caverns; the tool steers them by frequency (roster, odds) and the cavern gate (`groups cavern cap N`, `limits cavern ceiling N`)')
elseif cmd == 'pattern' then
    local c = loadConfig()
    local layer, name = 'land', args[2]
    if args[2] == 'land' or args[2] == 'cavern' or args[2] == 'water' then layer, name = args[2], args[3] end   -- v6.5.0: the water layer's draws keep a pattern too
    if name then
        if not PATTERN.SET[name] then print('usage: seasonal-wildlife pattern [land|water|cavern] <steady|burst|trickle|dawn|follow>') return end
        c.patterns[layer] = name; saveConfig(c)
        LEDGER.add('edit', layer, 'pattern %s', name)
        if dfhack.isMapLoaded() then PATTERN.trickleApply(c, true) end   -- v5.10.2: apply or restore the standing write at once
    end
    print(PATTERN.status(c))
    if layer == 'cavern' and name and name ~= 'steady' then print('note: cavern waves are DF\'s own (addendum 45); the cavern gate takes steady until v6.1') end
elseif cmd == 'vermin' then
    if not dfhack.isMapLoaded() then print('vermin: no map loaded') return end
    local c = loadConfig()
    local pool, biomeSet = buildPool(c)
    local sub = args[2]
    if sub == 'classes' then   -- v7.0.0 gobble (Q31): the tool's own SWV_* vermin taxonomy, world-wide
        local classes = VERMIN.allClasses()
        print(('%-18s %3s  %s'):format('CLASS', 'n', 'LABEL'))
        for _, swv in ipairs(VERMIN.SWV) do
            local list = classes[swv]
            print(('%-18s %3d  %s'):format(swv, #list, VERMIN.SWV_LABEL[swv]))
            if #list > 0 then print('  ' .. table.concat(list, ' '):sub(1, 200)) end
        end
        print(VERMIN.gobbleStatus(c))
        print(VERMIN.forageStatus(c))
    elseif sub == 'class' then   -- v7.1 (R21, R27): one SWV class in or out of the gobble wiring and of foraging
        local swv, v = args[3], args[4]
        if not (swv and VERMIN.SWV_LABEL[swv] and (v == 'on' or v == 'off')) then
            print('usage: seasonal-wildlife vermin class <SWV_X> on|off   classes: ' .. table.concat(VERMIN.SWV, ' ')) return
        end
        c.vermin_eat.classes[swv] = (v == 'on'); saveConfig(c)
        LEDGER.add('edit', '', 'vermin class %s %s', swv, v)
        print(('vermin class %s (%s): %s'):format(swv, VERMIN.SWV_LABEL[swv], v))
        if c.enabled then CACHE.cfg = nil; print(V7.apply(loadConfig())) end   -- re-wire: the class is untagged and uneaten at once
    elseif sub == 'edges' then   -- v7.1 (R51): the edge table in force, and which source feeds the writer
        local src = args[3]
        if src == 'rules' or src == 'edges' or src == 'both' then
            c.vermin_eat.source = src; saveConfig(c); LEDGER.add('edit', '', 'vermin edge source %s', src)
            if c.enabled then CACHE.cfg = nil; print(V7.apply(loadConfig())) end
        elseif src then print('usage: seasonal-wildlife vermin edges [rules|edges|both]') return end
        local rows, label = VERMIN.edges()
        print(('who eats which vermin -- source in force: %s'):format(c.vermin_eat.source))
        print('GOBBLE_RULES (the tool\'s own, v7.0):')
        for _, r in ipairs(VERMIN.GOBBLE_RULES) do print(('  %-34s %s'):format(r.name, table.concat(r.classes, ' '))) end
        print(('edge table: %s'):format(label))
        for _, r in ipairs(rows) do
            local cls = {}
            for _, vg in ipairs(r.vermin or {}) do cls[#cls+1] = vg .. '=' .. table.concat(VERMIN.VCLASS[vg] or { '?' }, '/') end
            print(('  %-34s %s'):format(r.native and 'DF native gobblers' or r.token or ((MODEL.GUILD_NAME[r.guild] or r.guild or '?') .. ' (' .. tostring(r.guild) .. ')' .. (r.where and (' in ' .. r.where) or '')),
                #cls > 0 and table.concat(cls, ' ') or '(their own class; DF wires it)'))
        end
    elseif sub == 'census' then   -- v7.1 (R21): the vermin really on the map
        for _, l in ipairs(VERMIN.censusLines(c)) do print(l) end
    elseif sub == 'eats' then     -- v7.1 (R63): forage outcomes and the loose-vermin trace
        for _, l in ipairs(VERMIN.eatsLines()) do print(l) end
    elseif sub == 'forage' then   -- v7.1 (R21): vermin eaters drawn to real vermin
        local k, v = args[3], args[4]
        local ve = c.vermin_eat
        local NUM = { cadence = { 200, 50000, true }, radius = { 3, 60, true }, budget = { 1, 64, true }, cooldown = { 0, 100000, true },
                      chance = { 0, 1 }, colony = { 0, 1 }, diversity = { 0, 10 } }
        if k == 'on' or k == 'off' then
            ve.forage = (k == 'on'); saveConfig(c); LEDGER.add('edit', '', 'vermin foraging %s', k)
            VERMIN.forageSchedule(c)
        elseif k == 'log' and (v == 'on' or v == 'off') then ve.log = (v == 'on'); saveConfig(c)
        elseif k and NUM[k] and tonumber(v) and tonumber(v) >= NUM[k][1] and tonumber(v) <= NUM[k][2] then
            ve[k] = NUM[k][3] and math.floor(tonumber(v)) or tonumber(v); saveConfig(c)
            LEDGER.add('edit', '', 'vermin forage %s %s', k, v)
            if k == 'cadence' and CACHE.vforage then CACHE.vforage.nextDraw = 0 end
        elseif k == 'now' then
            CACHE.cfg = c
            print(('vermin forage: %d eater(s) drawn now'):format(VERMIN.forageRun(true)))
            CACHE.cfg = nil
        elseif k then
            print('usage: seasonal-wildlife vermin forage [on|off|now|log on|off|cadence 200-50000|radius 3-60|budget 1-64|chance 0-1|cooldown 0-100000|colony 0-1|diversity 0-10]') return
        end
        print(VERMIN.forageStatus(c))
    elseif sub == 'defaults' then
        local n, cold = VERMIN.applyDefaults(c, pool, biomeSet); saveConfig(c)
        print(('vermin: seasonal defaults set on %d species by family%s'):format(n, cold and ' (cold embark: insects summer-autumn)' or ''))
    elseif sub and VERMIN.LABEL[sub] then
        local row
        for _, r in ipairs(VERMIN.rows(c, pool)) do if r.family == sub then row = r end end
        if not row then print(('vermin: no %s on this embark'):format(sub)) return end
        local what = args[3]
        if what == 'on' or what == 'off' then
            VERMIN.setAllow(c, row, what == 'on'); saveConfig(c)
            print(('vermin %s: %d species %s'):format(sub, row.n, what == 'on' and 'allowed' or 'blocked'))
        elseif what == 'seasons' and args[4] then
            local arr = VERMIN.parseSeasons(args[4])
            if not arr then print('usage: seasonal-wildlife vermin <family> seasons <all|none|SpSuAuWi codes>') return end
            VERMIN.setSeasons(c, row, arr); saveConfig(c)
            print(('vermin %s: %d species -> seasons %s'):format(sub, row.n, VERMIN.seasonLabel(table.concat(arr, ','))))
        elseif what == 'abundance' and tonumber(args[4]) then
            VERMIN.setAbundance(c, row, tonumber(args[4])); saveConfig(c)
            print(('vermin %s: %d species abundance %d'):format(sub, row.n, math.floor(tonumber(args[4]))))
        elseif what then
            print('usage: seasonal-wildlife vermin <family> [on|off|seasons <all|none|SpSuAuWi>|abundance N]') return
        else
            print(VERMIN.rowText(row))
            for _, e in ipairs(row.entries) do
                print(('  %-28s %-7s %-7s seasons %-6s abundance %d'):format(e.key, e.layer, isAllowed(c, e) and 'allowed' or 'blocked', seasonLabel(c, e.key), weightOf(c, e.key)))
            end
        end
    elseif sub then
        print('usage: seasonal-wildlife vermin [classes | class <SWV_X> on|off | edges [rules|edges|both] | census | eats | forage ... | defaults | <family> [on|off|seasons <all|none|SpSuAuWi>|abundance N]]   families: ' .. table.concat(VERMIN.FAMILIES, ' ')) return
    else
        local rows = VERMIN.rows(c, pool)
        if #rows == 0 then print('vermin: none managed on this embark (are the layers on?)') return end
        print(('%-9s %-26s %3s %7s  %-6s %-5s %s'):format('FAMILY', '', 'n', 'allowed', 'SEASON', 'ab', 'LAYERS'))
        for _, r in ipairs(rows) do print(VERMIN.rowText(r)) end
        print(VERMIN.coldEmbark(biomeSet) and 'cold embark: `vermin defaults` gives land insects summer-autumn' or 'defaults: land insects spring-autumn; mammals, fish, caverns and water all year')
    end
elseif cmd == 'irruption' then   -- v6.1.0; v7.1 (irruption stream): IRRUPT v2's verbs (IRRUPT.USAGE)
    IRRUPT.verb(args)
elseif cmd == 'undo' then   -- v5.11.4
    if not dfhack.isMapLoaded() then print('undo: no map loaded') return end
    local c = loadConfig()
    local label, left = UNDO.pop(c)
    if not label then print('undo: nothing to undo') return end
    saveConfig(c)
    UNDO.after(c)   -- v7.1 (Alpha Four 6.13): the raws, jobs and season stocks follow the restored config
    print(('undid: %s  (%d more to undo)'):format(label, left))
elseif cmd == 'preset' then   -- v5.11.3
    if not dfhack.isMapLoaded() then print('preset: no map loaded') return end
    local c = loadConfig(); captureDefault(c)
    local pool, biomeSet = buildPool(c)
    local name, allowed, seasons, layerNote = applyPreset(c, pool, biomeSet); saveConfig(c)
    enableSched(); applyLive(loadConfig(), df.global.cur_season)
    print(('preset %s: %d species active, one season each on %d; %s; seasonal rotation on'):format(name, allowed, seasons, layerNote))
elseif cmd == 'ledger' then
    if args[2] == 'clear' then LEDGER.clear(); print('ledger cleared'); return end
    local n, kind, layer = 20, nil, nil
    for i = 2, #args do
        local a = args[i]
        if tonumber(a) then n = math.max(1, math.floor(tonumber(a)))
        elseif a == 'land' or a == 'water' or a == 'cavern' then layer = a
        else kind = a end
    end
    local lines, total = LEDGER.lines(n, kind, layer)
    for _, l in ipairs(lines) do print(l) end
    print(('ledger: %d of %d recorded shown%s%s'):format(#lines, total, kind and ('  kind=' .. kind) or '', layer and ('  layer=' .. layer) or ''))
elseif cmd == 'layer' then
    local c = loadConfig()
    if args[2] and c.layers[args[2]] ~= nil and (args[3] == 'on' or args[3] == 'off') then
        c.layers[args[2]] = (args[3] == 'on')
        if args[2] == 'water' then c.water.layer_set = true end   -- v7.1 (fixes): the player's choice; the map no longer decides
        if dfhack.isMapLoaded() then ROSTER.normalize(c, buildPool(c)) end   -- v6.3.0: a layer's species join the roster whole
        saveConfig(c); LEDGER.add('edit', args[2], 'layer %s', args[3])
    end
    local ls = {}; for _, k in ipairs(LAYERS) do ls[#ls+1] = k .. '=' .. (c.layers[k] and 'on' or 'off') end
    print('layers: ' .. table.concat(ls, '  ') .. (args[2] and c.layers[args[2]] == nil and ('  (no layer named ' .. tostring(args[2]) .. ')') or ''))
elseif cmd == 'caverns' then
    if not dfhack.isMapLoaded() then print('caverns: no map loaded') return end
    if args[2] == 'survey' then local c = CAVE.get(true); print(('caverns: survey re-run in %d ms'):format(c.ms or 0)) end
    print(CAVE.status())
elseif cmd == 'stock' or cmd == 'odds' or cmd == 'size' or cmd == 'call' then
    -- v6.5.0 (W4, W5, W10): per species -- `stock KEY [N|clear]`, `odds KEY [N|clear]`, `size KEY [N|clear]`,
    -- `call KEY`. KEY is the Roster's key: TOKEN on land, water:TOKEN, cavern:TOKEN, deep:TOKEN.
    if not dfhack.isMapLoaded() then print(cmd .. ': no map loaded') return end
    local c = loadConfig()
    local key, v = args[2], args[3]
    local pool = buildPool(c)
    local e
    for _, x in ipairs(pool) do if x.key == key and x.inEmbark then e = x end end
    if not e then print(('usage: seasonal-wildlife %s <KEY> %s   (KEY as the Roster shows it: TOKEN, water:TOKEN, cavern:TOKEN, deep:TOKEN)'):format(cmd, cmd == 'call' and '' or '[N|clear]')) return end
    if e.locked then print(e.token .. ' is left to DF (a special creature)') return end
    if cmd == 'call' then
        local g = loadGroups(); local ok, why = ENGINE.call(c, g, e); saveGroups(g)
        print((ok and 'called %s: %s' or 'cannot call %s: %s'):format(e.token, why)) return
    end
    local field = (cmd == 'size') and 'group_size' or cmd
    if v == 'clear' then c[field][key] = nil
    elseif tonumber(v) and tonumber(v) >= (cmd == 'stock' and 0 or 1) then c[field][key] = math.floor(tonumber(v))
    elseif v then print(('usage: seasonal-wildlife %s %s [N|clear]'):format(cmd, key)) return end
    if v then
        saveConfig(c); LEDGER.add('edit', e.layer, '%s %s %s', key, cmd, c[field][key] and tostring(c[field][key]) or 'back to the raws')
        if cmd == 'stock' and c[field][key] and ROSTER.wants(c, key, df.global.cur_season) then RESERVE.set(key, c[field][key]) end
        if cmd == 'odds' and c.enabled then CAVERN.apply(c, df.global.cur_season) end
        if cmd == 'size' and c.enabled then PATTERN.sizeApply(c) end
    end
    local L = speciesDetail(c, pool, e)
    for _, l in ipairs(L) do if l:find('^' .. (cmd == 'size' and 'group size' or cmd)) then print(l) end end
elseif cmd == 'roster' or cmd == 'seasons' then
    -- v6.8.0 (the browser companion; user 29 Sep): the Roster's two edits from the console, under the one rule.
    --   roster                       counts per layer: active, inactive, in season now
    --   roster KEY [active|inactive] a species' state; activation gives exactly one season (its default)
    --   seasons KEY <SpSuAuWi|all>   set its seasons; an inactive species given seasons becomes active;
    --                                'none' is refused -- the way to keep a species away is `roster KEY inactive`
    -- Each edit is one undo step and one ledger line, as in the window, and applies at once when rotation is on.
    if not dfhack.isMapLoaded() then print(cmd .. ': no map loaded') return end
    local c = loadConfig()
    local pool = buildPool(c)
    local key, v = args[2], args[3]
    -- v7.0.0 (roster port, item 5): `roster build [layer]` runs the guild-first roster builder (ROSTER.build)
    -- for one layer (default land), behind the v7 'builder' switch; with it off the matrix/manual roster below
    -- is still the only path. Prints the filled/unfilled slots, any pair seeded to break a stall, any isolate
    -- dropped or kept by the vegetation link, the FREQUENCY ladder it wrote, and the vegetation/deep-water
    -- surveys behind it (items 30, 18). One undo step, like every other roster edit.
    if cmd == 'roster' and key == 'build' then
        if not V7.on(c, 'builder') then print("roster build: the 'builder' switch is off (v7 builder=false)") return end
        local layerArg = v or 'land'
        if not ROSTER.SLOTS[layerArg] then
            print('usage: seasonal-wildlife roster build [land|flying|water|cavern]') return
        end
        local before = loadConfig()
        local res = ROSTER.build(c, layerArg)
        if not res.ok then print('roster build: ' .. (res.why or 'failed')) return end
        print(('roster build %s -- seed %s%s'):format(res.layer, res.seed or '(none)',
            res.realm and (', realm ' .. res.realm) or ''))
        for _, sl in ipairs(res.slots) do
            print(('  %-3s %d (min %d, max %d)  %s'):format(sl.code, sl.have, sl.min, sl.max,
                (#sl.members > 0) and table.concat(sl.members, ', ') or '(empty)'))
        end
        for _, u in ipairs(res.unfilled) do
            print(('  UNFILLED %-3s needs %d, have %d -- %s'):format(u.code, u.min, u.have, u.reason))
        end
        if res.pairs_seeded > 0 then print(('  %d predator-prey pair(s) seeded to break a stall'):format(res.pairs_seeded)) end
        for _, d in ipairs(res.dropped) do
            print(('  dropped %s (isolated, no link)%s'):format(d.token, d.replaced_by and (' -- replaced by ' .. d.replaced_by) or ''))
        end
        for _, vg in ipairs(res.veg_linked) do
            print(('  %s kept by the vegetation link (needs %.0f, map index %.0f)'):format(vg.token, vg.need, vg.index))
        end
        -- v7.0.0 (item 23): always warn, loudly, on every seated outgunned pair -- already logged to the ledger
        -- by ROSTER.build itself; this is the console echo of the same list.
        for _, og in ipairs(res.outgunned) do
            print(('  OUTGUNNED: %s pack vs %s herd %.1fx%s'):format(og.pred, og.prey, og.factor,
                V7.on(c, 'outgun_cap') and (' -- capped to ' .. tostring(c.group_size[og.prey_key] or '?')) or ''))
        end
        local lkeys = {}
        for lk in pairs(res.ladder) do lkeys[#lkeys+1] = lk end
        table.sort(lkeys)
        -- v7.1: the ladder's target and what it predicts (R34, R59), machine-readable for the validator
        local li = res.ladder_info
        print(('  ladder-info target=%s units=%s herb=%.3f carn=%.3f binding=%s carn_waves=%.3f carn_units=%.3f biomass_c_over_h=%.3f floored=%s')
            :format(li.target, tostring(li.units), li.uH, li.uC, (li.binding:gsub(' ', '_')), li.wavesC, li.unitsC, li.biomassC,
                #li.floored > 0 and table.concat(li.floored, ',') or '-'))
        for tok, a in pairs(li.apex) do print(('  apex %s: FREQUENCY %s (no ladder step; the apex scheduler places it)'):format(tok, tostring(a))) end
        print('  ladder:')
        for _, lk in ipairs(lkeys) do print(('    %-24s %d'):format(lk, res.ladder[lk])) end
        print(('  gobble edges: %d over %d vermin (`roster gobble %s`)'):format(#res.gobble.edges, #res.gobble.vermin, layerArg))
        if res.deep then print(('  column depth: %d of %d sampled ocean column(s) hold %d or more stacked water tiles'):format(res.deep.n, res.deep.total, res.deep.need)) end   -- R22
        print(('  vegetation index %.0f (region %.0f, grass %.0f%% of %d surface tiles, %d shrub, %d tree)%s'):format(
            res.veg.index or 0, res.veg.region or 0, res.veg.grassShare or 0, res.veg.floor or 0, res.veg.shrubs or 0, res.veg.trees or 0,
            res.veg.stopped and ' (survey budget hit, partial)' or ''))
        if res.deactivated > 0 then print(('  %d previously-active %s species deactivated (not selected by the builder)'):format(res.deactivated, layerArg)) end
        UNDO.push(before, 'roster build ' .. layerArg)
        saveConfig(c)
        if c.enabled then applyLive(c, df.global.cur_season) end
        return
    end
    -- v7.0.0 (item 23): `roster outgun [layer]` lists every outgunned pair in the embark's pool (ROSTER.linkablePool,
    -- any slot) without seating, dropping or writing anything -- a read-only survey, unlike `roster build`'s check
    -- which only looks at the pairs it actually seated.
    if cmd == 'roster' and key == 'outgun' then
        local layerArg = v or 'land'
        if not ROSTER.SLOTS[layerArg] then
            print('usage: seasonal-wildlife roster outgun [land|flying|water|cavern]') return
        end
        local cands = ROSTER.linkablePool(pool, layerArg, c)
        local pairs_ = ROSTER.outgunPairs(c, cands, layerArg)
        if #pairs_ == 0 then print(('roster outgun %s -- none found'):format(layerArg)) return end
        print(('roster outgun %s -- %d pair(s) (factor >= %.1f)'):format(layerArg, #pairs_, V7.on(c, 'outgun') or 2.0))
        for _, pr in ipairs(pairs_) do
            print(('  outgunned: %s pack vs %s herd %.1fx'):format(pr.pred.token, pr.prey.token, pr.factor))
        end
        return
    end
    -- v7.1 (roster stream): the apex scheduler, the GOBBLE edge table, cavern depth, the curated water apexes and
    -- the roster knobs. Kept in a function of its own (ROSTER.verb) so this branch stays small for the merge.
    if cmd == 'roster' and (key == 'apex' or key == 'gobble' or key == 'depth' or key == 'aquatic' or key == 'set' or key == 'water') then
        return ROSTER.verb(c, pool, args)
    end
    if cmd == 'roster' and not key then
        local n = {}
        for _, e in ipairs(pool) do
            if e.inEmbark and not e.locked then
                local r = n[e.layer] or { a = 0, i = 0, now = 0 }; n[e.layer] = r
                if isAllowed(c, e) then r.a = r.a + 1; if inSeason(c, e.key, df.global.cur_season) then r.now = r.now + 1 end else r.i = r.i + 1 end
            end
        end
        for _, l in ipairs(LAYERS) do
            if n[l] then print(('roster %-7s %3d active (%d in season now), %3d inactive'):format(l, n[l].a, n[l].now, n[l].i)) end
        end
        return
    end
    local e
    for _, x in ipairs(pool) do if x.key == key and x.inEmbark then e = x end end
    if not e then print(('usage: seasonal-wildlife %s <KEY> %s   (KEY as the Roster shows it: TOKEN, water:TOKEN, cavern:TOKEN, deep:TOKEN)')
        :format(cmd, cmd == 'roster' and '[active|inactive]' or '<SpSuAuWi|all>')) return end
    if e.locked then print(e.token .. ' is left to DF (a special creature)') return end
    local before, label = loadConfig(), nil
    if cmd == 'roster' and (v == 'active' or v == 'inactive') then
        local on = (v == 'active')
        if isAllowed(c, e) ~= on then
            ROSTER.setActive(c, pool, e, on, on and 'you: active (console)' or 'you: inactive (console)')
            label = 'active/inactive'
            LEDGER.add('edit', e.layer, '%s %s%s', e.key, v, on and (', ' .. seasonLabel(c, e.key)) or '')
        end
    elseif cmd == 'seasons' and v then
        if v == 'none' then print(('seasons: an active species keeps at least one season; to keep %s away: seasonal-wildlife roster %s inactive'):format(e.token, e.key)) return end
        local arr = VERMIN.parseSeasons(v)
        if not arr then print(('usage: seasonal-wildlife seasons %s <SpSuAuWi|all>   e.g. SpAu, Wi, all'):format(e.key)) return end
        if not isAllowed(c, e) then c.allow[e.key] = true end
        setAssign(c, e.key, arr); whySet(c, e.key, 'you: seasons (console)')
        label = 'seasons'
        LEDGER.add('edit', e.layer, '%s seasons %s', e.key, seasonLabel(c, e.key))
        -- v6.9.0: DF never brings a species in a season its raws forbid (ECO T2) -- say so rather than let the roster lie
        local barred = {}
        for _, s in ipairs(arr) do if e.noSeason and e.noSeason[s] then barred[#barred+1] = SEASON[s] end end
        if #barred > 0 and not V7.on(c, 'seasons_own') then print(('note: %s has NO_%s in its raws; DF will not bring it then, whatever the roster says')
            :format(e.token, table.concat(barred, '/NO_'):upper())) end
    elseif v then
        print(('usage: seasonal-wildlife %s %s %s'):format(cmd, e.key, cmd == 'roster' and '[active|inactive]' or '<SpSuAuWi|all>')) return
    end
    if label then
        UNDO.push(before, label)
        saveConfig(c)
        if c.enabled then applyLive(c, df.global.cur_season) end
    end
    print(('%s %s, seasons %s%s  [guild: %s]'):format(e.key, isAllowed(c, e) and 'active' or 'inactive', seasonLabel(c, e.key),
        label and '' or (v and '  (no change)' or ''), MODEL.GUILD_NAME[e.guild or ''] or '?'))
elseif cmd == 'curious' then   -- v6.9.0: curious beasts as thieves (DF's way) or residents (CURIOUS)
    local c = loadConfig()
    local tok, mode = args[2], args[3]
    -- v7.1 (scav, R30): `curious reform [on|off|now]`, `curious loot drop|keep`, `curious set KEY N`, `curious status`
    if tok == 'reform' or tok == 'loot' or tok == 'set' or tok == 'status' then
        if tok == 'reform' and (mode == 'on' or mode == 'off') then
            c.curious.reform = (mode == 'on'); saveConfig(c); LEDGER.add('edit', '', 'curious reform %s', mode)
            if dfhack.isMapLoaded() then
                if mode == 'off' then local n = CURIOUS.unreform(); if n > 0 then print(('restored %d reformed curious beasts'):format(n)) end end
                CURIOUS.schedule(c)
            end
        elseif tok == 'reform' and mode == 'now' then
            if not dfhack.isMapLoaded() then print('curious: no map loaded') return end
            CACHE.cfg = nil
            print(('curious: %d reformed this pass'):format(CURIOUS.pass()))
            if not (c.enabled and CURIOUS.on(c)) then print('  (nothing runs while the tool is disabled or reform is off: `seasonal-wildlife enable`, `curious reform on`)') end
        elseif tok == 'loot' and (mode == 'drop' or mode == 'keep') then
            c.curious.loot = mode; saveConfig(c); LEDGER.add('edit', '', 'curious loot %s', mode)
        elseif tok == 'set' and CURIOUS.RANGE[mode or ''] and tonumber(args[4]) then
            local r, v = CURIOUS.RANGE[mode], math.floor(tonumber(args[4]))
            if v < r[1] or v > r[2] then print(('curious: %s must be %d-%d'):format(mode, r[1], r[2])) return end
            c.curious[mode] = v; saveConfig(c); LEDGER.add('edit', '', 'curious %s %d', mode, v)
            if mode == 'cadence' and dfhack.isMapLoaded() then CURIOUS.schedule(c) end
        elseif tok ~= 'status' then
            local ks = {}; for k in pairs(CURIOUS.RANGE) do ks[#ks+1] = k end; table.sort(ks)
            print('usage: seasonal-wildlife curious reform [on|off|now] | loot drop|keep | set <' .. table.concat(ks, '|') .. '> N | status') return
        end
        print(CURIOUS.status(c))
        return
    end
    if tok and (mode == 'resident' or mode == 'thief') then
        local cr = CAVERN.rawFor(tok)
        if not cr then print('curious: no creature ' .. tok) return end
        if not CURIOUS.is(cr) then print(('curious: %s is not a curious beast (no CURIOUSBEAST_EATER/ITEM/GUZZLER)'):format(tok)) return end
        c.curious.resident[tok] = (mode == 'resident') or nil; saveConfig(c)
        LEDGER.add('edit', '', '%s curious beast: %s', tok, mode)
        if dfhack.isMapLoaded() then CURIOUS.apply(c) end
    elseif tok then print('usage: seasonal-wildlife curious [TOKEN resident|thief]') return end
    local list = {}
    for t in pairs(c.curious.resident) do list[#list+1] = t end
    table.sort(list)
    print(('curious beasts kept as residents (flags cleared while the tool runs): %s'):format(#list > 0 and table.concat(list, ' ') or 'none -- all steal and leave, as DF does'))
    print(CURIOUS.status(c))   -- v7.1 (scav, R30)
elseif cmd == 'scavenge' then   -- v6.9.0: scavenging (SCAV)
    local c = loadConfig()
    if args[2] == 'on' or args[2] == 'off' then
        c.scavenge.enabled = (args[2] == 'on'); saveConfig(c); LEDGER.add('edit', '', 'scavenging %s', args[2])
        if dfhack.isMapLoaded() then SCAV.schedule(c) end
    elseif args[2] == 'radius' and tonumber(args[3]) and tonumber(args[3]) >= 3 then
        c.scavenge.radius = math.floor(tonumber(args[3])); saveConfig(c)
    elseif args[2] == 'now' then
        if not dfhack.isMapLoaded() then print('scavenge: no map loaded') return end
        CACHE.cfg = nil; local was = c.scavenge.enabled; c.scavenge.enabled = true; CACHE.cfg = c
        local n = SCAV.run(); c.scavenge.enabled = was; CACHE.cfg = nil
        local why = CACHE.scavLast and CACHE.scavLast.why   -- v7.1: a no-op says why (SCV2 ran vacuous, tool off)
        print(('scavenge: %d eaten%s'):format(n, why and (' (nothing ran: ' .. why .. ')') or ''))
    -- v7.1 (scav, R16/R18/R42): natural cadence, swimmers, the kleptoparasite wait, every timing, the attribution
    elseif (args[2] == 'natural' or args[2] == 'swimmers' or args[2] == 'defer') and (args[3] == 'on' or args[3] == 'off') then
        local k = args[2] == 'defer' and 'defer_larger' or args[2]
        c.scavenge[k] = (args[3] == 'on'); saveConfig(c); LEDGER.add('edit', '', 'scavenging %s %s', args[2], args[3])
        if k == 'swimmers' then CACHE.scavKind = nil end
    elseif args[2] == 'set' and SCAV.RANGE[args[3] or ''] and tonumber(args[4]) then
        local r, v = SCAV.RANGE[args[3]], tonumber(args[4])
        if v < r[1] or v > r[2] then print(('scavenge: %s must be %g-%g (%s)'):format(args[3], r[1], r[2], r[3])) return end
        c.scavenge[args[3]] = v; saveConfig(c); LEDGER.add('edit', '', 'scavenging %s %g', args[3], v)
        if args[3] == 'cadence' and dfhack.isMapLoaded() then SCAV.schedule(c) end
    elseif args[2] == 'keys' or (args[2] == 'set' and not args[3]) then
        local ks = {}; for k in pairs(SCAV.RANGE) do ks[#ks+1] = k end; table.sort(ks)
        for _, k in ipairs(ks) do local r = SCAV.RANGE[k]; print(('  %-18s %-8g %g-%g  %s'):format(k, SCAV.num(c, k), r[1], r[2], r[3])) end
        return
    elseif args[2] == 'stats' then
        if not dfhack.isMapLoaded() then print('scavenge: no map loaded') return end
        if args[3] == 'reset' then
            local st = SCAV.state(); st.stats = { by = {}, pairs = {}, since = absTick() }; st.fallbacks = {}; st.dirty = true; SCAV.saveStats(st)
            LEDGER.add('edit', '', 'scavenging counters reset')
        end
        for _, l in ipairs(SCAV.statsLines()) do print(l) end
        return
    elseif args[2] then print('usage: seasonal-wildlife scavenge [on|off|now|radius N|natural on|off|swimmers on|off|defer on|off|set KEY N|keys|stats [reset]]') return end
    print(SCAV.status(c))
elseif cmd == 'sponges' then   -- v7.0.0: `sponges` status, `sponges now` tops the ribbons up at once
    local c, g = loadConfig(), loadGroups()
    if args[2] == 'now' then
        local n = V7.spongeTick(c, g, true)
        saveGroups(g)
        if n == nil and not V7.on(c, 'sponges') then print('sponges are off (`seasonal-wildlife v7 sponges on`)')
        elseif n == nil and not c.layers.water then print('the water layer is off')
        else print(('sponges: %s'):format((g.sponges or {}).last or 'nothing to place')) end
    end
    print(V7.spongeStatus(c, g))
elseif cmd == 'realm' then   -- v7.0.0 (item 21): the embark's realm for the geography filter (v7 `realms` switch)
    local c = loadConfig()
    local v = args[2]
    if v == 'table' then   -- v7.1 (R57): the realm table for a validator, one line per entry
        local head, lines = ROSTER.realmTable(c)
        print(head)
        for _, l in ipairs(lines) do print(l) end
        return
    end
    if not v then
        local cur = c.realm
        if not cur or cur == '' then print('realm: unset (`seasonal-wildlife realm <name|auto|off>`)')
        elseif cur == 'auto' then
            if dfhack.isMapLoaded() then
                local picked = V7.autoRealm(buildPool(c))
                print(('realm: auto -> %s'):format(picked or '(no match in the embark pool)'))
            else print('realm: auto (no map loaded to resolve it)') end
        else print('realm: ' .. cur) end
        if not V7.on(c, 'realms') then print("  (the 'realms' switch is off -- `seasonal-wildlife v7 realms on`)") end
        return
    end
    if v == 'off' then c.realm = ''; saveConfig(c); LEDGER.add('edit', '', 'realm off'); print('realm: off'); return end
    if v == 'auto' then c.realm = 'auto'; saveConfig(c); LEDGER.add('edit', '', 'realm auto'); print('realm: auto'); return end
    local code = v:upper()
    local known = false
    for _, r in ipairs(V7.REALM_ORDER) do if r == code then known = true; break end end
    if not known then
        print(('usage: seasonal-wildlife realm <name|auto|off>   name is one of: %s'):format(table.concat(V7.REALM_ORDER, ', ')))
        return
    end
    c.realm = code; saveConfig(c); LEDGER.add('edit', '', 'realm %s', code); print('realm: ' .. code)
elseif cmd == 'v7' then   -- v7.0.0: the v7 switches; `v7 KEY on|off|N`, `v7 fisher TOKEN on|off`, `v7 apply`
    local c = loadConfig()
    local k, v = args[2], args[3]
    if k == 'fisher' and args[3] and (args[4] == 'on' or args[4] == 'off') then
        c.v7.fisher_list[args[3]] = (args[4] == 'on') or nil; saveConfig(c)
        LEDGER.add('edit', '', 'v7 fisher %s %s', args[3], args[4])
    elseif k == 'layer_groups' then   -- v7.1 (R7): retired; every layer always counts its own groups
        print('v7 layer_groups: retired in v7.1 -- every layer always has its own limit (R7); the one toggle is `limits formula` / `limits fixed N`')
        return
    elseif k and k ~= 'apply' and c.v7[k] ~= nil and type(c.v7[k]) ~= 'table' then
        if type(c.v7[k]) == 'boolean' and (v == 'on' or v == 'off') then c.v7[k] = (v == 'on')
        elseif type(c.v7[k]) == 'number' and tonumber(v) and tonumber(v) >= 0 and tonumber(v) <= 10 then c.v7[k] = tonumber(v)
        else print(('usage: seasonal-wildlife v7 %s %s'):format(k, type(c.v7[k]) == 'boolean' and 'on|off' or '<0..10>')) return end
        saveConfig(c); LEDGER.add('edit', '', 'v7 %s %s', k, v)
    elseif k and k ~= 'apply' then print('usage: seasonal-wildlife v7 [KEY on|off|N | fisher TOKEN on|off | apply]') return end
    if k and dfhack.isMapLoaded() then
        CACHE.cfg = nil; CACHE.class = {}; CACHE.align = nil; CACHE.predset = nil
        print(c.enabled and V7.apply(loadConfig()) or 'v7: rotation is off, so no raw is written')
    end
    local keys = {}
    for kk in pairs(c.v7) do keys[#keys+1] = kk end
    table.sort(keys)
    for _, kk in ipairs(keys) do
        local x = c.v7[kk]
        if type(x) == 'table' then local t = {}; for tok in pairs(x) do t[#t+1] = tok end; table.sort(t); x = table.concat(t, ' ') end
        print(('  %-13s %s'):format(kk, tostring(x)))
    end
    if dfhack.isMapLoaded() then
        local ok, a = pcall(V7.alignment)
        if ok and a then print(('  embark alignment: %s%s (%d region tiles read)'):format(a.good and 'good' or '', a.evil and ' evil' or (a.good and '' or 'neutral'), a.tiles)) end
    end
elseif cmd == 'perf' then V7.PERF.verb(args, dispatch)   -- v7.1 (perf stream, P0): job ms/KB, worst tick, DFHack perf counters, switches
elseif cmd == 'extinct' then V7.EXTINCT.verb(args)   -- v7.1 (extinct stream, R24): extinct tag corrections
elseif cmd == 'hunters' then V7.H.verb(args)   -- v7.1 (ecology stream): skill profiles, packs, stoop, fishing, cohesion
elseif cmd == 'aquarium' then V7.AQ.verb(args)   -- v7.1 (aquarium stream): the lens, legend, waves, veil and the translucent-water mod
elseif cmd == 'exhaust' then   -- v6.9.0: exhaustion and niche replacement (ROSTER.exhaust*)
    local c = loadConfig()
    if args[2] == 'on' or args[2] == 'off' then
        c.exhaust.enabled = (args[2] == 'on'); saveConfig(c); LEDGER.add('edit', '', 'exhaustion watch %s', args[2])
    elseif args[2] == 'now' then
        if not dfhack.isMapLoaded() then print('exhaust: no map loaded') return end
        print(('exhaust: %d replacement(s) made'):format(ROSTER.exhaustCheck(c, df.global.cur_season)))
    elseif args[2] then print('usage: seasonal-wildlife exhaust [on|off|now]') return end
    print(ROSTER.exhaustStatus(c))
elseif cmd == 'alerts' then   -- v6.9.0: quiet wildlife fights (ALERTS)
    local c = loadConfig()
    if args[2] == 'on' or args[2] == 'off' then
        c.alerts.quiet_wildlife = (args[2] == 'on'); saveConfig(c); LEDGER.add('edit', '', 'quiet wildlife fights %s', args[2])
        if dfhack.isMapLoaded() then ALERTS.schedule(c) end
    elseif args[2] then print('usage: seasonal-wildlife alerts [on|off]') return end
    print(('quiet wildlife fights: %s (combat alerts with no humanoid in them are dropped)'):format(c.alerts.quiet_wildlife and 'on' or 'off'))
elseif cmd == 'hunting' then   -- v6.6.0 (W6): the vermin-hunting flags
    local c = loadConfig()
    if args[2] == 'on' or args[2] == 'off' then
        c.hunting.enabled = (args[2] == 'on'); saveConfig(c); LEDGER.add('edit', '', 'vermin hunting %s', args[2])
        if dfhack.isMapLoaded() then
            local _, species, wrote = HUNT.apply(c)
            if args[2] == 'on' then print(('vermin hunting: %d species, %d caste flag(s) written'):format(species or 0, wrote or 0)) end
        end
    elseif args[2] then print('usage: seasonal-wildlife hunting [on|off]') return end
    print(HUNT.status(c))
elseif cmd == 'sendoff' then   -- v6.5.0 (W10): every gated group of a layer walks off; DF may send the next
    if not dfhack.isMapLoaded() then print('sendoff: no map loaded') return end
    local layer = args[2] or 'land'
    if layer ~= 'land' and layer ~= 'cavern' then print('usage: seasonal-wildlife sendoff [land|cavern]') return end
    local g = loadGroups(); local n = ENGINE.sendOff(g, layer); saveGroups(g)
    LEDGER.add('dismiss', layer, 'sent off %d gated group(s); the gate is open', n)
    print(('sent off %d gated %s group(s); the gate is open'):format(n, layer))
elseif cmd == 'enable' and args[2] == 'rotation' then enableSched(); LEDGER.add('edit', '', 'rotation enabled'); print('enabled (rotation only)')
elseif cmd == 'enable' then
    for _, l in ipairs(PANEL.enableAll()) do print(l) end
    print('enabled: every feature on (`seasonal-wildlife disable` stops it; the gui Panel tab switches each one)')
elseif cmd == 'disable' then disableSched(); LEDGER.add('edit', '', 'rotation disabled'); print('disabled')
else print('Usage: seasonal-wildlife [gui|status|now|enable|disable|preset|undo|layer land|water|cavern on|off|limits [formula|fixed N|LAYER ceiling N]|groups [on|off|layers|adopt IDS|clock ...|cavern ...|panic ...|natives ...|apcap N|coupling ...|pack N|cohesion ...|ecology ...|livestock ...|nudge ...|hold TOKEN DAYS|dismiss TOKEN]|water [on|off|now [BODY]|scan|bodies ...|layer auto|on|off|spill ...|survey|depth|mix ...|pull ...|levels N|aquatic on|off|budget MS|retry D|countdown N]|place TOKEN [n] [LAYER]|stock|odds|size KEY [N|clear]|call KEY|sendoff [land|cavern]|roster [KEY [active|inactive]|build|outgun|apex ...|gobble|depth ...|aquatic ...|set ...]|seasons KEY <SpSuAuWi|all>|pattern [LAYER] NAME|ledger [N] [kind] [layer]|clear|classes|class TOKEN natural|auto|caverns [survey]|vermin ...|scavenge ...|curious ...|exhaust [on|off|now]|alerts [on|off]|hunting [on|off]|hunters ...|sponges [now]|realm ...|v7 ...|extinct ...|irruption ...|perf ...|aquarium ...]  (TOKEN: the raw id, quoted if it has a space, or SEA_OTTER, or #N; `help seasonal-wildlife` lists every option)') end
end
dispatch(V7.CLI.args({ ... }))   -- v7.1 (fixes): '#N' and underscore forms of spaced raw ids resolved first
